/* 详情包（由 build_index.cjs 生成） */
window.registerDetails("flowers", {"flower-common-sunflower":{"description":"向日葵为一年生高大草本，茎秆粗壮直立，高 1–3 米，全体被短硬毛。叶片宽大呈心形，边缘有粗锯齿，互生。头状花序直径可达 10–30 厘米，外围一圈金黄色舌状花，中央密生管状花，结出的瘦果即常见的葵花籽。\n\n野生向日葵原产北美洲西部草原，喜阳光充足、温暖干燥的环境，根系可深达 1.5 米以上，耐旱而不耐水涝。花期 7–9 月，果期 8–10 月，幼株的花盘会随太阳转动，成熟后则固定朝向东方。种子含油率约 40%–50%，可榨食用油、炒食或作饲料；世界主产区有乌克兰、俄罗斯、阿根廷及中国内蒙古、新疆等地，成片花田也带火了乡村旅游。榨油后的饼粕可作饲料，茎秆还能用于造纸或压制成燃料。","habitat":"开阔草原、路边荒地及农田，喜阳光充足、排水良好的环境","distribution":"原产北美洲，现广泛栽培于中国、俄罗斯、乌克兰、阿根廷等地","conservation":"暂无评估","details":[{"label":"株高","value":"1–3 米，茎秆粗壮直立"},{"label":"花期","value":"7–9 月，单朵花序开放约 7–10 天"},{"label":"果期","value":"8–10 月，成熟花盘因结籽而低垂"},{"label":"光照","value":"喜强光，每天需 6 小时以上直射光"},{"label":"水分","value":"耐旱，苗期需水较多，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的沙壤土，耐轻度盐碱"},{"label":"主要用途","value":"葵花籽榨油与炒食，花盘可作切花观赏"}],"facts":["向日葵幼株的花盘会追随太阳转动，成熟后固定朝东，这一现象称为向光性。","我们看到的“一朵”向日葵其实由数百至上千朵小花组成，外围舌状花不结实。","花盘成熟后因种子增重而低垂，可避免雨水积在盘面导致霉变。","高油品种的种子含油率可达 50%，葵花籽油富含亚油酸。"]},"flower-garden-tulip":{"description":"郁金香为百合科郁金香属多年生球根草本，株高 30–60 厘米，地下具卵形鳞茎。每株通常有叶 3–5 枚，宽披针形、灰绿色，表面被白粉。花单生茎顶，花被片 6 枚，呈杯状、碗状或百合状，有红、黄、粉、白、紫及复色，花期 3–5 月，果期 5–6 月，蒴果三棱状。\n\n郁金香原产中亚天山、帕米尔高原一带，喜冬季冷凉湿润、夏季干燥的环境，需经过低温春化才能正常开花，适宜在疏松、排水良好的沙质土壤中栽培。17 世纪荷兰掀起“郁金香狂热”，一枚稀有球茎的价格一度被炒到相当于一栋豪宅，如今荷兰仍是世界最大的郁金香生产国。鳞茎含秋水仙碱，误食会引起中毒，栽培以观赏和切花为主，公园花展中常成片布置成色带。","habitat":"草原、山坡及林缘，喜冷凉干燥、阳光充足的环境","distribution":"原产中亚天山与帕米尔高原，荷兰、土耳其及中国新疆等地广泛栽培","conservation":"暂无评估","details":[{"label":"株高","value":"30–60 厘米"},{"label":"花期","value":"3–5 月，单朵花开放约 10–15 天"},{"label":"果期","value":"5–6 月，蒴果三棱状"},{"label":"光照","value":"喜光，生长期需充足阳光"},{"label":"水分","value":"土壤湿润但不积水，休眠期保持干燥"},{"label":"土壤","value":"疏松、排水良好的沙质壤土，忌黏重"},{"label":"繁殖","value":"以分球为主，也可播种"}],"facts":["荷兰“郁金香狂热”发生于 1634–1637 年，是历史上最早有记载的金融泡沫之一。","郁金香杯状的“花瓣”其实是 6 枚花被片，没有花瓣与花萼之分。","花苞在温暖室内会迅速张开，低温时重新闭合，可据此调节切花状态。","郁金香鳞茎外观像洋葱，却含秋水仙碱，不可食用。"]},"flower-chrysanthemum":{"description":"菊花是菊科菊属多年生宿根草本，株高 60–150 厘米，茎直立，基部常木质化。叶互生，卵形至披针形，边缘有粗大锯齿，叶面被白色短柔毛。头状花序单生或数个聚生茎顶，直径 2–20 厘米，由外围舌状花与中央管状花组成，花型有平瓣、匙瓣、管瓣、畸瓣等，花色涵盖黄、白、红、紫、绿等，花期 9–11 月。\n\n菊花原产中国，已有三千多年的栽培与选育历史，宋代即出现菊谱专著，如今品种数以千计。它喜阳光充足、凉爽通风的环境，为典型的短日照植物，秋季日照缩短后形成花芽；耐寒而不耐酷热，忌积水烂根。菊花可盆栽、地栽或作切花，花可冲泡菊花茶、入药，有清肝明目之说；浙江桐乡、河南开封等地分别以茶菊和菊展闻名，开封菊花会每年吸引大量游客。","habitat":"向阳山坡、草地及庭院，喜凉爽通风、阳光充足的环境","distribution":"原产中国，现遍布世界温带地区，浙江桐乡、河南开封为著名产区","conservation":"暂无评估","details":[{"label":"株高","value":"60–150 厘米，茎直立，基部木质化"},{"label":"花期","value":"9–11 月，分早菊、秋菊与寒菊"},{"label":"果期","value":"10–12 月，瘦果细小"},{"label":"光照","value":"喜光，短日照条件促进花芽分化"},{"label":"水分","value":"喜湿润但忌积水，雨季需及时排水"},{"label":"土壤","value":"疏松肥沃、排水良好的沙壤土"},{"label":"主要用途","value":"观赏、切花、菊花茶及药用"}],"facts":["菊花是短日照植物，秋季昼短夜长才形成花芽，栽培中常通过遮光或补光控制花期。","一个菊花的“花”实为头状花序，由成百上千朵舌状花与管状花组成。","部分菊花品种可耐 0℃ 左右低温，在初霜后仍能持续开放。","开封菊花会与桐乡杭白菊分别以观赏和茶用闻名。"]},"flower-spring-orchid":{"description":"春兰为兰科兰属多年生草本，地生，假鳞茎较小，呈卵球形。叶片 4–6 枚丛生，狭带形，长 20–40 厘米，边缘常具细锯齿，叶色深绿而有光泽。花葶直立，通常一葶一花，偶有两花，花直径 4–6 厘米，花色多为黄绿或淡黄绿色，唇瓣上有紫红色斑点，花期 1–3 月，果期 4–6 月。\n\n春兰分布于中国秦岭以南至广东、广西北部及西南山区，常生于海拔 300–2200 米的疏林下、溪谷旁腐殖质丰富的坡地，喜阴湿通风，忌强光直射和积水。它以清幽的香气和素雅的姿态深受文人喜爱，与梅、竹、菊并称“四君子”，南宋以来兰谱、兰画层出不穷。野生兰属植物已列入中国国家重点保护野生植物名录，采挖和买卖野生兰需遵守相关法规，市售春兰多为人工繁殖。","habitat":"疏林下、溪谷旁及腐殖质丰富的山坡，喜半阴湿润环境","distribution":"中国秦岭以南至西南、华南山区，日本、朝鲜半岛也有分布","conservation":"暂无评估；兰属野生种列入中国国家二级重点保护野生植物","details":[{"label":"株高","value":"叶长 20–40 厘米，花葶高 10–25 厘米"},{"label":"花期","value":"1–3 月，单朵花可开 20–30 天"},{"label":"果期","value":"4–6 月，蒴果长圆形"},{"label":"光照","value":"喜半阴散射光，忌强光直射"},{"label":"水分","value":"喜湿润，要求空气湿度 60% 以上"},{"label":"土壤","value":"疏松透气、富含腐殖质的微酸性土壤"},{"label":"繁殖","value":"以分株为主，也可无菌播种"}],"facts":["春兰并非每年都开花，需假鳞茎积累足够养分并经历低温刺激。","兰花种子细如粉尘且没有胚乳，野外必须与特定真菌共生才能萌发。","春兰的香气来自花瓣中的挥发性芳香物质，清晨与夜间更为明显。","传统上按花瓣形态将兰花分为梅瓣、荷瓣、水仙瓣等品系。"]},"flower-herbaceous-peony":{"description":"芍药为芍药科芍药属多年生草本，株高 60–80 厘米，具粗壮的肉质根，茎丛生。叶为二回三出复叶，小叶椭圆形至披针形，表面有光泽。花单生茎顶或生于叶腋，直径 8–15 厘米，有单瓣、重瓣之分，花色有白、粉、红、紫等，花期 5–6 月，果期 6–8 月，蓇葖果成熟后开裂散出黑色种子。\n\n芍药原产中国北方、朝鲜半岛及西伯利亚一带，喜阳光充足、夏季凉爽的环境，耐寒力强，可耐 -20℃ 低温，适宜在深厚肥沃、排水良好的沙壤土中生长。它与牡丹花形相似，但牡丹为木本、芍药为草本，故有“牡丹为花王、芍药为花相”之说。芍药根经炮制后即为中药白芍，有养血调经之效；山东菏泽、江苏扬州等地以芍药栽培与观赏闻名，春末夏初是重要的园林与切花材料。","habitat":"山坡草地、林缘及庭院，喜阳光充足、排水良好的环境","distribution":"原产中国北方及朝鲜半岛、西伯利亚，山东菏泽、江苏扬州等地广泛栽培","conservation":"暂无评估","details":[{"label":"株高","value":"60–80 厘米，茎丛生"},{"label":"花期","value":"5–6 月，单朵开放 5–7 天"},{"label":"果期","value":"6–8 月，蓇葖果开裂散种"},{"label":"光照","value":"喜光，生长期需充足阳光"},{"label":"水分","value":"喜湿润，忌积水烂根"},{"label":"土壤","value":"深厚肥沃、排水良好的沙壤土"},{"label":"药用价值","value":"根加工后为白芍，养血调经"}],"facts":["芍药与牡丹同属芍药科，但芍药是草本，牡丹是木本，冬季芍药地上部分会枯萎。","芍药的花蕾常分泌黏液，可阻挡蚂蚁等昆虫啃食花蕾。","“芍药”之名早见于《诗经》，古代男女相赠芍药以表惜别之情。","山东菏泽与江苏扬州都以芍药栽培闻名，每年 5 月前后举办花会。"]},"flower-carnation":{"description":"康乃馨即香石竹，为石竹科石竹属多年生宿根草本，株高 40–70 厘米，茎直立，节部膨大，全株被白粉而呈灰绿色。叶线状披针形，对生。花单生或数朵聚生，花径 5–8 厘米，花瓣边缘呈不规则锯齿或皱褶，有白、粉、红、黄、紫及复色，具芳香，自然花期 4–9 月，果期 6–10 月。\n\n康乃馨原产地中海沿岸，喜凉爽干燥、阳光充足的环境，耐寒而不耐炎热，夏季高温时生长缓慢。1907 年美国费城的安娜·贾维斯在母亲追悼会上以白色康乃馨表达思念，此后康乃馨逐渐成为母亲节的象征。它是世界四大切花之一，可露地栽培或温室周年生产；花瓣可提取香精，也用于花茶和食品装饰，但花萼与花心味苦，食用前需去除。","habitat":"地中海沿岸的石灰岩山坡与灌丛，喜凉爽、干燥和充足阳光","distribution":"原产地中海沿岸，现世界各地广泛栽培，中国云南、广东为主要产区","conservation":"暂无评估","details":[{"label":"株高","value":"40–70 厘米，茎节膨大"},{"label":"花期","value":"自然花期 4–9 月，温室可周年开花"},{"label":"果期","value":"6–10 月，蒴果圆柱形"},{"label":"光照","value":"喜充足阳光，光照不足易徒长"},{"label":"水分","value":"喜干燥，忌积水，宜见干见湿"},{"label":"土壤","value":"疏松、富含钙质的微碱性土壤"},{"label":"主要用途","value":"切花、花束、提取香精"}],"facts":["康乃馨是石竹科植物，与石竹、满天星是近亲，花瓣边缘的锯齿是识别特征。","1907 年安娜·贾维斯在母亲悼念活动中分发白色康乃馨，被视为母亲节用花的开端。","康乃馨是肯尼亚重要的出口花卉，欧洲市场的许多切花来自肯尼亚农场。","花茎节部膨大而脆弱，采收和运输时容易折断。"]},"flower-browns-lily":{"description":"百合为百合科百合属多年生草本，株高 60–120 厘米，地下具扁球形鳞茎，由多数肉质鳞片抱合而成。茎直立，叶散生，呈披针形至椭圆状披针形。花顶生或排成总状花序，喇叭形，长 10–20 厘米，花被片 6 枚，白色或带淡黄，香气浓郁，花期 5–7 月，果期 8–9 月，蒴果长圆形。\n\n百合原产中国，分布于河北、山西、陕西、河南、湖北、湖南、江西、浙江、四川、云南等地，多生于山坡林下、溪边草丛。它喜凉爽湿润和半阴环境，忌烈日暴晒与积水，可用鳞茎分球、鳞片扦插或播种繁殖。鳞茎富含淀粉与多糖，可煮食、制成百合干，入药有润肺止咳之效；花可作切花，是婚礼和节庆常用的吉祥花卉，湖南龙山、江西万载等地把食用百合作为特色农产品种植。","habitat":"山坡林下、溪边草丛及石缝，喜凉爽湿润、半阴的环境","distribution":"中国华北、华东、华中至西南山地，湖南龙山、江西万载等地大量种植","conservation":"暂无评估","details":[{"label":"株高","value":"60–120 厘米"},{"label":"花期","value":"5–7 月，单花开放约 7–10 天"},{"label":"果期","value":"8–9 月，蒴果长圆形"},{"label":"光照","value":"喜半阴，忌强光直射"},{"label":"水分","value":"喜湿润，忌积水烂鳞茎"},{"label":"土壤","value":"疏松、肥沃、排水良好的微酸性土壤"},{"label":"繁殖","value":"鳞茎分球、鳞片扦插或播种"},{"label":"食用药用","value":"鳞茎制百合干，可润肺止咳"}],"facts":["百合的鳞茎由层层肉质鳞片抱合而成，“百合”之名即取“百片合抱”之意。","百合花被片 6 枚排成两轮，纯白色的大花往往香气最浓。","猫对百合科植物极其敏感，误食花粉或叶片可导致急性肾衰竭。","湖南龙山、江西万载等地把食用百合作为特色农产品种植。"]},"flower-roof-iris":{"description":"鸢尾为鸢尾科鸢尾属多年生草本，株高 30–60 厘米，根状茎匍匐多节，粗壮。叶片剑形，长 15–50 厘米，宽 1.5–3 厘米，基部互相套叠，呈扇状排列。花葶自叶丛中抽出，花蓝紫色，直径约 10 厘米，外花被片中央有鸡冠状白色或紫色突起，花期 4–6 月，果期 6–8 月。\n\n鸢尾原产中国中部及日本，常生于林缘、溪边和湿润草地，喜阳光充足或半阴环境，耐寒、耐湿。它因花形如鸢鸟尾羽而得名，每朵花只开一天左右，但整株花期可持续数周。鸢尾根状茎含鸢尾苷等成分，可入药，但生品有毒，不可自行服用；园林中常片植于水岸、林下，梵高的名画《鸢尾花》更使它广为人知。","habitat":"林缘、溪边湿润草地及石隙，喜光也耐半阴","distribution":"原产中国中部及日本，中国长江流域及西南山地常见","conservation":"暂无评估","details":[{"label":"株高","value":"30–60 厘米"},{"label":"花期","value":"4–6 月，单朵花仅开 1–2 天"},{"label":"果期","value":"6–8 月，蒴果六棱状"},{"label":"光照","value":"喜光，也耐半阴"},{"label":"水分","value":"耐湿，可种于水岸浅水处"},{"label":"土壤","value":"疏松湿润、排水良好的壤土"},{"label":"主要用途","value":"园林地被、水景绿化，根茎入药"}],"facts":["鸢尾花形如鸢鸟的尾羽，外花被片中央的鸡冠状突起是识别要点。","单朵鸢尾花寿命很短，通常清晨开放、傍晚凋谢，但花序会陆续开放。","梵高 1889 年创作的《鸢尾花》以蓝紫色花朵为主题，是后印象派名作。","鸢尾根茎生用有毒性，须经炮制才能入药，不可自行采食。"]},"flower-hyacinth":{"description":"风信子为天门冬科风信子属多年生球根草本，株高 15–45 厘米，鳞茎球形，外被紫色或白色膜质皮。叶片基生，肥厚带状，长 15–30 厘米。总状花序由数十朵小花密集成穗状，花冠漏斗形，6 裂，有蓝、紫、粉、红、白、黄等色，香气浓郁，花期 3–4 月，果期 5 月。\n\n风信子原产地中海东部及小亚细亚一带，喜凉爽湿润和充足阳光，秋季生根、早春开花，夏季地上部分枯萎进入休眠。它耐寒性尚可，但花芽分化需要低温处理，栽培中常用冷藏种球控制花期；水培时只需将鳞茎底部接触水面即可生根开花。荷兰哈勒姆一带的花田以风信子、郁金香连片种植闻名，鳞茎含生物碱，误食可能引起中毒，室内摆放时宜保持通风。","habitat":"地中海东岸及小亚细亚的向阳山坡与草坡，喜凉爽、阳光充足","distribution":"原产地中海东部与小亚细亚，荷兰、土耳其及中国各地广泛栽培","conservation":"暂无评估","details":[{"label":"株高","value":"15–45 厘米"},{"label":"花期","value":"3–4 月，单穗花期约 2–3 周"},{"label":"果期","value":"5 月，蒴果球形"},{"label":"光照","value":"喜光，生长期需充足阳光"},{"label":"水分","value":"喜湿润，盆栽忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的沙质土，pH 6–7"},{"label":"繁殖","value":"以分球繁殖为主"},{"label":"主要用途","value":"盆栽、水培观赏与切花"}],"facts":["风信子一个花序可开数十朵小花，香气浓郁，少数人对花香比较敏感。","风信子鳞茎含生物碱，误食会中毒，处理种球后应洗手。","荷兰哈勒姆附近的花田每年春季以风信子与郁金香花海闻名。","水培风信子时只要鳞茎底部接触水面，根系就会向下生长。"]},"flower-narcissus":{"description":"水仙为石蒜科水仙属多年生球根草本，株高 20–40 厘米，鳞茎卵球形，外被褐色膜质皮。叶片扁平带状，长 20–40 厘米，粉绿色。花葶自叶丛抽出，伞形花序有花 4–8 朵，花被片白色、6 枚，副花冠浅杯状、黄色，香气清幽，花期 1–3 月，果期 4–5 月。\n\n水仙原产地中海沿岸，中国栽培的多为多花水仙变种，以福建漳州、上海崇明所产最为著名。它喜温暖湿润、阳光充足的环境，秋季种球下地，冬季抽叶开花，夏季休眠，可水培或盆栽，水培时只需清水和卵石即可。水仙是中国春节的传统清供花卉，寓意吉祥如意；园艺者还会雕刻鳞茎，塑造出蟹爪、茶壶等造型。鳞茎含石蒜碱，全株有毒，不可食用。","habitat":"温暖湿润的溪畔、庭园及沙质土壤，喜阳光充足、冬季温和","distribution":"原产地中海沿岸，中国福建漳州、上海崇明、浙江舟山等地大量栽培","conservation":"暂无评估","details":[{"label":"株高","value":"20–40 厘米"},{"label":"花期","value":"1–3 月，单株花期约 2–3 周"},{"label":"果期","value":"4–5 月，蒴果"},{"label":"光照","value":"喜光，也耐半阴"},{"label":"水分","value":"生长期喜湿润，水培需定期换水"},{"label":"土壤","value":"疏松、排水良好的沙质壤土"},{"label":"繁殖","value":"以分球繁殖为主"},{"label":"主要用途","value":"春节清供、水培观赏、切花"}],"facts":["水仙花被片洁白，中央杯状副花冠呈黄色，形成“金盏银台”的经典形象。","福建漳州水仙以雕刻造型闻名，一球可塑成蟹爪、茶壶等形态。","水仙鳞茎含石蒜碱等多种生物碱，误食会引起呕吐和腹泻。","水培水仙不需要土壤，靠鳞茎内储存的养分即可开花。"]},"flower-wild-pansy":{"description":"三色堇为堇菜科堇菜属一二年生草本，株高 15–30 厘米，茎多分枝，稍匍匐。叶互生，卵形或长圆形，边缘有圆齿，托叶羽状深裂。花单生于叶腋，直径 2–4 厘米，通常有紫、黄、白三色，上面两枚花瓣常为紫色，下面花瓣黄色并带紫色斑纹，花期 4–6 月，果期 5–7 月。\n\n三色堇原产欧洲，野生种是欧洲草甸常见的三色堇菜，19 世纪起英国、比利时园艺家以它为主体杂交选育，形成了花径更大、色彩更丰富的栽培品种。它喜凉爽湿润和充足阳光，耐寒不耐热，夏季高温时易萎蔫；播种以秋播为主，翌年早春开花。花朵可作沙拉和甜点的装饰，但需确认未施农药；在欧洲，三色堇的花语常与思念和快乐相连。","habitat":"欧洲草甸、田埂与林缘，喜凉爽、阳光充足的环境","distribution":"原产欧洲，现世界各地广泛栽培，中国各地花坛常见","conservation":"暂无评估","details":[{"label":"株高","value":"15–30 厘米，茎多分枝"},{"label":"花期","value":"4–6 月，凉爽地区可延至 7 月"},{"label":"果期","value":"5–7 月，蒴果三瓣开裂"},{"label":"光照","value":"喜光，也耐轻度半阴"},{"label":"水分","value":"喜湿润，忌干旱和水涝"},{"label":"土壤","value":"疏松肥沃、排水良好的壤土"},{"label":"繁殖","value":"以秋播为主，也可扦插"},{"label":"主要用途","value":"花坛、花境、盆花与食用装饰"}],"facts":["三色堇的花瓣通常呈现紫、黄、白三色，因此得名，图案又似一张猫脸。","园艺上常见的三色堇多为杂交选育品种，花径可比野生种大数倍。","三色堇播种后需经低温春化，翌年早春才能整齐开花。","花朵可点缀沙拉与甜点，但食用前须确认栽培中未使用农药。"]},"flower-english-lavender":{"description":"薰衣草为唇形科薰衣草属半灌木，株高 30–100 厘米，老枝木质化，嫩枝方形，全株被灰白色星状毛。叶片线形至披针形，长 2–6 厘米，灰绿色。轮伞花序聚集成顶生穗状花序，花冠蓝紫色，二唇形，花期 6–8 月，果期 8–9 月。\n\n薰衣草原产地中海沿岸的干燥山坡，喜阳光充足、冬季温和、排水极好的环境，耐旱怕涝，忌高温高湿。花穗在初开时香气最浓，此时采收可提取精油，主要成分是芳樟醇和乙酸芳樟酯，广泛用于香水、洗护用品和芳香疗法；干燥花穗可制作香包、花茶。法国普罗旺斯、保加利亚和英国是著名产地，中国新疆伊犁也形成了规模化的薰衣草种植区。","habitat":"地中海沿岸干燥向阳的山坡与石灰岩地，喜光、耐旱、怕涝","distribution":"原产地中海沿岸，法国普罗旺斯、保加利亚及中国新疆伊犁栽培较多","conservation":"暂无评估","details":[{"label":"株高","value":"30–100 厘米，老枝木质化"},{"label":"花期","value":"6–8 月，花穗初开时香气最浓"},{"label":"果期","value":"8–9 月，小坚果"},{"label":"光照","value":"极喜光，光照不足开花稀少"},{"label":"水分","value":"耐旱，忌积水，雨季注意排水"},{"label":"土壤","value":"疏松、排水良好的石灰质沙壤土"},{"label":"主要用途","value":"提取精油、干花、香包与花茶"}],"facts":["薰衣草精油的主要香气成分是芳樟醇和乙酸芳樟酯，广泛用于香水和洗护用品。","花穗在花苞初绽时采摘香气最浓，完全开放后香气反而下降。","普罗旺斯高原的薰衣草多在海拔 600 米以上种植，昼夜温差大有利香气积累。","干燥的薰衣草花穗可放入衣柜驱虫增香。"]},"flower-rosemary":{"description":"迷迭香为唇形科鼠尾草属常绿灌木，株高 50–150 厘米，分枝繁密，老枝褐色，树皮纵裂。叶片线形、革质，长 1–2.5 厘米，边缘反卷，叶面深绿有光泽，揉碎后散发松木般的香气。花腋生，唇形，蓝紫色至淡蓝色，花期 4–6 月，果期 6–7 月。\n\n迷迭香原产地中海沿岸的干燥石灰岩山坡，喜阳光充足、温暖干燥和排水极好的环境，耐旱而不耐水涝，冬季可耐短时 -5℃ 左右低温。它是西餐中重要的香草，烤羊排、烤肉和意面中常用；叶片和花可提取精油，用于香水和护发产品。欧洲传统中迷迭香象征记忆与忠诚，婚礼和纪念仪式上常佩戴，莎士比亚在《哈姆雷特》中也有提及。","habitat":"地中海沿岸干燥的石灰岩山坡与灌丛，喜光、耐旱、怕积水","distribution":"原产地中海沿岸，中国云南、贵州、广西等地有规模化种植","conservation":"暂无评估","details":[{"label":"株高","value":"50–150 厘米，分枝繁密"},{"label":"花期","value":"4–6 月，温暖地区可二次开花"},{"label":"果期","value":"6–7 月，小坚果"},{"label":"光照","value":"极喜光，每天需 6 小时以上直射光"},{"label":"水分","value":"耐旱，忌积水烂根"},{"label":"土壤","value":"疏松、排水良好的石灰质沙壤土"},{"label":"主要用途","value":"烹饪香草、精油、庭院绿篱"}],"facts":["迷迭香的学名原为 Rosmarinus officinalis，拉丁语意为“海之露”，后并入鼠尾草属。","叶片含迷迭香酸等抗氧化物质，可延缓油脂氧化，常用于烤肉腌料。","欧洲传统视迷迭香为记忆的象征，婚礼和纪念仪式上常佩戴。","迷迭香开花时是优质蜜源，地中海地区的迷迭香蜂蜜带有淡淡花香。"]},"flower-field-mint":{"description":"薄荷为唇形科薄荷属多年生草本，株高 30–80 厘米，茎直立或匍匐，方形，有节，节上生根。叶片对生，卵形至披针形，边缘有锯齿，两面被短毛。轮伞花序腋生，花小，花冠淡紫色或白色，花期 7–9 月，果期 8–10 月。\n\n薄荷原产东亚与北美温暖湿润地区，中国江苏、安徽、河南等地栽培较多。它喜阳光充足、湿润的环境，适应性强，可用根茎分株或扦插繁殖，地栽时地下茎蔓延迅速，容易长成成片群落。叶片含薄荷醇与薄荷酮，揉碎即有清凉气味，可鲜食、泡茶、调制饮品，也可提取薄荷脑用于医药和食品工业；中医认为薄荷有疏散风热之效，但芳香植物不宜过量长期饮用。","habitat":"溪边、林下、湿地及田埂，喜湿润、阳光充足的环境","distribution":"原产东亚与北美，中国江苏、安徽、河南、江西等地大面积栽培","conservation":"暂无评估","details":[{"label":"株高","value":"30–80 厘米，茎方形有节"},{"label":"花期","value":"7–9 月，轮伞花序腋生"},{"label":"果期","value":"8–10 月，小坚果"},{"label":"光照","value":"喜光，也耐半阴"},{"label":"水分","value":"喜湿润，忌长期干旱"},{"label":"土壤","value":"疏松肥沃、保水性好的壤土"},{"label":"繁殖","value":"分株、扦插或根茎繁殖"},{"label":"主要用途","value":"薄荷茶、食品调味、提取薄荷脑"}],"facts":["薄荷的清凉感来自薄荷醇，它刺激皮肤冷觉感受器，让人产生“凉”的错觉。","薄荷茎为四棱形，节上容易生根，剪一段茎插入水中即可繁殖。","地栽薄荷地下茎蔓延快，容易侵占邻近花坛，宜用花盆限根。","薄荷开花时蜜源丰富，能吸引蜜蜂和食蚜蝇等传粉昆虫。"]},"flower-sweet-basil":{"description":"罗勒为唇形科罗勒属一年生草本，株高 30–60 厘米，茎直立，四棱形，多分枝，全株被柔毛。叶片对生，卵形至长圆形，边缘有疏锯齿，揉碎后散发浓郁甜香。轮伞花序组成顶生的总状花穗，花小，白色或淡紫色，花期 6–9 月，果期 8–10 月，小坚果遇水会膨胀成胶质。\n\n罗勒原产热带亚洲，喜温暖、阳光充足和湿润的环境，不耐寒，遇霜即枯。它是世界著名的香草，意大利菜用它制作青酱，泰国菜用打抛罗勒增香，中国台湾的三杯鸡和潮汕菜也离不开九层塔。叶片富含芳樟醇、丁香酚等挥发油，可鲜食、干制或提取精油；种子在东南亚被制成饮品“兰香子”，吸水后外层形成透明胶膜。","habitat":"热带亚洲的向阳坡地与田边，喜温暖湿润、阳光充足","distribution":"原产热带亚洲，现全球温暖地区栽培，中国南方常见","conservation":"暂无评估","details":[{"label":"株高","value":"30–60 厘米，茎四棱形"},{"label":"花期","value":"6–9 月，花穗白色或淡紫"},{"label":"果期","value":"8–10 月，小坚果遇水膨胀"},{"label":"光照","value":"喜光，每天需 6 小时以上光照"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的壤土"},{"label":"繁殖","value":"以播种为主，也可扦插"},{"label":"主要用途","value":"鲜食香草、青酱、精油"}],"facts":["罗勒在台湾称九层塔，因花序层层叠生如塔而得名。","意大利青酱的核心原料就是罗勒叶、松子、蒜和橄榄油。","罗勒种子吸水后外层形成透明胶质，可制成饮品兰香子。","罗勒与番茄是经典搭配，能让番茄料理的香气更突出。"]},"flower-babys-breath":{"description":"满天星为石竹科满天星属多年生草本，株高 60–100 厘米，茎多分枝，全株被白粉而呈灰绿色。叶片披针形，对生。聚伞花序顶生，花极小，直径约 5 毫米，花瓣白色、5 枚，数不清的小花聚成蓬松的花团，花期 5–7 月，果期 6–8 月。\n\n满天星原产欧亚大陆的草原和石灰质干旱地区，喜阳光充足、凉爽干燥和排水良好的环境，耐旱耐寒，怕积水和湿热。它的属名来自古希腊语，意为“喜爱石灰”，可见对钙质土壤的偏好。切花中常见的满天星多由温室栽培，花枝干燥后仍能保持形态和颜色，是制作干花和永生花的常用材料，也常与玫瑰、康乃馨搭配成大花束。","habitat":"欧亚草原与石灰质丘陵，喜凉爽干燥、阳光充足","distribution":"原产欧洲至中亚一带，中国新疆、内蒙古等地有野生分布","conservation":"暂无评估","details":[{"label":"株高","value":"60–100 厘米，茎多分枝"},{"label":"花期","value":"5–7 月，单株花期约 1 个月"},{"label":"果期","value":"6–8 月，蒴果球形"},{"label":"光照","value":"喜光，光照不足易徒长"},{"label":"水分","value":"耐旱，忌积水"},{"label":"土壤","value":"石灰质沙壤土，喜钙、耐瘠薄"},{"label":"主要用途","value":"切花配材、干花、花束填充"}],"facts":["满天星的学名 Gypsophila 意为“喜爱石灰”，源自其对钙质土壤的偏好。","单朵花直径只有约 5 毫米，一个花序却可包含上百朵小花。","花枝采下倒挂阴干后仍能保持形态，是制作干花的常用材料。","花语为“甘愿做配角的爱”，常与玫瑰、康乃馨搭配成大花束。"]},"flower-lisianthus":{"description":"洋桔梗为龙胆科洋桔梗属一二年生草本，株高 30–100 厘米，茎直立，被白粉。叶片灰绿色，卵形至长椭圆形，对生，稍肉质。花单生或成圆锥花序，花冠钟状，直径 5–8 厘米，花瓣边缘常呈波状，有单瓣和重瓣，花色有白、粉、紫、蓝等，花期 5–9 月，果期 7–10 月。\n\n洋桔梗原产美国中南部草原，喜温暖、阳光充足和通风良好的环境，苗期需经低温才能顺利开花，夏季高温时生长缓慢。它虽名为“桔梗”，却与桔梗科无关，而是龙胆科的成员，因花形似桔梗而得名。洋桔梗切花寿命长、花瓣不易脱落，可用于花束、婚礼用花和瓶插；日本、荷兰是主要的育种和切花生产国，中国云南也有大面积栽培。","habitat":"美国中南部的草原与河岸，喜温暖、阳光充足的环境","distribution":"原产美国中南部，日本、荷兰及中国云南等地广泛栽培","conservation":"暂无评估","details":[{"label":"株高","value":"30–100 厘米，茎被白粉"},{"label":"花期","value":"5–9 月，单朵开放 1–2 周"},{"label":"果期","value":"7–10 月，蒴果"},{"label":"光照","value":"喜充足阳光，夏季需适度遮阴"},{"label":"水分","value":"喜湿润，忌积水烂根"},{"label":"土壤","value":"疏松肥沃、排水良好的壤土，pH 6–7"},{"label":"繁殖","value":"以播种繁殖为主"},{"label":"主要用途","value":"切花、花束、婚礼用花"}],"facts":["洋桔梗名中有“桔梗”，其实属于龙胆科，与桔梗科没有亲缘关系。","它的花瓣质地柔软且不易脱落，瓶插寿命可达 1–2 周。","洋桔梗幼苗需经过低温期才能诱导花芽，育苗期约 3 个月。","日本育种家培育出大量重瓣品种，使洋桔梗常被误认作玫瑰。"]},"flower-larkspur":{"description":"飞燕草为毛茛科飞燕草属一年生草本，株高 40–100 厘米，茎直立，上部疏生分枝。叶片掌状深裂，呈羽状细裂。总状花序顶生，花两侧对称，萼片呈花瓣状，后方延伸出细长的距，花色有蓝、紫、粉、白等，花期 5–7 月，果期 6–8 月，蓇葖果内含多数种子。\n\n飞燕草原产欧洲南部及地中海沿岸，喜阳光充足、凉爽干燥和排水良好的环境，耐寒不耐酷热，适合秋播、翌年春夏开花。它因花形酷似飞燕而得名，花穗挺拔，是花境中优良的竖线条材料，也是常见的切花。需要注意的是，飞燕草全株含二萜类生物碱，有毒，误食会引起中毒，栽培和摆放时应远离儿童与宠物。","habitat":"地中海沿岸的干燥山坡与草甸，喜凉爽、阳光充足","distribution":"原产欧洲南部及地中海沿岸，中国各地庭园有栽培","conservation":"暂无评估","details":[{"label":"株高","value":"40–100 厘米，茎直立"},{"label":"花期","value":"5–7 月，花序自下而上开放"},{"label":"果期","value":"6–8 月，蓇葖果"},{"label":"光照","value":"喜光，也可耐轻度半阴"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的壤土"},{"label":"繁殖","value":"以秋播为主"},{"label":"主要用途","value":"花境、切花、庭院点缀"}],"facts":["飞燕草花后细长的“尾巴”其实是花距，是容纳花蜜的结构。","花穗由下往上依次开放，整串花期可达 3–4 周。","飞燕草全株含二萜类生物碱，有毒，不可入口。","它常被用作花境的竖线条材料，与矮生花卉形成层次。"]},"flower-corn-poppy":{"description":"虞美人为罂粟科罂粟属一二年生草本，株高 30–80 厘米，茎细弱，密被开展的黄白色刚毛。叶片羽状深裂，两面被毛。花单生茎顶，花蕾下垂，开放后花瓣 4 枚、薄如绢，鲜红色，基部常具黑斑，直径 5–10 厘米，花期 5–6 月，果期 6–7 月，蒴果截顶球形。\n\n虞美人原产欧洲，野生于麦田、路边和荒地，喜阳光充足、凉爽的环境，耐寒不耐湿热，常以秋播繁殖。它因花姿轻盈、颜色鲜艳而广受喜爱，与同属的罂粟不同，虞美人植株较小、茎叶被毛、果实小，所含生物碱极少，但它全株仍有一定毒性，不可食用。第一次世界大战后，虞美人成为纪念阵亡将士的象征花，英国每年 11 月都会佩戴纸质虞美人花。","habitat":"欧洲的麦田、路边荒地与山坡，喜阳光充足、凉爽干燥","distribution":"原产欧洲，中国各地庭园广泛栽培，也有归化种群","conservation":"暂无评估","details":[{"label":"株高","value":"30–80 厘米，茎细弱被毛"},{"label":"花期","value":"5–6 月，单朵花仅开 2–3 天"},{"label":"果期","value":"6–7 月，蒴果截顶球形"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松、排水良好的沙壤土"},{"label":"繁殖","value":"以秋播或早春播种为主"},{"label":"主要用途","value":"庭园观赏、花境与切花"}],"facts":["虞美人与罂粟同属，但植株较小、茎叶有毛、果实小，有毒生物碱含量很低。","第一次世界大战后，虞美人成为纪念阵亡将士的象征花，英国每年 11 月佩戴纸质花。","花瓣薄如绢纸，开放后很快脱落，单朵花寿命仅 2–3 天。","花蕾开放前向下低垂，开放后花梗直立，姿态轻盈。"]},"flower-cosmos":{"description":"波斯菊为菊科秋英属一年生草本，株高 60–200 厘米，茎直立，多分枝。叶片二次羽状深裂，裂片线形，十分纤细。头状花序单生或数个聚生，直径 3–8 厘米，舌状花 8 枚，有粉、紫、白等色，中央管状花黄色，花期 6–10 月，果期 8–11 月。\n\n波斯菊原产墨西哥，喜阳光充足、凉爽通风的环境，耐干旱瘠薄，怕积水和酷热。它自播能力很强，种子落地后翌年可自行萌发，因此常成片出现在路旁、荒地和新开垦的坡地。中国西藏、青海、云南等地常把波斯菊称作“格桑花”，在高海拔地区成片种植形成花海景观，是旅游旺季的常见观赏花卉，也常用于公路沿线的边坡绿化。","habitat":"墨西哥的干旱草原与山坡，喜阳光充足、凉爽通风","distribution":"原产墨西哥，现世界各地归化或栽培，中国各地常见","conservation":"暂无评估","details":[{"label":"株高","value":"60–200 厘米，茎多分枝"},{"label":"花期","value":"6–10 月，单株花期长"},{"label":"果期","value":"8–11 月，瘦果细长"},{"label":"光照","value":"极喜光，光照不足易徒长"},{"label":"水分","value":"耐旱，忌积水"},{"label":"土壤","value":"疏松、排水良好的沙壤土，耐瘠薄"},{"label":"繁殖","value":"以播种为主，自播能力强"},{"label":"主要用途","value":"花海景观、路旁绿化、切花"}],"facts":["波斯菊叶片细裂如羽，英文名 Cosmos 源自希腊语，本意是“秩序、和谐”。","种子成熟后落地可自行萌发，次年常成片生长，几乎不需要人工播种。","在西藏、青海等地，波斯菊常被称作“格桑花”，是高原花海的常见主角。","植株过高时遇风容易倒伏，花海种植常通过摘心控制株高。"]},"flower-zinnia":{"description":"百日草为菊科百日菊属一年生草本，株高 30–100 厘米，茎直立粗壮，被短毛。叶片对生，卵形至披针形，基部抱茎，表面粗糙。头状花序单生茎顶，直径 4–10 厘米，舌状花扁平，有红、橙、黄、粉、紫、白等色，花期 6–10 月，果期 8–11 月。\n\n百日草原产墨西哥，喜温暖、阳光充足的环境，耐干旱但怕酷热和积水，播种后约两个月即可开花。它的花期很长，可持续百日左右，因此得名；花后结出的瘦果呈瘦长楔形。百日草是世界重要的花坛和切花花卉，有高秆大花与矮生多花等不同类型，适合布置花坛、花境和盆栽。2016 年国际空间站的宇航员曾在轨培育百日草并成功开花，是太空植物栽培实验的明星物种之一。","habitat":"墨西哥的干旱草原与山坡，喜温暖、阳光充足","distribution":"原产墨西哥，现世界各地栽培，中国南北各地花坛常见","conservation":"暂无评估","details":[{"label":"株高","value":"30–100 厘米"},{"label":"花期","value":"6–10 月，单株花期可达 100 天"},{"label":"果期","value":"8–11 月，瘦果楔形"},{"label":"光照","value":"极喜光，光照不足易徒长"},{"label":"水分","value":"耐旱，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的壤土"},{"label":"繁殖","value":"以播种为主"},{"label":"主要用途","value":"花坛、花境、切花"}],"facts":["百日草花期可长达约 100 天，“百日”之名由此而来。","2016 年国际空间站的宇航员在轨培育百日草并成功开花。","头状花序上的舌状花颜色鲜艳，中央管状花则密集成盘。","高秆品种可作切花，矮生品种适合花坛和盆栽。"]},"flower-african-marigold":{"description":"万寿菊为菊科万寿菊属一年生草本，株高 50–150 厘米，茎直立粗壮，多分枝。叶片羽状全裂，裂片披针形，边缘有锯齿，揉碎后有特殊气味。头状花序单生，直径 5–10 厘米，舌状花多层、橙黄或金黄，重瓣品种形似绒球，花期 7–9 月，果期 9–10 月。\n\n万寿菊原产墨西哥，喜温暖、阳光充足的环境，适应性强，耐干旱和瘠薄，但怕霜冻和积水。它是重要的经济花卉，花瓣富含叶黄素，可提取天然色素用于饲料和食品着色；植株根系的分泌物能抑制根结线虫，常被种在番茄、马铃薯田间作伴生植物。在墨西哥，万寿菊是亡灵节祭坛上的传统花卉，被认为能为亡魂指引回家的路。","habitat":"墨西哥的草原与山坡，喜温暖、阳光充足","distribution":"原产墨西哥，中国各地广泛栽培，云南、山东为主要种植区","conservation":"暂无评估","details":[{"label":"株高","value":"50–150 厘米，茎直立多分枝"},{"label":"花期","value":"7–9 月，单株花期约 2 个月"},{"label":"果期","value":"9–10 月，瘦果线形"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"耐旱，忌积水"},{"label":"土壤","value":"疏松、排水良好的壤土，耐瘠薄"},{"label":"主要用途","value":"观赏、提取叶黄素、驱线虫"}],"facts":["万寿菊根部会分泌抑制线虫的物质，常与番茄、马铃薯间作。","花瓣富含叶黄素，是天然饲料着色剂的重要来源。","在墨西哥亡灵节，万寿菊被视为为亡魂指引归途的花。","揉碎万寿菊叶片会闻到浓烈气味，有人形容为“臭菊花”。"]},"flower-daylily":{"description":"萱草为阿福花科萱草属多年生草本，株高 40–100 厘米，具肉质根，根端常膨大成纺锤状块根。叶片基生，线形，长 30–80 厘米，排成两列。花葶自叶丛抽出，花序有花 6–12 朵，花橙红色至橘黄色，花被片 6 枚，花期 5–8 月，果期 7–9 月。\n\n萱草原产中国，广泛分布于山坡、林缘和溪边，喜阳光充足或半阴、湿润的环境，耐寒耐旱，适应性强。它的每朵花只开一天，清晨开放、傍晚凋谢，但整株花序会持续开花数周。中国古籍称萱草为“忘忧草”，《诗经》中已有记载，古人常把它种在母亲居所旁，因此萱草也被视为中国的母亲花。黄花菜是萱草属中可食用的种类，而常见观赏萱草含秋水仙碱，误食会中毒。","habitat":"山坡、林缘、溪边及路旁，喜光也耐半阴","distribution":"原产中国，朝鲜半岛及日本也有分布，中国南北各地常见","conservation":"暂无评估","details":[{"label":"株高","value":"40–100 厘米，具肉质块根"},{"label":"花期","value":"5–8 月，单朵花仅开一天"},{"label":"果期","value":"7–9 月，蒴果"},{"label":"光照","value":"喜光，也耐半阴"},{"label":"水分","value":"喜湿润，也耐短时干旱"},{"label":"土壤","value":"疏松肥沃、排水良好的壤土"},{"label":"主要用途","value":"庭园观赏、食用黄花菜、药用"}],"facts":["萱草每朵花只开一天，清晨绽放、傍晚凋谢，次日由新的花蕾接替。","古人称萱草为忘忧草，并把它种在母亲居所旁，故萱草被视为中国母亲花。","可食用的黄花菜是萱草属的另一物种，观赏萱草含秋水仙碱，不可食用。","萱草根端常膨大成纺锤状块根，储存养分以度过冬季。"]},"flower-hollyhock":{"description":"蜀葵为锦葵科蜀葵属二年生草本，株高 1–2.5 米，茎直立，全株被星状毛。叶片大，圆心形，边缘有浅裂和锯齿，叶柄长。花大，直径 6–12 厘米，单瓣或重瓣，有红、粉、白、黄、紫等色，沿茎自下而上排列成总状花序，花期 5–8 月，果期 7–9 月，种子肾形。\n\n蜀葵原产中国西南，因在四川一带栽培广泛而得名，喜阳光充足、凉爽的环境，耐寒耐旱，对土壤要求不严，常自播繁衍。它株形高大挺拔，古称“一丈红”，是院落墙边和路旁常见的传统花卉。花瓣可食用，含花青素，民间有用花瓣泡水、做点心的做法；根、茎、叶和花均可入药，有清热解毒之效。","habitat":"向阳的院墙边、路旁与山坡，喜光、耐旱、耐寒","distribution":"原产中国西南地区，现各地庭院广泛栽培","conservation":"暂无评估","details":[{"label":"株高","value":"1–2.5 米，茎直立被毛"},{"label":"花期","value":"5–8 月，花自下而上开放"},{"label":"果期","value":"7–9 月，分果扁圆形"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"耐旱，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的壤土"},{"label":"繁殖","value":"以播种为主，自播能力强"},{"label":"主要用途","value":"庭院观赏、花瓣食用、入药"}],"facts":["蜀葵因原产四川一带而得名，古称“一丈红”，形容其花茎高挺。","花朵沿茎自下而上依次开放，下面的花先开、上面的花后开。","花瓣含花青素，可作食品染色或点缀，民间有以花瓣做点心的习俗。","蜀葵全株被星状毛，触摸叶片有粗糙感。"]},"flower-sensitive-plant":{"description":"含羞草为豆科含羞草属多年生草本，常作一二年生栽培，株高 20–60 厘米，茎直立或匍匐，多分枝，全株被钩刺和毛。叶为二回羽状复叶，小叶 10–20 对，排列整齐。头状花序球形，花小，淡粉红色，花期 7–10 月，果期 8–11 月，荚果扁平、由 3–5 节组成。\n\n含羞草原产热带美洲，喜温暖、阳光充足和湿润的环境，不耐寒，在中国南方可露地栽培，北方多盆栽。它的叶柄基部和叶枕细胞在受到触碰时迅速失水，导致叶片闭合、叶柄下垂，数分钟后可恢复，这种触敏运动被认为有减少水分蒸发和躲避昆虫的作用。含羞草全株含含羞草碱，长期接触或误食可能影响健康；在热带地区它生长蔓延快，有时被视为杂草。","habitat":"热带美洲的草地、路旁与灌丛，喜温暖湿润、阳光充足","distribution":"原产热带美洲，现热带、亚热带地区归化，中国南方常见","conservation":"暂无评估","details":[{"label":"株高","value":"20–60 厘米，茎多分枝"},{"label":"花期","value":"7–10 月，头状花序球形"},{"label":"果期","value":"8–11 月，荚果扁平"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"喜湿润，忌干旱"},{"label":"土壤","value":"疏松、排水良好的沙壤土"},{"label":"繁殖","value":"以播种繁殖为主"},{"label":"主要用途","value":"盆栽观赏、科普教学"}],"facts":["含羞草受触碰后，叶枕细胞迅速失去膨压，叶片闭合、叶柄下垂，数分钟后恢复。","它的触敏运动可减少水分蒸发，也被认为有助于躲避昆虫取食。","含羞草全株含含羞草碱，长期接触或误食可能影响健康。","在热带地区，含羞草种子繁殖快、带刺，有时成为农田杂草。"]},"flower-dandelion":{"description":"蒲公英为菊科蒲公英属多年生草本，株高 10–30 厘米，根粗壮、肉质，茎极短。叶片基生，倒披针形，羽状深裂，边缘具齿，排成莲座状。花葶自叶丛抽出，头状花序金黄色，全部由舌状花组成，花期 4–9 月，果期 5–10 月，瘦果顶端有白色冠毛，形成绒球状。\n\n蒲公英广布于北半球温带，中国各地山坡、田野、路旁都能见到，喜阳光充足、耐寒耐旱，对土壤要求不严。它的花清晨开放、傍晚闭合，刮风或阴天时花序也会闭合，种子则借助冠毛随风传播，一株可产生数百至上千粒种子。嫩叶可作野菜凉拌或炒食，根可烘焙后磨粉代咖啡，全草入药有清热解毒、消肿散结之效。","habitat":"山坡草地、田野、路旁及荒地，喜光、耐寒、耐旱","distribution":"广布于北半球温带，中国各地均有分布","conservation":"暂无评估","details":[{"label":"株高","value":"10–30 厘米，茎极短"},{"label":"花期","value":"4–9 月，花晨开暮合"},{"label":"果期","value":"5–10 月，瘦果具白色冠毛"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"耐旱，忌长期积水"},{"label":"土壤","value":"对土壤要求不严，疏松壤土最佳"},{"label":"繁殖","value":"以播种繁殖为主"},{"label":"主要用途","value":"药用、嫩叶食用、根代咖啡"}],"facts":["蒲公英的“绒球”是带有冠毛的瘦果，可借风力传播数公里。","花在清晨开放、傍晚闭合，阴雨天也会闭合，可据此判断天气变化。","蒲公英根烘焙磨粉后可作咖啡代用品，民间称“蒲公英咖啡”。","一株蒲公英一季可产生数百至上千粒种子，繁殖能力极强。"]},"flower-dahlia":{"description":"大丽花为菊科大丽花属多年生草本，地下具膨大块根，形似红薯。株高 30–200 厘米，茎直立粗壮，多分枝。叶片对生，一至三回羽状深裂，边缘有锯齿。头状花序顶生，直径 5–30 厘米，重瓣品种花瓣层层叠叠，有红、黄、粉、白、紫等色，花期 6–10 月，果期 8–11 月。\n\n大丽花原产墨西哥高原，喜阳光充足、凉爽干燥和通风良好的环境，不耐寒也不耐酷热，块根在 0℃ 以下易受冻。它是墨西哥的国花，18 世纪传入欧洲后经园艺家不断杂交选育，如今品种数以万计，花型有单瓣、重瓣、球型、睡莲型、仙人掌型等。块根含菊糖，可作提取果糖的原料；花朵可作切花，花期长、花径大，是庭院和花坛的重要材料。","habitat":"墨西哥高原的凉爽山地，喜光、喜凉爽干燥、怕积水","distribution":"原产墨西哥，现世界各地广泛栽培，中国南北各地均有种植","conservation":"暂无评估","details":[{"label":"株高","value":"30–200 厘米，因品种差异大"},{"label":"花期","value":"6–10 月，单朵花可开 1–2 周"},{"label":"果期","value":"8–11 月，瘦果扁平"},{"label":"光照","value":"喜充足阳光，每天需 6 小时以上"},{"label":"水分","value":"喜湿润，忌积水烂根"},{"label":"土壤","value":"疏松肥沃、排水良好的沙壤土"},{"label":"繁殖","value":"分块根、扦插或播种"},{"label":"主要用途","value":"庭院花坛、切花、盆栽"}],"facts":["大丽花的块根形似红薯，因此民间也称“地瓜花”。","墨西哥把大丽花定为国花，18 世纪传入欧洲后引发育种热潮。","大丽花花径最大可超过 30 厘米，花型有球型、睡莲型、仙人掌型等。","块根中含菊糖，可作为提取果糖和膳食纤维的原料。"]},"flower-madagascar-periwinkle":{"description":"长春花为夹竹桃科长春花属常绿亚灌木，常作草本栽培，株高 30–60 厘米，茎直立，多分枝，全株光滑。叶片对生，倒卵形至长圆形，表面深绿有光泽，中脉明显。花单生或成聚伞花序，花冠高脚碟状，5 裂，有粉、白、紫红等色，花期 5–10 月，温暖地区几乎全年开花；果实为蓇葖果。\n\n长春花原产马达加斯加，喜温暖、阳光充足和湿润的环境，不耐寒，冬季需保持在 10℃ 以上，对土壤要求不严。它在热带地区逸生后容易归化，成为常见的路边野花。长春花是重要的药用植物，全株含长春碱和长春新碱等生物碱，可用于提取抗癌药物；但全株有毒，误食会引起白细胞减少等中毒症状，只可观赏，切勿采食或自行入药。","habitat":"马达加斯加的海岸灌丛与林缘，喜温暖、阳光充足","distribution":"原产马达加斯加，现全球热带、亚热带地区归化或栽培，中国南方常见","conservation":"暂无评估","details":[{"label":"株高","value":"30–60 厘米，茎多分枝"},{"label":"花期","value":"5–10 月，温暖地区几乎全年开花"},{"label":"果期","value":"花后结蓇葖果"},{"label":"光照","value":"喜充足阳光，也耐半阴"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松、排水良好的壤土"},{"label":"繁殖","value":"以播种和扦插为主"},{"label":"主要用途","value":"观赏、提取抗癌生物碱"}],"facts":["长春花全株含长春碱、长春新碱等生物碱，是提取抗癌药物的重要原料。","它全株有毒，误食会影响造血系统，只能观赏，不可采食或自行入药。","长春花花期极长，温暖地区几乎全年开花，故有“日日春”的别名。","在热带、亚热带地区，长春花逸生后常成为路边常见的归化植物。"]},"flower-petunia":{"description":"矮牵牛为茄科矮牵牛属一年生草本，园艺品种多为杂交种，株高 15–60 厘米，茎直立或匍匐，全株被细柔毛。叶片卵形，对生，表面有黏性腺毛。花单生叶腋，花冠漏斗形，直径 5–10 厘米，边缘有皱褶，有红、粉、紫、白、黄及条纹、复色，花期 4–10 月；果实为蒴果。\n\n矮牵牛由南美洲的腋花矮牵牛和整合矮牵牛杂交育成，19 世纪起在欧洲广泛栽培，如今品种数以千计，有直立型和垂吊型之分。它喜阳光充足、温暖湿润和通风良好的环境，不耐寒也不耐酷热，盛夏高温时需适当遮阴；播种以春播为主，垂吊品种适合吊篮和窗台。它与旋花科的牵牛花并非近亲，只是花形相似，容易混淆。","habitat":"南美草原起源的园艺杂交种，喜温暖、阳光充足、通风良好","distribution":"原产南美洲，现世界各地广泛栽培，中国各地花坛与阳台常见","conservation":"暂无评估","details":[{"label":"株高","value":"15–60 厘米，垂吊型枝条可达 1 米"},{"label":"花期","value":"4–10 月，单株花期长"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜充足阳光，夏季高温需遮阴"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的壤土"},{"label":"繁殖","value":"以播种为主，也可扦插"},{"label":"主要用途","value":"花坛、花境、吊篮与窗台盆栽"}],"facts":["矮牵牛的学名中“×”表示它是杂交种，由两种南美矮牵牛杂交育成。","它与旋花科的牵牛花并非近亲，只是花形相似，常被误认。","叶片和茎上的腺毛会分泌黏液，触摸后有黏手的感觉。","垂吊型品种枝条可垂到 1 米长，是吊篮和窗台绿化的热门材料。"]},"flower-scarlet-sage":{"description":"一串红为唇形科鼠尾草属多年生亚灌木，常作一年生花卉栽培，株高 30–90 厘米，茎四棱形，多分枝。叶片对生，卵形，边缘有锯齿。轮伞花序密集成顶生的穗状花序，花萼钟形、鲜红色，花冠唇形、比萼片短，红色，花期 7–10 月；果实为小坚果。\n\n一串红原产巴西，喜温暖、阳光充足和湿润的环境，不耐寒，遇霜即枯，栽培以春播为主。它的花萼颜色鲜艳且宿存，是观赏的主要部分，花谢后萼片仍可保持红色一段时间。一串红在中国城市绿化中常大面积布置于节日花坛，与黄色万寿菊、紫色矮牵牛搭配形成色块。花蜜丰富，在原产地由蜂鸟传粉；种子成熟后会自行散落，可留种翌年播种。","habitat":"巴西的亚热带林缘与灌丛，喜温暖、阳光充足","distribution":"原产巴西，现世界各地广泛栽培，中国各地花坛常见","conservation":"暂无评估","details":[{"label":"株高","value":"30–90 厘米，茎四棱形"},{"label":"花期","value":"7–10 月，穗状花序鲜红"},{"label":"果期","value":"9–11 月，小坚果"},{"label":"光照","value":"喜充足阳光，也耐轻度半阴"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的壤土"},{"label":"繁殖","value":"以播种为主，也可扦插"},{"label":"主要用途","value":"节日花坛、花境、盆栽"}],"facts":["一串红观赏的主要是鲜红色的花萼，花冠其实比萼片短。","它的花蜜丰富，在原产地巴西主要由蜂鸟传粉。","一串红不耐寒，遇霜即枯，在中国北方多作一年生栽培。","国庆期间的城市花坛常以一串红为主色，搭配万寿菊形成红黄对比。"]},"flower-coleus":{"description":"彩叶草为唇形科鞘蕊花属多年生草本，常作一二年生栽培，株高 30–80 厘米，茎四棱形，多分枝。叶片对生，卵形，边缘有锯齿，叶面有红、黄、紫、绿、橙等色彩和斑纹，是观赏的主要部分。轮伞花序排成顶生穗状花序，花小，蓝紫色或白色，花期 8–10 月。\n\n彩叶草原产东南亚爪哇一带，喜温暖、阳光充足和湿润的环境，不耐寒，适合在疏松肥沃的土壤中栽培。它的叶色受光照影响明显：光照充足时颜色鲜艳，光照不足则叶色变淡、茎秆徒长。园艺品种繁多，有大型、小型、皱叶、羽叶等类型，常用于花坛镶边、庭院色块和盆栽观赏；开花会消耗养分、影响叶色，栽培中常及时摘除花穗。","habitat":"东南亚热带林缘与灌丛，喜温暖、湿润、阳光充足","distribution":"原产东南亚，现世界各地广泛栽培，中国各地花坛常见","conservation":"暂无评估","details":[{"label":"株高","value":"30–80 厘米，茎四棱形"},{"label":"花期","value":"8–10 月，花小，蓝紫色"},{"label":"果期","value":"花后结小坚果"},{"label":"光照","value":"喜充足阳光，光照不足叶色变淡"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的壤土"},{"label":"繁殖","value":"以扦插为主，也可播种"},{"label":"主要用途","value":"花坛镶边、庭院色块、盆栽观叶"}],"facts":["彩叶草观赏的是叶片，叶面颜色和斑纹会随光照强弱发生变化。","它的花小而密集，开花会消耗养分，栽培中常摘除花穗保持叶色。","彩叶草扦插极易成活，剪一段茎插入水中就能生根。","园艺品种有皱叶、羽叶等类型，叶色从鲜红到紫黑应有尽有。"]},"flower-cockscomb":{"description":"鸡冠花为苋科青葙属一年生草本，株高 30–90 厘米，茎直立粗壮，少分枝。叶片披针形至卵形，互生，有红、绿两色。花序顶生，扁平肉质、皱褶如鸡冠，也有羽毛状和圆球状类型，颜色有红、橙、黄、紫、白等，花期 7–10 月；果实为胞果，种子细小、黑色。\n\n鸡冠花原产热带亚洲，喜温暖、阳光充足和干燥的环境，不耐寒、怕积水，适应性强，常自播繁殖。它的花序形态独特、颜色浓艳，适合布置花坛、花境，也可剪下作干花；嫩叶可作蔬菜食用，种子即中药青葙子，有清肝明目之效。鸡冠花在中国栽培历史悠久，是夏秋季节常见的庭院与路旁花卉，也常用于花境镶边。","habitat":"热带亚洲的向阳草地与田边，喜温暖、阳光充足、干燥","distribution":"原产热带亚洲，中国各地广泛栽培，南北均有种植","conservation":"暂无评估","details":[{"label":"株高","value":"30–90 厘米，茎直立粗壮"},{"label":"花期","value":"7–10 月，花序扁平如鸡冠"},{"label":"果期","value":"9–11 月，胞果，种子黑色"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"耐旱，忌积水"},{"label":"土壤","value":"疏松、排水良好的沙壤土"},{"label":"繁殖","value":"以播种为主，自播能力强"},{"label":"主要用途","value":"花坛观赏、干花、嫩叶食用、种子入药"}],"facts":["鸡冠花的花序扁平、皱褶，形似鸡冠，因此得名。","除鸡冠型外，还有羽毛型、圆球型的园艺类型。","它的种子即中药青葙子，有清肝明目的功效。","鸡冠花花序剪下倒挂阴干后仍能保持形态，可作干花。"]},"flower-globe-amaranth":{"description":"千日红为苋科千日红属一年生草本，株高 20–60 厘米，茎直立，多分枝，全株被白色柔毛。叶片对生，长椭圆形，表面粗糙。头状花序球形或长圆形，直径 2–3 厘米，由多数膜质小花的苞片组成，有紫红、粉、白等色，花期 7–10 月；果实为胞果。\n\n千日红原产热带美洲，喜温暖、阳光充足和干燥的环境，不耐寒、怕积水，对土壤要求不严。它的花被片为膜质，干燥后颜色和形态能保持很久，因此得名“千日红”，是制作干花和花环的常用材料；花序也可泡茶，民间认为有平肝明目之效。栽培以春播为主，生长期适当摘心可促发分枝、增加花量，花后及时剪除残花还能再开一茬。","habitat":"热带美洲的向阳草地与田边，喜温暖、干燥、阳光充足","distribution":"原产热带美洲，现世界温暖地区广泛栽培，中国南北均有种植","conservation":"暂无评估","details":[{"label":"株高","value":"20–60 厘米，茎多分枝"},{"label":"花期","value":"7–10 月，球状花序"},{"label":"果期","value":"9–11 月，胞果"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"耐旱，忌积水"},{"label":"土壤","value":"疏松、排水良好的壤土"},{"label":"繁殖","value":"以播种为主"},{"label":"主要用途","value":"花坛观赏、干花制作、花序泡茶"}],"facts":["千日红的花被片为膜质，干燥后仍能长期保持颜色，因此得名。","它的圆球状花序由许多小花组成，实际是一团密集的苞片和小花。","千日红是制作干花和花环的常用材料，剪下倒挂阴干即可。","花序晒干后可泡茶，民间认为有平肝明目之效。"]},"flower-balsam":{"description":"凤仙花为凤仙花科凤仙花属一年生草本，株高 40–100 厘米，茎肉质、直立，节部膨大。叶片互生，披针形，边缘有锯齿，叶柄两侧有腺体。花单生或数朵簇生于叶腋，有单瓣和重瓣，颜色有红、粉、白、紫等，花期 6–8 月；果实为椭圆形蒴果，成熟后轻轻一碰就会弹裂，种子弹出。\n\n凤仙花原产印度、东南亚一带，中国栽培历史悠久，喜温暖、阳光充足和湿润的环境，不耐寒，常自播繁殖。花瓣中含有天然色素，民间常把红色花瓣捣碎加明矾，用来染指甲，因此得名“指甲花”；茎、根和种子均可入药，种子即中药“急性子”，有活血化瘀之效。它的果实弹裂传播种子的特性十分有趣，英文属名意为“没有耐心的”，正指这种一触即裂的果实。","habitat":"印度与东南亚的温暖湿润林缘，喜光、喜湿、不耐寒","distribution":"原产印度与东南亚，中国各地庭院广泛栽培，常见自播种群","conservation":"暂无评估","details":[{"label":"株高","value":"40–100 厘米，茎肉质，节部膨大"},{"label":"花期","value":"6–8 月，单瓣或重瓣"},{"label":"果期","value":"8–10 月，蒴果一触即裂"},{"label":"光照","value":"喜充足阳光，也耐半阴"},{"label":"水分","value":"喜湿润，忌干旱"},{"label":"土壤","value":"疏松肥沃、排水良好的壤土"},{"label":"繁殖","value":"以播种为主，自播能力强"},{"label":"主要用途","value":"庭院观赏、花瓣染指甲、全草入药"}],"facts":["凤仙花果实成熟后轻轻一碰就会弹裂，把种子弹出很远。","红色花瓣捣碎加明矾可染指甲，因此民间称它“指甲花”。","英文属名 Impatiens 意为“没有耐心的”，形容果实一触即裂的特性。","它的种子是中药“急性子”，茎和根也可入药。"]},"flower-chinese-pink":{"description":"石竹为石竹科石竹属多年生草本，常作二年生栽培，株高 30–50 厘米，茎直立，节部膨大，全株带白粉。叶片线状披针形，对生，灰绿色。花单生或数朵聚生茎顶，花瓣 5 枚，边缘有锯齿或须状深裂，有红、粉、白、紫及复色，喉部常有斑纹，花期 5–9 月；果实为蒴果。\n\n石竹原产中国北方、朝鲜半岛一带，喜凉爽、阳光充足和排水良好的环境，耐寒耐旱，怕积水和酷热，常用于花坛、花境和岩石园。它的茎节膨大、叶似竹叶，故得名“石竹”；栽培历史悠久，是传统名花之一。石竹花朵耐瓶插，可作切花；全草可入药；同属的康乃馨是它的近亲，二者花瓣边缘都有锯齿。","habitat":"中国北方的向阳山坡、草地与石缝，喜凉爽、阳光充足","distribution":"原产中国北方及朝鲜半岛，中国各地栽培，俄罗斯也有分布","conservation":"暂无评估","details":[{"label":"株高","value":"30–50 厘米，节部膨大"},{"label":"花期","value":"5–9 月，单花可开 1 周左右"},{"label":"果期","value":"7–10 月，蒴果"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"耐旱，忌积水"},{"label":"土壤","value":"疏松、排水良好的石灰质壤土"},{"label":"繁殖","value":"以播种为主，也可扦插"},{"label":"主要用途","value":"花坛、花境、切花，全草入药"}],"facts":["石竹的茎节膨大、叶片似竹叶，因此得名“石竹”。","它的花瓣边缘有锯齿或须状深裂，与康乃馨同属，形态相似。","石竹原产中国，是传统名花，耐寒耐旱，适合布置岩石园。","石竹花剪下瓶插可保持一周左右，是常用的切花材料。"]},"flower-geranium":{"description":"天竺葵为牻牛儿苗科天竺葵属多年生草本，常作亚灌木状栽培，株高 30–60 厘米，茎肉质，多分枝，全株被短毛。叶片圆形至肾形，边缘有浅裂和锯齿，表面有暗色环纹，揉碎后有特殊气味。伞形花序顶生，由多数小花组成球状，花有红、粉、白、橙等色，花期 5–7 月，温暖地区可全年开花。\n\n天竺葵原产南非，园艺品种多为杂交选育，喜凉爽、阳光充足和通风良好的环境，怕高温高湿和积水，夏季高温时生长停滞。它花球饱满、花期长，是欧洲窗台花箱的经典植物；叶片含挥发油，揉碎后有独特香气，同属的香叶天竺葵可用于提取玫瑰香精。栽培以扦插为主，花后修剪残花和过密枝条可促进再次开花。","habitat":"南非的干燥山坡与灌丛，喜凉爽、阳光充足、通风","distribution":"原产南非，现世界各地广泛盆栽，中国各地常见","conservation":"暂无评估","details":[{"label":"株高","value":"30–60 厘米，茎肉质多分枝"},{"label":"花期","value":"5–7 月，温暖地区可全年开花"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜充足阳光，夏季需遮阴"},{"label":"水分","value":"喜干燥，忌积水"},{"label":"土壤","value":"疏松、排水良好的沙壤土"},{"label":"繁殖","value":"以扦插为主"},{"label":"主要用途","value":"窗台盆栽、花坛、提取香精"}],"facts":["天竺葵的花序由许多小花组成球状，远看像绣球，故又称“洋绣球”。","揉碎它的叶片会闻到特殊气味，同属的香叶天竺葵可提取玫瑰香精。","天竺葵怕高温高湿，夏季闷热时容易落叶甚至腐烂。","它是欧洲窗台花箱的经典植物，花球丰满、花期长。"]},"flower-nasturtium":{"description":"旱金莲为旱金莲科旱金莲属一年生蔓生草本，茎柔软、匍匐或攀援，长 1–3 米。叶片互生，圆形盾状，形似小荷叶，叶柄着生于叶片中央，边缘波状。花单生叶腋，花瓣 5 枚，有橙、黄、红等色，后方一枚花瓣有长距，花期 6–10 月；果实为瘦果。\n\n旱金莲原产南美洲安第斯山区，喜凉爽、阳光充足和湿润的环境，不耐酷热，盛夏生长变弱。它的花和嫩叶带类似芥末的辛辣味，可拌沙拉或作装饰，花蕾和未成熟的果实还可腌制成类似酸豆的调味品。旱金莲蔓生性强，适合种在花坛边缘、篱笆旁或垂吊花盆中，让枝条自然垂挂；栽培以播种为主，也可在春季扦插，蔓生枝条生长很快。","habitat":"南美安第斯山区的凉爽坡地，喜凉爽、阳光充足","distribution":"原产南美洲安第斯山区，世界各地广泛栽培，中国各地庭园常见","conservation":"暂无评估","details":[{"label":"株高","value":"蔓长 1–3 米，茎匍匐或攀援"},{"label":"花期","value":"6–10 月，单朵花有长距"},{"label":"果期","value":"8–10 月，瘦果"},{"label":"光照","value":"喜充足阳光，夏季需适度遮阴"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的壤土"},{"label":"繁殖","value":"以播种为主，也可扦插"},{"label":"主要用途","value":"花坛垂吊观赏、花叶食用"}],"facts":["旱金莲的叶片圆盾形、叶柄长在叶片中央，形似小荷叶。","它的花和嫩叶带类似芥末的辛辣味，可拌沙拉食用。","未成熟的果实腌渍后可作酸豆的代用品。","旱金莲后方一枚花瓣有细长的距，是识别它的特征之一。"]},"flower-verbena":{"description":"美女樱为马鞭草科美女樱属多年生草本，常作一年生栽培，株高 20–50 厘米，茎匍匐或斜升，四棱形，全株被短毛。叶片对生，长圆形至披针形，边缘有粗锯齿。伞房花序顶生，由多数小花密集组成，花冠 5 裂，有红、粉、紫、白、蓝等色，花期 5–10 月；果实为蒴果。\n\n美女樱原产南美洲巴西、阿根廷一带，园艺品种多为杂交种，喜阳光充足、温暖湿润和通风良好的环境，较耐寒但不耐酷热，盛夏需适当遮阴。它枝条匍匐、着花密集，是花坛镶边、坡地地被和吊篮的理想材料，成片种植时可形成彩色花毯。栽培以扦插和播种为主，生长期摘心可促使分枝、增加花量，花后修剪可延长观赏期。","habitat":"南美草原与河岸，喜阳光充足、温暖湿润","distribution":"原产南美洲，现世界各地广泛栽培，中国各地花坛常见","conservation":"暂无评估","details":[{"label":"株高","value":"20–50 厘米，茎匍匐或斜升"},{"label":"花期","value":"5–10 月，花序密集"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜充足阳光，盛夏适当遮阴"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的壤土"},{"label":"繁殖","value":"扦插、播种"},{"label":"主要用途","value":"花坛镶边、地被、吊篮"}],"facts":["美女樱的花序由许多小花密集成团，盛开时像一块彩色花毯。","它的茎匍匐生长，是花坛镶边和吊篮绿化的理想材料。","美女樱较耐寒但不耐酷热，盛夏高温时开花会明显减少。","生长期摘心可促进分枝，让株形更饱满、花量更大。"]},"flower-snapdragon":{"description":"金鱼草为车前科金鱼草属多年生草本，常作一二年生栽培，株高 20–100 厘米，茎直立，多分枝。叶片披针形至长圆形，对生或上部互生。总状花序顶生，花冠唇形，基部膨大呈囊状，下唇有隆起，形似金鱼嘴，有红、黄、粉、白、橙等色，花期 5–10 月；果实为蒴果。\n\n金鱼草原产地中海沿岸，喜凉爽、阳光充足和排水良好的环境，耐寒性较强，怕酷热和积水。它的花唇在两侧被轻捏时会像小嘴一样张合，英文名意为“龙嘴”，欧洲人还相信把花放在掌心捏一下能带来好运。金鱼草花序挺拔、花色明快，是花境中优良的竖线条材料，也是切花和盆栽的常见品种；栽培以秋播或春播为主，摘心可促进分枝。","habitat":"地中海沿岸的岩石坡地，喜凉爽、阳光充足、排水良好","distribution":"原产地中海沿岸，现世界各地广泛栽培，中国各地花坛常见","conservation":"暂无评估","details":[{"label":"株高","value":"20–100 厘米，茎直立多分枝"},{"label":"花期","value":"5–10 月，花序自下而上开放"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜充足阳光，也耐轻度半阴"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松、排水良好的壤土"},{"label":"繁殖","value":"以播种为主"},{"label":"主要用途","value":"花境、切花、盆栽"}],"facts":["金鱼草的花冠形似金鱼嘴，捏住两侧花瓣时上下唇会张合。","它的英文名意为“龙嘴”，欧洲传说捏一下花能带来好运。","金鱼草花序自下而上依次开放，整串花期可持续数周。","花色丰富，从纯白、黄色到深红、紫红都有，是花境的常用材料。"]},"flower-foxglove":{"description":"毛地黄为车前科毛地黄属二年生或多年生草本，株高 0.6–1.5 米，茎直立，全株被灰白色短毛。叶片基生呈莲座状，卵形至长椭圆形，叶面皱褶。总状花序顶生，花冠钟形、下垂，长 4–5 厘米，紫红、粉或白色，喉部常有斑点，花期 5–7 月；果实为蒴果。\n\n毛地黄原产欧洲西部，喜凉爽、半阴和湿润的环境，常见于林缘、荒地和石墙边，靠种子繁殖，常成片生长。它是重要的药用植物，叶片含洋地黄毒苷等强心苷，可用于提取治疗心力衰竭的药物，但全株剧毒，剂量极难掌握，必须由专业人员使用，普通人切勿采食或自行入药。毛地黄花形如垂挂的铃铛，英文名意为“狐狸手套”，也是花境中富有野趣的竖线条花卉。","habitat":"欧洲西部的林缘、荒地与石墙边，喜凉爽、半阴、湿润","distribution":"原产欧洲西部，现世界温带地区栽培或归化，中国庭园有引种","conservation":"暂无评估","details":[{"label":"株高","value":"0.6–1.5 米，全株被短毛"},{"label":"花期","value":"5–7 月，钟形花下垂"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜半阴，也耐散射光"},{"label":"水分","value":"喜湿润，忌干旱"},{"label":"土壤","value":"肥沃、富含腐殖质的微酸性土壤"},{"label":"繁殖","value":"以播种为主"},{"label":"主要用途","value":"花境观赏、提取强心苷类药物"}],"facts":["毛地黄是提取洋地黄毒苷等强心苷的药用植物，但全株剧毒。","它的钟形花冠下垂如串铃，英文名意为“狐狸手套”。","毛地黄叶片含强心苷，剂量极难掌握，必须由专业人员使用。","欧洲野外常见毛地黄成片生长在林缘和石墙边，是典型的高大野生花卉。"]},"flower-forget-me-not":{"description":"勿忘我为紫草科勿忘我属多年生草本，株高 15–30 厘米，全株被柔毛。叶片基生和互生，长椭圆形至匙形。聚伞花序呈螺旋状弯曲，花小，直径 5–8 毫米，花冠 5 裂，天蓝色，喉部有黄色小孔，花期 5–6 月；果实为小坚果。\n\n勿忘我原产欧洲阿尔卑斯山等高寒地区，喜凉爽、湿润和半阴的环境，耐寒性较强，忌高温和积水。它的蓝色小花密集如云，常成片生长在高山草甸和林缘。在欧洲，勿忘我象征忠贞与思念，流传着骑士与恋人的美丽传说；花枝剪下后可制作干花，也能作花束的配材。栽培以播种为主，适合布置花境、岩石园和盆花，也可成片种于林下。","habitat":"欧洲高山的草甸与林缘，喜凉爽、湿润、半阴","distribution":"原产欧洲山地，世界温带地区广泛栽培，中国北方有引种","conservation":"暂无评估","details":[{"label":"株高","value":"15–30 厘米，全株被柔毛"},{"label":"花期","value":"5–6 月，小花天蓝色"},{"label":"果期","value":"花后结小坚果"},{"label":"光照","value":"喜半阴散射光，忌强光暴晒"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、富含腐殖质的壤土"},{"label":"繁殖","value":"以播种为主"},{"label":"主要用途","value":"花束配材、干花、岩石园观赏"}],"facts":["勿忘我的花语是“不要忘记我”，是表达思念与忠贞的经典花卉。","它的聚伞花序呈螺旋状弯曲，小花沿一侧依次开放。","花冠天蓝色、喉部有黄色小孔，是识别勿忘我的重要特征。","花枝剪下倒挂阴干后可作干花，也常作花束的配材。"]},"flower-canterbury-bells":{"description":"风铃草为桔梗科风铃草属二年生草本，株高 60–100 厘米，茎直立，全株被粗毛。叶片披针形至卵形，基生叶有长柄。总状花序顶生，花冠钟形或杯形，长 4–5 厘米，有蓝紫、粉、白等色，花冠 5 裂，花期 5–6 月；果实为蒴果，成熟后自顶部开裂。\n\n风铃草原产欧洲南部意大利一带，喜凉爽、阳光充足和排水良好的环境，耐寒而不耐高温高湿，常作二年生栽培，第一年长叶、第二年开花。它的钟形花朵沿茎成串排列，风吹时轻轻摇曳，宛如铃铛，因此得名；英文名意为“坎特伯雷的钟”。风铃草是花境和庭院中优良的竖线条材料，也可作切花，栽培以秋播为主。","habitat":"南欧的岩石坡地与林缘，喜凉爽、阳光充足、排水良好","distribution":"原产欧洲南部，现世界温带地区广泛栽培，中国庭园有引种","conservation":"暂无评估","details":[{"label":"株高","value":"60–100 厘米，全株被粗毛"},{"label":"花期","value":"5–6 月，钟形花成串开放"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜充足阳光，夏季需适当遮阴"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松、排水良好的石灰质壤土"},{"label":"繁殖","value":"以秋播为主"},{"label":"主要用途","value":"花境、庭院点缀、切花"}],"facts":["风铃草的钟形花朵成串垂挂，风吹时摇曳如铃，因此得名。","它是二年生植物，第一年只长叶，第二年才抽葶开花。","英文名意为“坎特伯雷的钟”，在欧洲庭园栽培历史悠久。","花冠顶端 5 裂，裂片向外翻卷，是识别风铃草的标志。"]},"flower-balloon-flower":{"description":"桔梗为桔梗科桔梗属多年生草本，株高 40–90 厘米，具肥厚肉质根，茎直立，少分枝。叶片卵形至披针形，边缘有锯齿，互生或轮生。花单生茎顶或数朵组成总状花序，花冠钟状，蓝色或蓝紫色，未开放时花苞膨大如气球，花期 6–8 月；果实为蒴果，成熟后开裂散种。\n\n桔梗原产东亚，中国、日本、朝鲜半岛的山坡草地和林缘都能见到，喜阳光充足、凉爽干燥和排水良好的环境，耐寒不耐积水。它的根富含皂苷，是中药“桔梗”的来源，有宣肺祛痰之效；在朝鲜半岛，桔梗根经盐渍、拌辣酱后制成泡菜，是传统小菜。桔梗花形独特、花期长，也常作花境和盆栽观赏，英文名直译即“气球花”。","habitat":"东亚的山坡草地与林缘，喜阳光充足、凉爽干燥","distribution":"原产东亚，中国、日本、朝鲜半岛广泛分布与栽培","conservation":"暂无评估","details":[{"label":"株高","value":"40–90 厘米，具肥厚肉质根"},{"label":"花期","value":"6–8 月，花苞膨大如气球"},{"label":"果期","value":"8–10 月，蒴果开裂散种"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"耐旱，忌积水"},{"label":"土壤","value":"疏松、排水良好的沙壤土"},{"label":"繁殖","value":"以播种和分株为主"},{"label":"主要用途","value":"花境观赏、根入药、朝鲜族泡菜原料"}],"facts":["桔梗未开放的花苞鼓鼓的像气球，因此英文名意为“气球花”。","它的根是中药“桔梗”的来源，有宣肺祛痰的功效。","在朝鲜半岛，桔梗根常被制成拌辣酱的泡菜。","桔梗花冠钟形、蓝色或蓝紫色，花苞开放时会“啪”地弹开。"]},"flower-japanese-sage":{"description":"鼠尾草为唇形科鼠尾草属多年生草本，株高 40–80 厘米，茎四棱形，多分枝，全株被短柔毛。叶片对生，卵形至披针形，边缘有锯齿。轮伞花序排列成顶生的总状花序，花序细长、略弯曲，形似鼠尾，花冠唇形，蓝紫色或淡紫色，花期 6–9 月；果实为小坚果。\n\n鼠尾草原产中国和日本，生于山坡草地、林缘和路旁，喜阳光充足、温暖湿润和排水良好的环境。它与欧洲烹饪常用的鼠尾草同属不同种，后者叶片厚、灰绿色、气味浓烈，而本种以观赏为主，花序蓝紫、细长飘逸，适合布置花境和庭院石边。鼠尾草全草可入药，有清热利湿之效；栽培以播种和扦插为主，花后修剪可促进二次开花。","habitat":"中国和日本的山坡草地、林缘与路旁，喜光、喜湿润","distribution":"原产中国与日本，中国长江流域及以南地区常见","conservation":"暂无评估","details":[{"label":"株高","value":"40–80 厘米，茎四棱形"},{"label":"花期","value":"6–9 月，花序细长如鼠尾"},{"label":"果期","value":"花后结小坚果"},{"label":"光照","value":"喜充足阳光，也耐半阴"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的壤土"},{"label":"繁殖","value":"播种、扦插"},{"label":"主要用途","value":"花境观赏、庭院点缀、全草入药"}],"facts":["鼠尾草的花序细长、略弯曲，形似老鼠尾巴，因此得名。","它与欧洲烹饪用的鼠尾草同属不同种，后者叶片厚、气味浓烈。","本种主要作观赏，蓝紫色花序轻盈飘逸，适合花境种植。","全草可入药，有清热利湿之效，但须遵医嘱使用。"]},"flower-wax-begonia":{"description":"四季海棠为秋海棠科秋海棠属多年生草本，常作一年生栽培，株高 15–30 厘米，茎肉质、多汁，稍分枝。叶片互生，卵形至心形，边缘有细齿，表面光亮，绿色或带红晕。花单性同株，雌雄花同生于一花序，花有红、粉、白等色，花期 4–10 月，温暖地区可全年开花；果实为蒴果。\n\n四季海棠原产南美洲巴西，喜温暖、湿润和半阴的环境，忌强光暴晒和高温干旱，在疏松肥沃的土壤中生长良好。它叶片肉质、花朵繁密，花期长，是窗台、花坛和吊篮的常见材料，也适合室内盆栽。栽培以播种、扦插为主，浇水时避免淋在叶片上，否则高温时容易引发叶斑病；花后修剪残花可促进新花不断开放。","habitat":"巴西的林下与溪边，喜温暖、湿润、半阴","distribution":"原产南美巴西，现世界各地广泛栽培，中国各地常见","conservation":"暂无评估","details":[{"label":"株高","value":"15–30 厘米，茎肉质"},{"label":"花期","value":"4–10 月，温暖地区全年开花"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜半阴散射光，忌强光暴晒"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的腐殖质土"},{"label":"繁殖","value":"播种、扦插"},{"label":"主要用途","value":"窗台盆栽、花坛、吊篮"}],"facts":["四季海棠的花为单性花，雌花和雄花同生于一个花序上。","它的叶片肉质光亮，能储存水分，但怕烈日暴晒。","四季海棠耐阴，在散射光下也能持续开花，适合室内栽培。","浇水时避免淋湿叶片，高温高湿时容易引发叶斑病。"]},"flower-cyclamen":{"description":"仙客来为报春花科仙客来属多年生球根草本，株高 20–30 厘米，地下具扁球形块茎。叶片心形至肾形，表面有银白色斑纹，叶柄长。花单生，花梗自块茎抽出，花瓣 5 枚、向上翻卷，形似兔耳，有红、粉、白、紫等色，花期 10 月至翌年 4 月；果实为蒴果，花后花梗卷曲。\n\n仙客来原产地中海东部，喜凉爽、湿润和半阴的环境，夏季高温时块茎休眠，秋凉后重新萌芽，冬季开花。它花形奇特、花色艳丽，是圣诞和春节期间重要的年宵花，盆栽摆放在室内明亮处即可长期观赏。栽培时浇水不宜淋在块茎和叶心，否则容易腐烂；花后花梗会卷曲把种子推向土面，这是它传播种子的一种方式。","habitat":"地中海东部的林下与岩石坡地，喜凉爽、湿润、半阴","distribution":"原产地中海东部，现世界各地广泛盆栽，中国各地年宵花市常见","conservation":"暂无评估","details":[{"label":"株高","value":"20–30 厘米，具扁球形块茎"},{"label":"花期","value":"10 月至翌年 4 月"},{"label":"果期","value":"花后结蒴果，花梗卷曲"},{"label":"光照","value":"喜明亮散射光，忌强光"},{"label":"水分","value":"喜湿润，忌淋湿块茎和叶心"},{"label":"土壤","value":"疏松透气、排水良好的腐殖质土"},{"label":"繁殖","value":"以播种为主"},{"label":"主要用途","value":"年宵花、室内盆栽观赏"}],"facts":["仙客来的花瓣向上翻卷，形似兔耳，因此别称“兔耳花”。","花后花梗会卷曲，把种子推向土面，便于种子传播。","仙客来夏季高温时块茎休眠，秋凉后才重新萌芽。","浇水时若淋湿块茎和叶心，容易导致腐烂，应沿盆边浇水。"]},"flower-african-daisy":{"description":"非洲菊为菊科非洲菊属多年生草本，株高 30–60 厘米，叶基生，呈莲座状，叶片长椭圆形，羽状浅裂，背面有短毛。花葶自叶丛抽出，头状花序单生，直径 8–15 厘米，舌状花多层，有红、橙、黄、粉、白等色，中央管状花密集，花期 4–11 月；果实为瘦果。\n\n非洲菊原产南非，喜温暖、阳光充足和通风良好的环境，不耐寒也不耐酷热，适合在疏松肥沃、排水良好的土壤中栽培。它是世界五大切花之一，花大色艳、瓶插寿命长，常用于花束、花篮和婚礼布置；在中国，非洲菊也被称作“扶郎花”。栽培以分株和组织培养繁殖为主，切花采收时斜剪花梗并用清水养，可延长观赏期。","habitat":"南非的草原与山坡，喜温暖、阳光充足、通风","distribution":"原产南非，现世界各地广泛栽培，中国云南是重要产区","conservation":"暂无评估","details":[{"label":"株高","value":"30–60 厘米，叶基生莲座状"},{"label":"花期","value":"4–11 月，温室可全年开花"},{"label":"果期","value":"花后结瘦果"},{"label":"光照","value":"喜充足阳光，夏季高温需遮阴"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的沙壤土"},{"label":"繁殖","value":"分株、组织培养"},{"label":"主要用途","value":"切花、花束、花篮、盆栽"}],"facts":["非洲菊是世界五大切花之一，花大色艳、瓶插寿命长。","它的头状花序由外围舌状花和中央管状花组成，颜色丰富。","非洲菊在中国也称“扶郎花”，是花篮和花束的常用花材。","采收切花时斜剪花梗、及时换水，可以明显延长观赏期。"]},"flower-gazania":{"description":"勋章菊为菊科勋章菊属多年生草本，常作一年生栽培，株高 20–30 厘米，茎匍匐或斜生，叶片披针形，羽状深裂，叶背密被白色绒毛。头状花序单生，直径 6–10 厘米，舌状花橙黄、金黄或白色，基部有深色环纹，形似勋章，花期 4–10 月；果实为瘦果。\n\n勋章菊原产南非的海岸沙地与草原，喜阳光充足、温暖干燥和排水良好的环境，耐旱力强，怕积水和阴湿。它的花序在白天光照充足时开放，傍晚和阴天闭合，是典型的“日出而作”的菊科花卉。勋章菊花大色艳、花期长，适合布置花坛、花境和岩石园，也可作地被和盆栽，在温暖地区能全年开花，是南方冬季花坛的常见选择。","habitat":"南非的海岸沙地与草原，喜光、耐旱、怕积水","distribution":"原产南非，现世界各地广泛栽培，中国各地花坛常见","conservation":"暂无评估","details":[{"label":"株高","value":"20–30 厘米，茎匍匐或斜生"},{"label":"花期","value":"4–10 月，温暖地区全年开花"},{"label":"果期","value":"花后结瘦果"},{"label":"光照","value":"极喜光，光照不足花朵闭合"},{"label":"水分","value":"耐旱，忌积水"},{"label":"土壤","value":"疏松、排水良好的沙质土"},{"label":"繁殖","value":"以播种和扦插为主"},{"label":"主要用途","value":"花坛、花境、岩石园、地被"}],"facts":["勋章菊的舌状花基部有深色环纹，形似勋章，因此得名。","它的花白天开放、傍晚和阴天闭合，是典型的日开夜合花卉。","勋章菊原产南非海岸，叶片背面密生白色绒毛，可减少水分蒸发。","它耐旱耐贫瘠，是花坛和岩石园中管理粗放的好材料。"]},"flower-english-daisy":{"description":"雏菊为菊科雏菊属多年生草本，常作二年生栽培，株高 5–15 厘米，叶基生，倒卵形至匙形，排成莲座状。头状花序单生，直径 2–4 厘米，舌状花白色或粉红色，中央管状花黄色，花期 3–5 月；果实为瘦果。\n\n雏菊原产欧洲，常见于草地、路旁和草坪，喜凉爽、阳光充足和湿润的环境，耐寒性较强，忌酷热。它的花白天开放，傍晚和阴天闭合，英文名由“白天的眼睛”演化而来，形容花朵随日开合。雏菊植株矮小、花朵密集，是早春花坛和草坪边缘的常见点缀，也常与三色堇、郁金香搭配布置；栽培以秋播为主，也可分株繁殖；植株矮小，适合与郁金香、风信子等球根花卉混植。","habitat":"欧洲的草地、草坪与路旁，喜凉爽、阳光充足","distribution":"原产欧洲，现世界各地广泛栽培，中国各地常见","conservation":"暂无评估","details":[{"label":"株高","value":"5–15 厘米，叶基生莲座状"},{"label":"花期","value":"3–5 月，单朵花晨开暮合"},{"label":"果期","value":"花后结瘦果"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"喜湿润，忌干旱"},{"label":"土壤","value":"疏松肥沃、排水良好的壤土"},{"label":"繁殖","value":"以秋播为主，也可分株"},{"label":"主要用途","value":"花坛、草坪边缘、盆栽"}],"facts":["雏菊的花白天开放、傍晚闭合，英文名意为“太阳之眼”。","雏菊植株矮小、花朵密集，是早春花坛和草坪边缘的常见点缀。","在欧美庭院中，雏菊常被视为天真、纯洁的象征。","它耐寒性较强，早春即可开花，是春季最早开放的花卉之一。"]},"flower-pot-marigold":{"description":"金盏菊为菊科金盏花属一年生草本，株高 30–60 厘米，茎直立，多分枝，全株被短毛。叶片长椭圆形至倒卵形，互生。头状花序单生茎顶，直径 4–7 厘米，舌状花橙黄或金黄色，多层排列，花期 4–9 月；果实为瘦果，弯曲呈船形。\n\n金盏菊原产地中海沿岸，喜凉爽、阳光充足和排水良好的环境，耐寒不耐酷热，能自播繁衍。它的花瓣富含类胡萝卜素，可提取天然黄色素，也常被用来点缀沙拉、汤和甜点；在欧洲传统医学中，金盏菊的花可入药，制成软膏用于护理皮肤。金盏菊在欧美常被种在蔬菜和药草园中，兼具观赏与实用价值，花期长、管理简单，播种后约 60 天即可开花。","habitat":"地中海沿岸的向阳坡地与田边，喜凉爽、阳光充足","distribution":"原产地中海沿岸，现世界各地广泛栽培，中国各地花坛常见","conservation":"暂无评估","details":[{"label":"株高","value":"30–60 厘米，全株被短毛"},{"label":"花期","value":"4–9 月，晴天开放"},{"label":"果期","value":"花后结瘦果，弯曲呈船形"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松、排水良好的壤土"},{"label":"繁殖","value":"以播种为主，能自播"},{"label":"主要用途","value":"花坛观赏、花瓣食用、提取色素、药用"}],"facts":["金盏菊的橙黄色花瓣富含类胡萝卜素，可提取天然黄色素。","花瓣可点缀沙拉和汤，也常被用于制作护肤品和药膏。","金盏菊的花在晴天开放、傍晚闭合，阴雨天也不完全展开。","它耐寒不耐酷热，能自播繁衍，是药草园中的常见植物。"]},"flower-china-aster":{"description":"翠菊为菊科翠菊属一年生草本，株高 30–80 厘米，茎直立，全株被白色糙毛。叶片卵形至长椭圆形，边缘有粗锯齿。头状花序单生茎顶，直径 5–10 厘米，有单瓣、重瓣之分，花色有蓝紫、紫红、粉、白等，花期 7–10 月；果实为瘦果。\n\n翠菊原产中国，是该属唯一的物种，朝鲜半岛和日本也有分布，喜凉爽、阳光充足和排水良好的环境，不耐酷热和积水。它花型丰满、花色明快，是花坛、花境和切花的常用材料，重瓣品种尤其受欢迎。翠菊在中国栽培历史悠久，别名“江西腊”；栽培以春播为主，注意轮作，避免连作导致枯萎病；高秆品种可作切花，矮生品种适合花坛边缘。","habitat":"中国的山坡草地与林缘，喜凉爽、阳光充足","distribution":"原产中国，朝鲜半岛、日本也有分布，世界温带地区广泛栽培","conservation":"暂无评估","details":[{"label":"株高","value":"30–80 厘米，全株被糙毛"},{"label":"花期","value":"7–10 月，单株花期约 1 个月"},{"label":"果期","value":"花后结瘦果"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的壤土"},{"label":"繁殖","value":"以播种为主"},{"label":"主要用途","value":"花坛、花境、切花"}],"facts":["翠菊属只有翠菊一个物种，是原产中国的单种属植物。","它的花色有蓝紫、紫红、粉、白等，重瓣品种花形丰满。","翠菊别名“江西腊”，在中国已有悠久的栽培历史。","翠菊忌连作，同一地块连续种植容易发生枯萎病。"]},"flower-giant-onion":{"description":"大花葱为石蒜科葱属多年生球根草本，株高 0.8–1.5 米，地下具球形鳞茎。叶片基生，带状，灰绿色。花葶粗壮直立，顶端生球形伞形花序，直径可达 15–20 厘米，由上千朵小花密集组成，花色紫红或淡紫，花期 5–6 月；果实为蒴果。\n\n大花葱原产中亚、阿富汗和伊朗一带的干旱山地，喜凉爽、阳光充足和排水良好的环境，耐寒性强，夏季地上部分枯萎休眠。它的小花密集成球，远看像一个紫色大绒球，花葶高大挺拔，是花境中极具视觉冲击力的竖线条植物，也常作切花。大花葱与洋葱、大蒜同属葱属，叶片揉碎后有葱蒜气味；栽培以播种和分球繁殖为主。","habitat":"中亚干旱山地的草坡与石缝，喜凉爽、阳光充足、排水良好","distribution":"原产中亚、阿富汗与伊朗，现世界各地庭园栽培","conservation":"暂无评估","details":[{"label":"株高","value":"0.8–1.5 米，花球直径 15–20 厘米"},{"label":"花期","value":"5–6 月，花球由上千朵小花组成"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"耐旱，忌积水"},{"label":"土壤","value":"疏松、排水良好的沙质壤土"},{"label":"繁殖","value":"播种、分球"},{"label":"主要用途","value":"花境、切花、岩石园"}],"facts":["大花葱的花球直径可达 15–20 厘米，由上千朵小花密集组成。","它和洋葱、大蒜同属葱属，叶片揉碎后有葱蒜气味。","花葶高大挺拔，是花境中视觉效果突出的竖线条植物。","大花葱夏季地上部分枯萎休眠，鳞茎在土中越夏。"]},"flower-amaryllis":{"description":"朱顶红为石蒜科朱顶红属多年生球根草本，株高 30–60 厘米，地下具球形鳞茎。叶片带状，基生，与花葶同时或稍后抽出。花葶粗壮中空，顶端着花 2–6 朵，花大，喇叭形，直径 10–15 厘米，花色有红、粉、白、橙及条纹，花期 4–6 月；果实为蒴果。\n\n朱顶红原产南美洲巴西一带，喜温暖、阳光充足和湿润的环境，不耐寒，冬季需保持 10℃ 以上。它花大色艳、栽培简单，盆栽时鳞茎半埋即可，是春季和年宵花市常见的球根花卉；近年来进口的重瓣、绿色、条纹品种也越来越多。栽培以分球繁殖为主，也可播种；花后剪去残花、保留叶片养球，翌年才能再次开花。","habitat":"南美巴西的林缘与草地，喜温暖、阳光充足","distribution":"原产南美洲，现世界各地广泛盆栽，中国各地常见","conservation":"暂无评估","details":[{"label":"株高","value":"30–60 厘米，具球形鳞茎"},{"label":"花期","value":"4–6 月，一葶可开 2–6 朵"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜充足阳光，夏季适度遮阴"},{"label":"水分","value":"喜湿润，忌积水烂球"},{"label":"土壤","value":"疏松肥沃、排水良好的沙壤土"},{"label":"繁殖","value":"以分球为主，也可播种"},{"label":"主要用途","value":"盆栽观赏、年宵花、切花"}],"facts":["朱顶红的花大如喇叭，一葶可开 2–6 朵，花色鲜艳。","它原产南美，盆栽时鳞茎半埋土中，浇水不可没过球顶。","花后剪去残花、保留叶片养球，是翌年再次开花的关键。","近年来进口的重瓣、绿色和条纹朱顶红品种越来越受欢迎。"]},"flower-autumn-zephyr-lily":{"description":"葱兰为石蒜科葱莲属多年生球根草本，株高 15–30 厘米，地下具卵形小鳞茎。叶片线形，肉质，深绿色，丛生，形似小葱。花单生花葶顶端，花被片 6 枚，白色，外侧常带淡红晕，花径 3–5 厘米，花期 7–10 月；果实为蒴果。\n\n葱兰原产南美洲阿根廷、乌拉圭一带，喜温暖、阳光充足和湿润的环境，耐半阴，在南方可露地越冬。它常在雨后集中开放，因此英文名意为“雨百合”；花白色、叶片葱绿，成片种植时如同铺了一层白色小花毯，是花坛镶边、林下地被和路边绿化的常用材料。葱兰以分球繁殖为主，鳞茎繁殖快，栽培管理粗放，但忌长期积水，否则鳞茎容易腐烂。","habitat":"南美草原与河岸，喜温暖、阳光充足、耐半阴","distribution":"原产南美洲，中国南方广泛栽培，长江流域可露地越冬","conservation":"暂无评估","details":[{"label":"株高","value":"15–30 厘米，叶线形丛生"},{"label":"花期","value":"7–10 月，雨后集中开放"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜充足阳光，也耐半阴"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的壤土"},{"label":"繁殖","value":"以分球繁殖为主"},{"label":"主要用途","value":"花坛镶边、林下地被、盆栽"}],"facts":["葱兰叶片细长如葱，因此得名；它常在雨后集中开放，英文名意为“雨百合”。","葱兰的花白色、花被片 6 枚，成片开放时像铺了一层白花毯。","它靠小鳞茎分球繁殖，繁殖速度快，栽培管理粗放。","葱兰在南方可露地越冬，是花坛镶边和林下地被的常用植物。"]},"flower-moth-orchid":{"description":"蝴蝶兰为兰科蝴蝶兰属附生草本，无假鳞茎，茎短，叶片肥厚、革质，长圆形，交互排列于茎基。根系粗壮，气生根可附着于树皮或岩石并吸收空气中的水分。花葶自叶腋抽出，长 30–60 厘米，着花数朵至十余朵，花大，形似蝴蝶，有白、粉、紫、黄及斑纹，花期 1–6 月。\n\n蝴蝶兰原产菲律宾和台湾南部等热带地区，附生于雨林树干上，喜温暖、湿润、通风和半阴的环境，忌强光暴晒和积水。它的气生根表面有海绵状的根被，能吸收空气中的水分；栽培常用水苔或树皮作基质。蝴蝶兰单株花期可长达 2–3 个月，是春节年宵花市的主要花卉；花谢后剪去花葶上部，部分植株还能再次抽花。","habitat":"热带雨林的树干与岩石上，喜温暖、湿润、半阴","distribution":"原产菲律宾与台湾南部，现世界各地广泛栽培，中国南方大量生产","conservation":"暂无评估；CITES 附录Ⅱ（兰科植物）","details":[{"label":"株高","value":"花葶长 30–60 厘米，着花数朵至十余朵"},{"label":"花期","value":"1–6 月，单株花期可达 2–3 个月"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜半阴散射光，忌强光暴晒"},{"label":"水分","value":"喜湿润，空气湿度宜 60%–80%"},{"label":"土壤","value":"以水苔、树皮等透气基质附生栽培"},{"label":"繁殖","value":"分株、组培繁殖"},{"label":"主要用途","value":"年宵花、室内盆栽、切花"}],"facts":["蝴蝶兰的花形似蝴蝶，单株花期可长达 2–3 个月。","它是附生植物，气生根表面的海绵状根被能吸收空气中的水分。","蝴蝶兰的学名种加词意为“阿佛洛狄忒”，即希腊神话中的爱与美之神。","花谢后从花葶下部剪断，部分植株还能再次抽出花芽。"]},"flower-dendrobium":{"description":"石斛兰为兰科石斛属附生草本，茎丛生，圆柱形，长 30–60 厘米，节明显，肉质。叶片互生，长圆形，革质，脱落或半脱落。花自茎节抽出，单生或数朵成总状花序，花大，直径 5–8 厘米，有白、粉、紫等色，唇瓣基部常有深色斑块，花期 3–5 月；果实为蒴果。\n\n石斛兰原产中国南方、喜马拉雅地区及东南亚，附生于树干和岩石上，喜温暖、湿润、通风和半阴的环境，忌积水和强光。它是兰科中重要的观赏类群，花姿优雅、花期长，常作盆栽和切花；同时石斛属多个物种是中药材“石斛”的来源，有滋阴清热之效。野生石斛属植物已列入国家重点保护野生植物名录和 CITES 附录Ⅱ，购买时宜选择人工繁殖的植株。","habitat":"亚洲南部的树干与岩石上，喜温暖、湿润、半阴","distribution":"原产中国南方、喜马拉雅地区及东南亚，中国西南与华南有分布","conservation":"暂无评估；中国国家二级重点保护野生植物（石斛属），CITES 附录Ⅱ","details":[{"label":"株高","value":"茎长 30–60 厘米，节明显"},{"label":"花期","value":"3–5 月，花大而艳丽"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜半阴散射光，忌强光"},{"label":"水分","value":"喜湿润，空气湿度宜 60% 以上"},{"label":"土壤","value":"以树皮、水苔等基质附生栽培"},{"label":"繁殖","value":"分株、扦插、组培"},{"label":"主要用途","value":"观赏盆栽、切花、中药材"}],"facts":["石斛兰的茎一节一节的，节间明显，是识别石斛属植物的重要特征。","它附生于树干和岩石上，靠气生根吸收水分和养分。","石斛属多个物种是中药“石斛”的来源，有滋阴清热之效。","野生石斛属植物受国家保护并列入 CITES 附录Ⅱ，宜选购人工繁殖个体。"]},"flower-paphiopedilum":{"description":"杏黄兜兰为兰科兜兰属多年生草本，地生或半附生，株高 10–20 厘米，具短而匍匐的根状茎。叶片 3–5 枚，长圆形，革质，表面有深浅相间的斑纹。花单生花葶顶端，直径 6–8 厘米，杏黄色，唇瓣膨大成兜状，花期 2–4 月；果实为蒴果。\n\n杏黄兜兰原产中国云南西部的高山峡谷，生于海拔 1400–2100 米的石灰岩山地林下，喜凉爽、湿润、通风和半阴的环境。它花形奇特、色泽明丽，被发现后曾在国际兰花界引起轰动，也因过度采挖和栖息地破坏而野生资源锐减。目前兜兰属所有种均被列入 CITES 附录Ⅰ，严禁国际贸易，中国也已将其列入重点保护野生植物名录，人工繁殖个体需通过合法渠道购买。","habitat":"云南西部石灰岩山地林下，喜凉爽、湿润、半阴","distribution":"原产中国云南西部，缅甸北部可能也有分布","conservation":"暂无评估；CITES 附录Ⅰ；列入中国国家重点保护野生植物名录","details":[{"label":"株高","value":"10–20 厘米，叶 3–5 枚"},{"label":"花期","value":"2–4 月，花杏黄色，唇瓣呈兜状"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜半阴散射光，忌强光"},{"label":"水分","value":"喜湿润，空气湿度宜 70% 以上"},{"label":"土壤","value":"疏松透气、富含腐殖质的石灰质基质"},{"label":"繁殖","value":"分株、无菌播种"},{"label":"主要用途","value":"珍稀观赏兰花、保护与繁育研究"}],"facts":["杏黄兜兰的唇瓣膨大成兜状，是兜兰属的典型特征。","它原产云南西部石灰岩山地，被发现后曾轰动国际兰花界。","因过度采挖，兜兰属所有种都被列入 CITES 附录Ⅰ，严禁国际贸易。","人工繁殖杏黄兜兰难度较大，市场上合法个体多来自专业繁育机构。"]},"flower-primrose":{"description":"报春花为报春花科报春花属一二年生草本，株高 20–40 厘米，茎短，全株被白色柔毛。叶片基生，卵形至长椭圆形，边缘有缺刻状锯齿。伞形花序自叶丛中抽出，通常 2–3 轮，花小而密，花冠高脚碟状，5 裂，有粉、红、白、紫等色，花期 1–4 月；果实为蒴果。\n\n报春花原产中国云南、贵州等地，喜凉爽、湿润和半阴的环境，不耐高温和强光，适合在疏松肥沃的土壤中栽培。它开花早，常在春节前后盛开，因此得名“报春花”，是年宵花市和冬春花坛的常见花卉。报春花属种类繁多，中国西南是其分布中心；栽培以播种为主，夏季需遮阴降温，否则容易枯死。","habitat":"中国西南的山地草甸与林缘，喜凉爽、湿润、半阴","distribution":"原产中国云南、贵州等地，中国西南山地为其分布中心","conservation":"暂无评估","details":[{"label":"株高","value":"20–40 厘米，全株被柔毛"},{"label":"花期","value":"1–4 月，伞形花序 2–3 轮"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜半阴散射光，忌强光"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的腐殖质土"},{"label":"繁殖","value":"以播种为主"},{"label":"主要用途","value":"年宵花、冬春花坛、盆栽"}],"facts":["报春花在春节前后开放，因此得名“报春”，是年宵花的常见品种。","它的伞形花序常排成 2–3 轮，小花密集、颜色柔和。","中国西南山地是报春花属的分布中心，野生种类非常丰富。","报春花怕高温强光，夏季需遮阴降温才能安全越夏。"]},"flower-cineraria":{"description":"瓜叶菊为菊科瓜叶菊属多年生草本，常作一二年生栽培，株高 20–50 厘米，茎直立，全株被短柔毛。叶片大，心形至肾形，边缘有波状锯齿，形似瓜叶。头状花序多数，密集排列成伞房状，花有蓝、紫、粉、红、白等色，花期 12 月至翌年 5 月；果实为瘦果。\n\n瓜叶菊原产非洲西北部的加那利群岛，园艺品种多为杂交选育，喜凉爽、湿润和明亮散射光的环境，不耐高温和强光，是典型的冬春盆花。它花序密集、花色丰富，常被用作年宵花和早春花坛的装饰；栽培以播种为主，夏季高温时植株容易枯萎，需要遮阴降温。瓜叶菊的花期集中在冬春，正好填补了寒冷季节观花植物较少的空档。","habitat":"加那利群岛的山地林缘，喜凉爽、湿润、明亮散射光","distribution":"原产加那利群岛，现世界各地广泛盆栽，中国各地年宵花市常见","conservation":"暂无评估","details":[{"label":"株高","value":"20–50 厘米，全株被短柔毛"},{"label":"花期","value":"12 月至翌年 5 月，花序密集"},{"label":"果期","value":"花后结瘦果"},{"label":"光照","value":"喜明亮散射光，忌强光暴晒"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的腐殖质土"},{"label":"繁殖","value":"以播种为主"},{"label":"主要用途","value":"年宵花、冬春盆栽、花坛布置"}],"facts":["瓜叶菊的叶片大而心形，形似瓜叶，因此得名。","它的头状花序密集排列成伞房状，一盆可开数十朵花。","瓜叶菊喜凉爽怕高温，夏季高温时容易枯萎，需要遮阴降温。","它是冬春年宵花市的常见盆花，花色从蓝紫到纯白都有。"]},"flower-snow-lotus":{"description":"雪莲为菊科风毛菊属多年生草本，株高 15–35 厘米，根粗壮，茎短而密被白色长毛。叶片密集基生，长椭圆形，边缘有锯齿，两面被白色绒毛。头状花序密集成球，被多层膜质、半透明的苞片包裹，苞片淡黄绿色，花期 7–8 月；果实为瘦果。\n\n雪莲原产中国新疆天山、昆仑山及青藏高原的高山地带，生于海拔 2400–4000 米以上的高山流石滩和雪线附近，耐寒、耐旱、抗风，生长期很短。它的膜质苞片像温室一样包裹花序，能保温保湿，帮助花朵在严酷环境中开放。雪莲是著名的高山药用植物，因过度采挖和生境脆弱，野生资源稀少，已被列入国家重点保护野生植物名录，禁止随意采挖。","habitat":"天山、昆仑山等高山的流石滩与雪线附近，耐寒、耐旱、抗风","distribution":"原产中国新疆天山、昆仑山及青藏高原高山地带，中亚山地也有分布","conservation":"暂无评估；中国国家二级重点保护野生植物","details":[{"label":"株高","value":"15–35 厘米，全株被白色长毛"},{"label":"花期","value":"7–8 月，头状花序被膜质苞片包裹"},{"label":"果期","value":"花后结瘦果"},{"label":"光照","value":"喜强光，生于高海拔开阔地"},{"label":"水分","value":"耐旱，忌积水"},{"label":"土壤","value":"高山流石滩的碎石与贫瘠土壤"},{"label":"繁殖","value":"以播种繁殖为主"},{"label":"主要用途","value":"高山药用植物、科研与保护对象"}],"facts":["雪莲的膜质苞片像小温室一样包裹花序，能保温保湿。","它生于海拔 2400–4000 米以上的高山流石滩，生长期很短。","雪莲因过度采挖和生境脆弱，已被列入国家重点保护野生植物名录。","雪莲全株密被白色长毛，可抵御高山强风和强紫外线。"]},"flower-french-marigold":{"description":"孔雀草为菊科万寿菊属一年生草本，株高 20–40 厘米，茎多分枝。叶片羽状全裂，裂片披针形，边缘有锯齿，揉碎后有特殊气味。头状花序单生，直径 3–5 厘米，舌状花红褐色、橙黄色或双色，中央管状花黄色，花期 6–10 月；果实为瘦果。\n\n孔雀草原产墨西哥，喜阳光充足、温暖干燥的环境，不耐寒、怕积水，适应性强，能自播繁衍。它与万寿菊是近亲，但株型更小、花色更丰富，红黄相间的舌状花在花坛中十分醒目。根系分泌物能抑制根结线虫，常被种在蔬菜田间作伴生植物；花瓣也含叶黄素，可作天然色素原料；在南方温暖地区，花期可一直延续到初冬。","habitat":"墨西哥的向阳草原与山坡，喜温暖、阳光充足","distribution":"原产墨西哥，世界温暖地区广泛栽培，中国各地花坛常见","conservation":"暂无评估","details":[{"label":"株高","value":"20–40 厘米，茎多分枝"},{"label":"花期","value":"6–10 月，单株花期长"},{"label":"果期","value":"8–11 月，瘦果线形"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"耐旱，忌积水"},{"label":"土壤","value":"疏松、排水良好的壤土"},{"label":"主要用途","value":"花坛观赏、驱线虫伴生、提取色素"}],"facts":["孔雀草与万寿菊是近亲，但株型更小、舌状花常呈红黄双色。","它的根系分泌物能抑制根结线虫，常与蔬菜间作。","揉碎叶片有特殊气味，有人形容为“臭菊花”。","孔雀草能自播繁衍，种子落地后翌年常自行萌发。"]},"flower-stock":{"description":"紫罗兰为十字花科紫罗兰属二年生至多年生草本，株高 30–60 厘米，茎直立，全株被灰白色柔毛。叶片长椭圆形至披针形，灰绿色。总状花序顶生，花有紫红、粉、白、淡黄等色，单瓣或重瓣，具浓郁香气，花期 3–5 月；果实为长角果。\n\n紫罗兰原产地中海沿岸，喜凉爽、阳光充足和排水良好的环境，耐寒不耐酷热，秋播后翌年春天开花。它花序挺直、花色柔和、香气清雅，是花束、花坛和盆栽的常见材料，重瓣品种尤其受欢迎。注意与苦苣苔科的非洲堇区分，二者亲缘关系很远；紫罗兰的花可作食用装饰，但需确认未施农药；重瓣品种在花市上尤其受欢迎，适合做胸花。","habitat":"地中海沿岸的岩石坡地与干燥草地，喜凉爽、阳光充足","distribution":"原产地中海沿岸，现世界各地栽培，中国各地花坛与花市常见","conservation":"暂无评估","details":[{"label":"株高","value":"30–60 厘米，全株被柔毛"},{"label":"花期","value":"3–5 月，香气浓郁"},{"label":"果期","value":"花后结长角果"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松、排水良好的石灰质壤土"},{"label":"主要用途","value":"花束、花坛、盆栽"}],"facts":["紫罗兰的穗状花序香气浓郁，是欧洲传统花束的常用花材。","它与苦苣苔科的非洲堇并非近亲，只是名称相近。","紫罗兰秋播后需经过冬季低温，翌年春天才能整齐开花。","重瓣紫罗兰的种子多来自单瓣植株，育苗时需挑选。"]},"flower-ornamental-kale":{"description":"羽衣甘蓝为十字花科芸薹属二年生草本，株高 30–60 厘米，茎短缩。叶片宽大，倒卵形，边缘有波状皱褶，内叶呈白、黄、粉、紫等色，外叶蓝绿色，整体形似盛开的牡丹。总状花序在翌年春季抽出，花黄色，花期 3–4 月；果实为长角果。\n\n羽衣甘蓝是甘蓝的园艺变种，原产地中海沿岸，喜凉爽、阳光充足和排水良好的环境，耐寒力强，可耐 -10℃ 左右低温，霜冻后叶色反而更鲜艳。秋冬季节它叶色斑斓，是花坛、花境和盆栽的观叶主角；嫩叶富含维生素和膳食纤维，也可炒食或做沙拉，但观赏品种口感较硬，以观赏为主；冬季低温时叶色最为浓艳，观赏期可延续到早春。","habitat":"地中海沿岸的石灰质坡地，喜凉爽、阳光充足","distribution":"原产地中海沿岸，现世界各地栽培，中国各地秋冬花坛常见","conservation":"暂无评估","details":[{"label":"株高","value":"30–60 厘米，叶展可达 40 厘米"},{"label":"花期","value":"翌年 3–4 月抽薹开花"},{"label":"果期","value":"花后结长角果"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的壤土"},{"label":"主要用途","value":"秋冬花坛观叶、盆栽、嫩叶食用"}],"facts":["羽衣甘蓝内叶的白、粉、紫等色彩，是秋冬花坛的重要配色来源。","它耐寒力强，经霜冻后叶色反而更加鲜艳。","羽衣甘蓝是甘蓝的园艺变种，与卷心菜、西兰花是近亲。","观赏品种的嫩叶可食，但口感较硬，一般以观赏为主。"]},"flower-horned-violet":{"description":"角堇为堇菜科堇菜属多年生草本，常作一二年生栽培，株高 10–20 厘米，茎匍匐或丛生。叶片卵形至心形，边缘有圆齿。花单生，直径 2–3 厘米，有紫、蓝、黄、白及复色，花瓣上有斑纹，花期 11 月至翌年 5 月；果实为蒴果。\n\n角堇原产西班牙和法国南部的比利牛斯山区，喜凉爽、阳光充足和湿润的环境，耐寒不耐酷热，是冬春季节花坛和吊篮的重要材料。它比三色堇植株更小、花朵更密，开花量极大，常成片种植形成花毯；花色丰富，还有香味品种。栽培以秋播为主，花后修剪可促进再次开花；在长江流域可露地越冬，北方则需移入室内或覆盖保护过冬。","habitat":"西班牙与法国南部的山地草甸，喜凉爽、湿润","distribution":"原产西班牙、法国南部，现世界各地栽培，中国各地冬春花坛常见","conservation":"暂无评估","details":[{"label":"株高","value":"10–20 厘米，茎匍匐或丛生"},{"label":"花期","value":"11 月至翌年 5 月"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜充足阳光，也耐半阴"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的壤土"},{"label":"主要用途","value":"冬春花坛、吊篮、盆栽"}],"facts":["角堇比三色堇植株更小、花朵更密，开花量极大。","它耐寒性强，是冬春季节花坛的重要色彩来源。","角堇原产比利牛斯山区，喜凉爽而不耐酷热。","部分角堇品种带有香味，可用于香花布置。"]},"flower-drummond-phlox":{"description":"福禄考为花荵科福禄考属一年生草本，株高 20–45 厘米，茎直立或匍匐，全株被短毛。叶片卵形至披针形，互生。聚伞花序顶生，花冠高脚碟状，5 裂，有红、粉、紫、白等色，喉部常有深色斑纹，花期 5–8 月；果实为蒴果。\n\n福禄考原产美国得克萨斯州的草原，喜阳光充足、温暖干燥和排水良好的环境，不耐寒也不耐酷热，播种后约两个月即可开花。它株型低矮、花色明快，适合布置花坛、花境和岩石园，也可作盆栽和切花。园艺品种有矮生、大花、星花等类型，成片种植时如铺了一层彩色地毯；矮生品种适合花坛镶边，高生品种可剪下作切花，瓶插期约一周。","habitat":"美国得克萨斯的草原与沙地，喜温暖、阳光充足","distribution":"原产美国南部，现世界各地栽培，中国各地花坛常见","conservation":"暂无评估","details":[{"label":"株高","value":"20–45 厘米，茎直立或匍匐"},{"label":"花期","value":"5–8 月"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松、排水良好的沙壤土"},{"label":"主要用途","value":"花坛、花境、盆栽、切花"}],"facts":["福禄考的花冠喉部常有深色斑纹，是识别品种的重要特征。","它原产美国得克萨斯，播种后约两个月即可开花。","园艺品种有矮生、大花、星花等类型，花色十分丰富。","福禄考成片种植时如铺了一层彩色地毯，是花坛的常用材料。"]},"flower-love-in-a-mist":{"description":"黑种草为毛茛科黑种草属一年生草本，株高 30–60 厘米，茎直立，多分枝。叶片二至三回羽状深裂，裂片细丝状。花单生茎顶，花被片 5 枚，蓝紫、粉或白色，外围有细裂的苞片环绕，花期 5–7 月；果实为膨大的球形蒴果，成熟后开裂。\n\n黑种草原产地中海沿岸，喜阳光充足、凉爽干燥和排水良好的环境，不耐酷热和积水，常自播繁衍。它细裂的苞片像一层羽纱，把花朵半掩其中，因此英文名意为“雾中情人”；花谢后膨大的球形蒴果也颇具观赏性，常用于干花制作。栽培以播种为主，成片种植可营造轻盈梦幻的花境效果；干燥后的花萼和蒴果是花艺中常见的装饰材料。","habitat":"地中海沿岸的干燥坡地与田边，喜凉爽、阳光充足","distribution":"原产地中海沿岸，现世界各地栽培，中国各地庭园常见","conservation":"暂无评估","details":[{"label":"株高","value":"30–60 厘米，茎多分枝"},{"label":"花期","value":"5–7 月"},{"label":"果期","value":"花后结球形蒴果"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"耐旱，忌积水"},{"label":"土壤","value":"疏松、排水良好的壤土"},{"label":"主要用途","value":"花境、切花、干花制作"}],"facts":["黑种草细裂的苞片像羽纱环绕花朵，英文名意为“雾中情人”。","花谢后膨大的球形蒴果也很有观赏性，可制作干花。","它原产地中海沿岸，耐旱不耐酷热，常自播繁衍。","蓝紫色花朵在细裂苞片中若隐若现，是花境的特色材料。"]},"flower-sulfur-cosmos":{"description":"硫华菊为菊科秋英属一年生草本，株高 60–150 厘米，茎直立，多分枝。叶片二回羽状深裂，裂片较宽。头状花序单生或数个聚生，直径 3–6 厘米，舌状花橙黄、金黄或橙红色，先端有齿，花期 6–10 月；果实为瘦果，细长。\n\n硫华菊原产墨西哥，喜阳光充足、温暖干燥的环境，耐旱耐瘠薄，适应性强，种子落地后能自播繁衍。它株型高大、花色浓烈，是花海景观、路旁绿化和庭院花境的常用植物，与波斯菊搭配可形成橙黄与粉白的层次；但植株过高时遇风易倒伏，栽培中常通过摘心控制高度；在南方，它常与波斯菊一起构成秋季花海的橙黄色底色，观赏期可达两个月。","habitat":"墨西哥的向阳草原与山坡，喜温暖、阳光充足","distribution":"原产墨西哥，现世界各地栽培或归化，中国各地常见","conservation":"暂无评估","details":[{"label":"株高","value":"60–150 厘米，茎多分枝"},{"label":"花期","value":"6–10 月"},{"label":"果期","value":"8–11 月，瘦果细长"},{"label":"光照","value":"极喜光"},{"label":"水分","value":"耐旱，忌积水"},{"label":"土壤","value":"疏松、排水良好的沙壤土，耐瘠薄"},{"label":"主要用途","value":"花海景观、路旁绿化、切花"}],"facts":["硫华菊舌状花先端有齿，橙黄色调与波斯菊的粉白形成鲜明对比。","它株型高大、自播力强，种子落地后翌年常成片萌发。","硫华菊耐旱耐瘠薄，适应性强，是花海景观的常用材料。","植株过高时遇风容易倒伏，栽培中常通过摘心控制高度。"]},"flower-large-larkspur":{"description":"翠雀为毛茛科翠雀属多年生草本，株高 40–80 厘米，茎直立，多分枝，全株被短柔毛。叶片掌状深裂，裂片线形。总状花序顶生，花两侧对称，萼片呈花瓣状，蓝色或蓝紫色，后方有细长的距，花期 6–8 月；果实为蓇葖果。\n\n翠雀原产中国北方、蒙古和西伯利亚的草原与山地，喜凉爽、阳光充足和排水良好的环境，耐寒不耐酷热。它花形别致、蓝紫色调清新，是花境中优良的竖线条材料；全株含二萜类生物碱，有毒，误食会引起中毒，栽培时应远离儿童与宠物。翠雀与飞燕草同科不同属，二者花形相似，但翠雀多为多年生；花后及时剪除残花，可促进侧枝再次抽出花穗。","habitat":"中国北方与西伯利亚的草原、山地草甸，喜凉爽、阳光充足","distribution":"原产中国北方、蒙古与西伯利亚，中国北方山地有分布","conservation":"暂无评估","details":[{"label":"株高","value":"40–80 厘米，茎直立多分枝"},{"label":"花期","value":"6–8 月"},{"label":"果期","value":"花后结蓇葖果"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松、排水良好的壤土"},{"label":"主要用途","value":"花境、切花、庭院点缀"}],"facts":["翠雀花后方的细长距是容纳花蜜的结构，与飞燕草相似。","它多为多年生，而飞燕草多为一年生，二者同科不同属。","翠雀全株含生物碱，有毒，栽培时应远离儿童与宠物。","蓝紫色花序高挺，是花境中的竖线条材料。"]},"flower-high-mallow":{"description":"锦葵为锦葵科锦葵属二年生或多年生草本，株高 60–120 厘米，茎直立，多分枝，全株被星状毛。叶片圆心形，边缘有浅裂和锯齿，叶柄长。花簇生于叶腋，花瓣 5 枚，紫红色至淡紫色，具深紫色脉纹，花期 5–9 月；果实为扁圆形的分果，成熟后裂成多个小坚果。\n\n锦葵原产欧洲、北非和西亚，中国各地路旁、荒地和庭院常见，喜阳光充足、凉爽的环境，耐寒耐旱，对土壤要求不严，常自播繁衍。它花朵虽小，但花期长、花色柔美，带有一种野趣，适合布置花境、庭院和路边；嫩叶和花可作蔬菜食用，全草也可入药，有清热利湿之效。锦葵与同科的蜀葵是近亲，两者花形相似，但蜀葵花序更高大。","habitat":"欧洲至西亚的草地、路旁与荒地，喜光、耐旱、耐寒","distribution":"原产欧洲、北非与西亚，中国各地路旁庭院常见","conservation":"暂无评估","details":[{"label":"株高","value":"60–120 厘米，茎直立多分枝"},{"label":"花期","value":"5–9 月，花果期长"},{"label":"果期","value":"花后结分果，裂成小坚果"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"耐旱，忌积水"},{"label":"土壤","value":"疏松、排水良好的壤土，耐瘠薄"},{"label":"主要用途","value":"花境与庭院观赏、嫩叶食用、全草入药"}],"facts":["锦葵的花瓣上有深紫色脉纹，是它最明显的识别特征。","它与同科的蜀葵是近亲，两者花形相似，但蜀葵花序更高大。","锦葵的嫩叶和花可作蔬菜食用，全草也可入药。","锦葵常自播繁衍，在路旁和荒地能形成野生群落。"]},"flower-rain-lily":{"description":"韭兰为石蒜科葱莲属多年生球根草本，株高 15–30 厘米，地下具卵形鳞茎。叶片线形，扁平，深绿色，丛生，形似韭菜。花单生花葶顶端，花被片 6 枚，粉红色至玫红色，直径 5–8 厘米，花期 5–9 月；果实为蒴果。\n\n韭兰原产中美洲一带，喜温暖、阳光充足和湿润的环境，耐半阴，在南方可露地越冬。它常在雨后集中开放，因此有“雨百合”之称；花朵粉红娇艳、叶片葱绿，成片种植时如铺了一层粉绿相间的地毯，是花坛镶边、林下地被和庭院点缀的常用材料。韭兰以分球繁殖为主，鳞茎繁殖快，栽培管理粗放，但忌长期积水，是南方庭院常见的低维护地被植物。","habitat":"中美洲的草原与河岸，喜温暖、阳光充足","distribution":"原产中美洲，中国南方广泛栽培，长江流域可露地越冬","conservation":"暂无评估","details":[{"label":"株高","value":"15–30 厘米，叶线形丛生"},{"label":"花期","value":"5–9 月，雨后集中开放"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜充足阳光，也耐半阴"},{"label":"水分","value":"喜湿润，忌长期积水"},{"label":"土壤","value":"疏松肥沃、排水良好的壤土"},{"label":"繁殖","value":"以分球繁殖为主"},{"label":"主要用途","value":"花坛镶边、林下地被、盆栽"}],"facts":["韭兰叶片扁平似韭菜，花朵粉红，因此得名。","它常在雨后集中开放，英文名意为“雨百合”。","韭兰靠小鳞茎分球繁殖，繁殖速度快。","它忌长期积水，否则鳞茎容易腐烂。"]},"flower-red-spider-lily":{"description":"石蒜为石蒜科石蒜属多年生球根草本，地下具球形鳞茎。叶片带状，深绿色，在花期结束后才抽出，翌年夏季枯萎。花葶在秋季抽出，高 30–60 厘米，伞形花序有花 4–7 朵，花鲜红色，花被片 6 枚、强烈向后反卷，边缘皱曲，雄蕊细长伸出，花期 8–9 月；果实为蒴果。\n\n石蒜原产中国长江流域及日本，常生于阴湿的林下、溪边和石缝，喜半阴、湿润和排水良好的环境。它秋天开花时叶片尚未生出，花谢后才长叶，叶枯时花又未开，因此有“花叶永不相见”之说，民间也常把它与离别、思念联系在一起。石蒜鳞茎含石蒜碱等多种生物碱，有毒，不可食用；因花形奇特、色彩醒目，常用于林下布置和切花，但需注意避免误食。","habitat":"林下、溪边与石缝等阴湿处，喜半阴、湿润","distribution":"原产中国长江流域及日本，中国南方林下常见","conservation":"暂无评估","details":[{"label":"株高","value":"花葶高 30–60 厘米"},{"label":"花期","value":"8–9 月，花期约两周"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜半阴，忌强光直射"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松、排水良好的腐殖质土"},{"label":"繁殖","value":"分球繁殖"},{"label":"主要用途","value":"林下观赏、切花（有毒）"}],"facts":["石蒜花叶永不相见：开花时无叶，长叶时无花。","鲜红色花被片向后强烈反卷、边缘皱曲，形似龙爪，故有“龙爪花”之称。","石蒜鳞茎含石蒜碱等生物碱，有毒，不可食用。","它常生于阴湿林下，在秋季抽出花葶，花期约两周。"]},"flower-golden-spider-lily":{"description":"忽地笑为石蒜科石蒜属多年生球根草本，地下具鳞茎。叶片带状，深绿色，花后才抽出。花葶秋季抽出，高 40–70 厘米，伞形花序有花 4–8 朵，花金黄色，花被片 6 枚、向后反卷，边缘皱曲，雄蕊细长伸出，花期 8–10 月；果实为蒴果。\n\n忽地笑原产中国长江流域及以南地区，常生于阴湿林下、溪边和岩石缝隙，喜半阴、湿润和排水良好的环境，耐寒性一般。它秋天开花时叶片尚未抽出，花谢后才长叶，与石蒜一样“花叶不相见”；金黄色的花朵在秋日林下格外醒目，因此得名“忽地笑”。鳞茎含石蒜碱，有毒，不可食用，栽培和观赏时应避免误食，可用于林下和庭院点缀。","habitat":"林下、溪边与岩石缝隙等阴湿处，喜半阴、湿润","distribution":"原产中国长江流域及以南地区，日本也有分布","conservation":"暂无评估","details":[{"label":"株高","value":"花葶高 40–70 厘米"},{"label":"花期","value":"8–10 月"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜半阴，忌强光直射"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松、排水良好的腐殖质土"},{"label":"繁殖","value":"分球繁殖"},{"label":"主要用途","value":"林下观赏、庭院点缀（有毒）"}],"facts":["忽地笑与石蒜同属，花形相似，但花色为金黄色。","它也是“花叶不相见”：秋季开花时叶片尚未抽出。","鳞茎含石蒜碱，有毒，不可食用，栽培时需注意。","金黄色花序在秋日林下十分醒目，因此得名“忽地笑”。"]},"flower-persian-buttercup":{"description":"花毛茛为毛茛科毛茛属多年生草本，株高 20–50 厘米，地下具纺锤状块根。叶片羽状分裂，裂片有齿。花单生或数朵聚生，花径 5–10 厘米，有红、粉、黄、白、橙等色，重瓣品种花瓣层层叠叠，形似小牡丹，花期 3–5 月；果实为瘦果。\n\n花毛茛原产地中海沿岸和西亚，喜凉爽、阳光充足和排水良好的环境，夏季高温时块根休眠，秋凉后重新萌芽。它花形饱满、色彩丰富，重瓣品种形似牡丹，因此有“洋牡丹”之称，是春季花坛和切花的重要材料。栽培以块根种植为主，需用疏松透气的土壤，忌积水；块根在夏季休眠期应挖出放在阴凉处贮藏，秋季再种；花后剪去残花可减少养分消耗。","habitat":"地中海沿岸与西亚的向阳坡地，喜凉爽、阳光充足","distribution":"原产地中海沿岸与西亚，现世界各地栽培，中国云南等地种植较多","conservation":"暂无评估","details":[{"label":"株高","value":"20–50 厘米，具纺锤状块根"},{"label":"花期","value":"3–5 月"},{"label":"果期","value":"花后结瘦果"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松透气、排水良好的壤土"},{"label":"繁殖","value":"块根分株、播种"},{"label":"主要用途","value":"花坛、切花、盆栽"}],"facts":["花毛茛重瓣品种的花瓣层层叠叠，形似小牡丹，因此有“洋牡丹”之称。","它夏季高温时块根休眠，秋凉后才重新萌芽。","花毛茛原产地中海和西亚，喜凉爽而不耐酷热。","栽培时土壤需疏松透气，积水容易导致块根腐烂。"]},"flower-poppy-anemone":{"description":"银莲花为毛茛科银莲花属多年生草本，株高 20–40 厘米，地下具块茎。叶片羽状分裂，裂片细裂。花单生花葶顶端，花径 5–8 厘米，萼片呈花瓣状，有红、蓝、紫、粉、白等色，中央密生黑紫色雄蕊，花期 3–5 月；果实为瘦果。\n\n银莲花原产地中海沿岸，喜凉爽、阳光充足和排水良好的环境，夏季块茎休眠，秋凉后萌芽，翌年春季开花。它花形舒展、色彩浓烈，中心黑紫色的雄蕊群与鲜艳的萼片形成强烈对比，是春季花坛和切花的特色材料。栽培以块茎种植为主，土壤需疏松透气，生长期保持湿润但不积水；与毛茛科许多植物一样，全株有一定毒性，不可食用。","habitat":"地中海沿岸的向阳坡地，喜凉爽、阳光充足","distribution":"原产地中海沿岸，现世界各地栽培，中国各地花市常见","conservation":"暂无评估","details":[{"label":"株高","value":"20–40 厘米，地下具块茎"},{"label":"花期","value":"3–5 月"},{"label":"果期","value":"花后结瘦果"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松透气、排水良好的壤土"},{"label":"繁殖","value":"以块茎种植为主"},{"label":"主要用途","value":"花坛、切花、盆栽"}],"facts":["银莲花的花瓣其实是萼片，中央密生黑紫色雄蕊。","它原产地中海沿岸，喜凉爽，夏季块茎休眠。","银莲花与花毛茛同为毛茛科，全株有毒性，不可食用。","花色浓烈、花形舒展，是春季切花的特色材料。"]},"flower-bleeding-heart":{"description":"荷包牡丹为罂粟科荷包牡丹属多年生草本，株高 40–80 厘米，茎直立，带肉质。叶片二回三出羽状分裂，形似牡丹叶。总状花序弯垂，花两侧对称，外侧两枚花瓣粉红色，基部膨大呈心形或荷包状，内侧花瓣白色，花期 4–6 月；果实为蒴果。\n\n荷包牡丹原产中国北方、朝鲜半岛和日本，常生于林下、溪边等阴湿处，喜半阴、湿润和排水良好的环境，耐寒性较强。它花朵成串垂挂，形似一个个小荷包，因此得名；花期恰逢牡丹盛开，叶形也似牡丹，故又称“荷包牡丹”。荷包牡丹是春季林下和花境的优良材料，也适合盆栽；全株含生物碱，有一定毒性，不可食用，也不宜自行入药。","habitat":"林下、溪边与阴湿山谷，喜半阴、湿润、凉爽","distribution":"原产中国北方、朝鲜半岛与日本，中国北方山地有分布","conservation":"暂无评估","details":[{"label":"株高","value":"40–80 厘米，茎直立带肉质"},{"label":"花期","value":"4–6 月，花序弯垂"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜半阴，忌强光暴晒"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、富含腐殖质的壤土"},{"label":"繁殖","value":"分株、播种"},{"label":"主要用途","value":"林下花境、庭院点缀、盆栽"}],"facts":["荷包牡丹的花朵呈心形，成串垂挂，形似一个个小荷包。","它花期恰逢牡丹盛开、叶形也似牡丹，因此得名。","荷包牡丹喜阴湿，是林下花境的优良材料。","全株含生物碱，有一定毒性，不可食用。"]},"flower-lupine":{"description":"羽扇豆为豆科羽扇豆属多年生草本，株高 80–150 厘米，茎直立，全株被短毛。掌状复叶由 7–15 枚小叶组成，形似张开的羽扇。总状花序顶生，长 30–60 厘米，由数十至上百朵蝶形小花从下往上排列，有蓝紫、粉、红、黄、白等色，花期 5–7 月；果实为荚果。\n\n羽扇豆原产北美洲西部，喜凉爽、阳光充足和排水良好的环境，耐寒不耐酷热，适合在疏松的微酸性土壤中栽培。它花序高挺、花朵密集，是花境中优良的竖线条材料，成片种植时如一座座彩色宝塔；园艺品种还有矮生类型，可作盆栽。羽扇豆的根系能固氮，可改善土壤；种子和植株含生物碱，有毒，不可食用。","habitat":"北美西部的山地草甸与林缘，喜凉爽、阳光充足","distribution":"原产北美洲西部，现世界各地栽培，中国各地花境常见","conservation":"暂无评估","details":[{"label":"株高","value":"80–150 厘米，茎直立"},{"label":"花期","value":"5–7 月，花序长 30–60 厘米"},{"label":"果期","value":"花后结荚果"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松、排水良好的微酸性土壤"},{"label":"繁殖","value":"以播种为主"},{"label":"主要用途","value":"花境、切花、固氮改良土壤"}],"facts":["羽扇豆的掌状复叶形似张开的羽扇，因此得名。","塔状花序由上百朵小花从下往上排列，是花境的竖线条材料。","它的根系能固氮，可改善土壤肥力。","种子和植株含生物碱，有毒，不可食用。"]},"flower-boat-orchid":{"description":"大花蕙兰为兰科兰属多年生附生或半附生草本，是园艺杂交品种群，假鳞茎粗大，叶片带状、革质，长 50–100 厘米。花葶自假鳞茎抽出，长 40–80 厘米，着花 10–20 朵，花大，直径 6–10 厘米，有红、粉、黄、绿、白及复色，花期 12 月至翌年 4 月。\n\n大花蕙兰由兰属多个原生种杂交选育而成，亲本多原产中国西南、东南亚的高海拔地区，喜温暖湿润、半阴通风和昼夜温差较大的环境，忌强光暴晒和积水。它株型高大、花序丰满，单枝花期可长达两三个月，是春节年宵花市的主力花卉；栽培常用树皮、水苔等透气基质，花后可剪去花葶、保留叶片养球，来年再开花。","habitat":"杂交种，喜温暖湿润、半阴通风、昼夜温差大","distribution":"园艺杂交品种，中国云南、广东等地规模化生产，世界各地盆栽","conservation":"暂无评估（园艺杂交品种）","details":[{"label":"株高","value":"花葶长 40–80 厘米，着花 10–20 朵"},{"label":"花期","value":"12 月至翌年 4 月"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜半阴散射光，忌强光暴晒"},{"label":"水分","value":"喜湿润，空气湿度 60%–80%"},{"label":"土壤","value":"以树皮、水苔等透气基质栽培"},{"label":"主要用途","value":"年宵花、切花、盆栽"}],"facts":["大花蕙兰是兰属多个原生种杂交选育的品种群，不是自然物种。","单枝花序可开两三个月，是春节年宵花市的主力之一。","亲本多来自中国西南和东南亚的高海拔地区，喜昼夜温差大的环境。","花后剪去花葶、保留叶片养球，是来年再次开花的关键。"]},"flower-ensifolium-orchid":{"description":"建兰为兰科兰属多年生地生草本，假鳞茎卵球形，叶片 2–6 枚丛生，带状，长 30–60 厘米，绿色有光泽。花葶直立，着花 3–9 朵，花黄绿色至浅黄褐色，唇瓣有紫红色斑纹，香气清远，花期 6–10 月，有的植株一年可开两次；果实为蒴果。\n\n建兰原产中国南方、日本和东南亚，常生于疏林下、溪谷旁的腐殖质坡地，喜半阴、湿润和通风良好的环境。它是中国传统国兰的重要种类，与春兰、蕙兰、墨兰并称“四大家”，叶片飘逸、花香清远，南宋以来深受文人喜爱。野生兰属植物已列入国家重点保护野生植物名录，市售建兰多为人工繁殖；栽培以疏松透气的植料为主，忌积水和强光暴晒。","habitat":"疏林下、溪谷旁的腐殖质坡地，喜半阴、湿润、通风","distribution":"原产中国南方、日本与东南亚，中国华南、西南山地有分布","conservation":"暂无评估；兰属野生种列入中国国家二级重点保护野生植物","details":[{"label":"株高","value":"叶长 30–60 厘米，花葶高 20–40 厘米"},{"label":"花期","value":"6–10 月，部分植株一年两开"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜半阴散射光"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松透气、富含腐殖质的植料"},{"label":"繁殖","value":"以分株为主"},{"label":"主要用途","value":"国兰观赏、盆栽"}],"facts":["建兰是中国传统国兰“四大家”之一，夏秋开花、香气清远。","部分建兰植株一年能开两次花，因此有“四季兰”之称。","野生兰属植物受国家保护，市售多为人工繁殖个体。","建兰叶片飘逸有光泽，是文人案头清供的常见兰花。"]},"flower-chinese-cymbidium":{"description":"墨兰为兰科兰属多年生地生草本，假鳞茎椭圆形，叶片 3–5 枚丛生，带状，长 50–80 厘米，深绿色、有光泽。花葶直立，高出叶面，着花 5–15 朵，花紫褐色至深紫红色，唇瓣有斑纹，香气浓郁，花期 1–3 月；果实为蒴果。\n\n墨兰原产中国南方、日本和东南亚，常生于疏林下、溪谷旁的阴湿坡地，喜温暖、半阴、湿润和通风的环境，耐寒性较弱。它是中国传统国兰“四大家”之一，叶色深绿、花色紫褐，在国兰中颜色最深，因此得名；冬春开花、香气浓郁，常作为年宵花摆放。野生兰属植物受国家保护，市售墨兰多为人工繁殖；栽培以透气植料为主，冬季需防寒。","habitat":"疏林下、溪谷旁的阴湿坡地，喜温暖、半阴、湿润","distribution":"原产中国南方、日本与东南亚，中国华南、西南山地有分布","conservation":"暂无评估；兰属野生种列入中国国家二级重点保护野生植物","details":[{"label":"株高","value":"叶长 50–80 厘米，花葶高出叶面"},{"label":"花期","value":"1–3 月，香气浓郁"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜半阴散射光"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松透气、富含腐殖质的植料"},{"label":"繁殖","value":"以分株为主"},{"label":"主要用途","value":"年宵花、国兰观赏、盆栽"}],"facts":["墨兰是传统国兰“四大家”之一，花色紫褐，在国兰中颜色最深。","它冬春开花、香气浓郁，常被用作年宵花。","墨兰耐寒性较弱，冬季需放在温暖避风处。","野生兰属植物受国家保护，市售墨兰多为人工繁殖。"]},"flower-faber-cymbidium":{"description":"蕙兰为兰科兰属多年生地生草本，假鳞茎不明显，叶片 5–8 枚丛生，带状，长 40–80 厘米，边缘有细锯齿。花葶直立，着花 5–15 朵，花浅黄绿色至黄绿色，唇瓣有紫红色斑点，香气清冽，花期 3–5 月；果实为蒴果。\n\n蕙兰原产中国中部、西南及秦岭以南的山区，常生于疏林下、溪谷旁的腐殖质坡地，喜凉爽、半阴、湿润和通风良好的环境，耐寒性较强。它是中国传统国兰“四大家”之一，一葶多花、花香清冽，古人常把它与春兰并称；野生蕙兰已列入国家重点保护野生植物名录，采挖和买卖野生兰需遵守法规。栽培以透气植料为主，忌积水和强光。","habitat":"疏林下、溪谷旁的腐殖质坡地，喜凉爽、半阴、湿润","distribution":"原产中国中部与西南山区，秦岭以南多地有分布","conservation":"暂无评估；兰属野生种列入中国国家二级重点保护野生植物","details":[{"label":"株高","value":"叶长 40–80 厘米，花葶着花 5–15 朵"},{"label":"花期","value":"3–5 月"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜半阴散射光"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松透气、富含腐殖质的植料"},{"label":"繁殖","value":"以分株为主"},{"label":"主要用途","value":"国兰观赏、盆栽"}],"facts":["蕙兰一葶多花、花香清冽，是传统国兰“四大家”之一。","它耐寒性较强，多生于秦岭以南的山区林下。","野生蕙兰受国家保护，采挖和买卖需遵守相关法规。","古人常把蕙兰与春兰并称，视其为兰花中的高品。"]},"flower-calla-lily":{"description":"马蹄莲为天南星科马蹄莲属多年生草本，株高 60–100 厘米，地下具粗壮根状茎。叶片箭形至心形，长 20–45 厘米，有长叶柄。花葶自叶丛抽出，佛焰苞白色、展开呈马蹄形，中央为黄色的肉穗花序，花期 3–6 月；果实为浆果。\n\n马蹄莲原产南非的沼泽和湿地，喜温暖、湿润和半阴的环境，耐寒性一般，冬季需保护越冬。它白色的佛焰苞形态优雅，是婚礼、花束和花艺中常见的切花，也可作盆栽观赏。需要注意的是，马蹄莲全株含草酸钙结晶，有毒，误食会引起口腔和消化道刺痛、肿胀，修剪或插花时应戴手套，并避免儿童和宠物接触。","habitat":"南非的沼泽、湿地与河岸，喜温暖、湿润、半阴","distribution":"原产南非，现世界各地栽培，中国南方可露地种植","conservation":"暂无评估","details":[{"label":"株高","value":"60–100 厘米，具粗壮根状茎"},{"label":"花期","value":"3–6 月"},{"label":"果期","value":"花后结浆果"},{"label":"光照","value":"喜半阴散射光"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"肥沃、富含腐殖质的壤土"},{"label":"繁殖","value":"分株、块茎繁殖"},{"label":"主要用途","value":"切花、婚礼花艺、盆栽（有毒）"}],"facts":["马蹄莲的“花”其实是白色佛焰苞，真正的花是中央的肉穗花序。","它是婚礼和花束中常用的切花，象征纯洁与优雅。","全株含草酸钙结晶，有毒，误食会引起口腔刺痛。","马蹄莲原产南非湿地，喜湿润，盆栽时不能缺水。"]},"flower-african-violet":{"description":"非洲堇为苦苣苔科非洲堇属多年生草本，株高 10–15 厘米，叶片肉质，卵形至圆形，表面密被短毛，呈莲座状排列。花葶自叶腋抽出，聚伞花序有花数朵，花冠 5 裂，有紫、蓝、粉、白及复色，花期可全年，以春秋最盛；果实为蒴果。\n\n非洲堇原产东非坦桑尼亚的山区，生于阴湿的岩石和树干旁，喜温暖、湿润和明亮的散射光，忌强光暴晒和积水，是典型的室内花卉。它株型小巧、花期长，适合放在窗台、书桌和案头；叶插繁殖极容易，把叶片带叶柄插入微潮的基质即可长出新苗。浇水时避免淋湿叶片，否则容易引发叶斑病。","habitat":"东非山区的阴湿岩缝与林下，喜温暖、湿润、散射光","distribution":"原产东非坦桑尼亚，现世界各地广泛盆栽，中国各地花市常见","conservation":"暂无评估","details":[{"label":"株高","value":"10–15 厘米，莲座状"},{"label":"花期","value":"可全年开花，春秋最盛"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜明亮散射光，忌强光"},{"label":"水分","value":"喜湿润，忌淋湿叶片"},{"label":"土壤","value":"疏松透气、富含腐殖质的基质"},{"label":"繁殖","value":"叶插、分株"},{"label":"主要用途","value":"室内盆栽、窗台观赏"}],"facts":["非洲堇叶片表面密被短毛，浇水时淋到叶片容易引发叶斑病。","它株型小巧、花期长，是室内窗台最受欢迎的盆栽之一。","叶插繁殖极容易，把叶片带叶柄插入微潮基质即可长出新苗。","非洲堇原产东非山区，喜散射光，忌强光暴晒。"]},"flower-gloxinia":{"description":"大岩桐为苦苣苔科大岩桐属多年生球根草本，株高 15–30 厘米，地下具扁球形块茎。叶片大，卵形至长椭圆形，肉质，密被绒毛，深绿色。花单生或数朵聚生叶腋，花冠钟形，直径 5–8 厘米，有红、粉、紫、白及复色，花期 4–10 月；果实为蒴果。\n\n大岩桐原产巴西的阴湿山区，喜温暖、湿润和明亮的散射光，忌强光暴晒和积水。它叶片绒质、花朵钟形如丝绒，色彩浓艳，是室内盆栽和花坛的常见花卉；块茎可反复开花，花后剪去残花、保留叶片养球，来年可再度萌发。浇水时应沿盆边浇，避免淋湿叶片和块茎；叶插和块茎分株均可繁殖。","habitat":"巴西阴湿山区的林下与岩缝，喜温暖、湿润、散射光","distribution":"原产巴西，现世界各地广泛盆栽，中国各地花市常见","conservation":"暂无评估","details":[{"label":"株高","value":"15–30 厘米，具扁球形块茎"},{"label":"花期","value":"4–10 月"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜明亮散射光，忌强光暴晒"},{"label":"水分","value":"喜湿润，忌淋湿叶片"},{"label":"土壤","value":"疏松透气、富含腐殖质的基质"},{"label":"繁殖","value":"叶插、块茎分株"},{"label":"主要用途","value":"室内盆栽、花坛布置"}],"facts":["大岩桐叶片密被绒毛，花朵像丝绒，触感十分特别。","它地下有扁球形块茎，可反复萌发开花。","浇水时淋湿叶片和块茎容易腐烂，应沿盆边浇。","大岩桐原产巴西阴湿山区，喜散射光而怕暴晒。"]},"flower-fuchsia":{"description":"倒挂金钟为柳叶菜科倒挂金钟属常绿灌木，园艺品种多为杂交种，株高 30–100 厘米，枝细长下垂。叶片对生，卵形，边缘有锯齿。花单生叶腋，下垂，花萼管状、常呈红或紫红色，花瓣 4 枚、颜色与花萼不同，形似悬挂的小灯笼，花期 4–10 月；果实为浆果。\n\n倒挂金钟原产中南美洲的山地，园艺杂交品种亲本多来自墨西哥、秘鲁等地，喜凉爽、湿润、半阴和通风良好的环境，耐寒性较弱，夏季高温时生长停滞。它花形奇特、花色明快，成串下垂如小灯笼，是阳台、吊篮和庭院悬挂栽培的经典花卉。栽培以疏松透气的土壤为主，夏季需遮阴降温、控水，否则容易落叶甚至枯死。","habitat":"中南美洲山地林缘，喜凉爽、湿润、半阴、通风","distribution":"园艺杂交品种，原种产中南美洲，世界各地广泛盆栽","conservation":"暂无评估","details":[{"label":"株高","value":"30–100 厘米，枝细长下垂"},{"label":"花期","value":"4–10 月，单株花期长"},{"label":"果期","value":"花后结浆果"},{"label":"光照","value":"喜半阴散射光，忌强光"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松透气、富含腐殖质的壤土"},{"label":"繁殖","value":"扦插繁殖"},{"label":"主要用途","value":"阳台吊篮、庭院悬挂、盆栽"}],"facts":["倒挂金钟的花萼与花瓣颜色不同，整朵花下垂如小灯笼。","它原产中南美洲山地，怕热不怕冷凉，夏季高温时生长停滞。","倒挂金钟成串垂挂，是阳台和吊篮的经典花卉。","夏季需遮阴降温、控水，否则容易落叶枯死。"]},"flower-thyme":{"description":"百里香为唇形科百里香属半灌木，株高 10–25 厘米，茎匍匐或斜升，老枝木质化。叶片细小，卵形至椭圆形，对生，揉碎后散发浓郁香气。轮伞花序密集成头状，花小，淡紫色或粉白色，花期 6–8 月；果实为小坚果。\n\n百里香原产中国北方、蒙古及欧亚温带地区，喜阳光充足、凉爽干燥和排水良好的环境，耐旱耐瘠薄，忌积水和湿热。它茎叶含百里香酚等挥发性成分，是西餐和中餐常用的香草，可用于烤肉、炖汤和腌料，也可提取精油；植株低矮、蔓延性强，还是优良的地被和岩石园植物，开花时吸引蜜蜂。","habitat":"中国北方与蒙古的干旱草原、石质坡地，喜光、耐旱","distribution":"原产中国北方、蒙古及欧亚温带，中国华北、西北山地有分布","conservation":"暂无评估","details":[{"label":"株高","value":"10–25 厘米，茎匍匐或斜生"},{"label":"花期","value":"6–8 月，花小，淡紫色"},{"label":"果期","value":"花后结小坚果"},{"label":"光照","value":"极喜光"},{"label":"水分","value":"耐旱，忌积水"},{"label":"土壤","value":"排水良好的石灰质沙壤土"},{"label":"繁殖","value":"扦插、分株、播种"},{"label":"主要用途","value":"烹饪香草、提取精油、地被绿化"}],"facts":["百里香叶片细小、香气浓郁，是西餐烤肉和炖汤的常用香草。","它含百里香酚等挥发性成分，可提取精油。","百里香匍匐蔓延，是岩石园和地被绿化的好材料。","开花时花蜜丰富，能吸引蜜蜂等传粉昆虫。"]},"flower-oregano":{"description":"牛至为唇形科牛至属多年生草本，株高 30–60 厘米，茎直立或斜生，四棱形，多分枝。叶片卵形，对生，表面有腺点，揉碎后散发浓郁辛香。伞房状聚伞花序顶生，花小，粉紫色或白色，花期 6–9 月；果实为小坚果。\n\n牛至原产地中海沿岸和西亚，喜阳光充足、温暖干燥和排水良好的环境，耐旱耐寒，忌积水和湿热。它叶片含香芹酚、百里香酚等挥发性成分，是意大利披萨、番茄酱和烤肉中不可或缺的香草，干燥后香气更浓；全草也可入药，有解表化湿之效。栽培以疏松的石灰质土壤为主，生长期摘心可促进分枝。","habitat":"地中海沿岸的干燥草地与岩石坡地，喜光、耐旱","distribution":"原产地中海沿岸与西亚，中国各地有栽培，部分山区有归化","conservation":"暂无评估","details":[{"label":"株高","value":"30–60 厘米，茎四棱形"},{"label":"花期","value":"6–9 月，花小，粉紫色或白色"},{"label":"果期","value":"花后结小坚果"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"耐旱，忌积水"},{"label":"土壤","value":"疏松、排水良好的石灰质壤土"},{"label":"繁殖","value":"播种、分株、扦插"},{"label":"主要用途","value":"烹饪香草、全草入药"}],"facts":["牛至是意大利披萨和番茄酱中不可或缺的香草，干燥后香气更浓。","叶片表面有腺点，揉碎后会散发浓郁的辛香。","它含香芹酚等挥发性成分，全草也可入药。","牛至耐旱耐寒，但对积水十分敏感。"]},"flower-perilla":{"description":"紫苏为唇形科紫苏属一年生草本，株高 30–100 厘米，茎直立，四棱形，多分枝，全株有香气。叶片对生，卵形，边缘有锯齿，有绿色和紫红色两类。轮伞花序组成顶生或腋生的总状花序，花小，白色或淡紫色，花期 7–9 月；果实为小坚果。\n\n紫苏原产东亚，中国各地栽培或野生，喜温暖、阳光充足和湿润的环境，适应性强，常自播繁衍。它的叶片有独特的香气，是中餐、日料和韩餐中常用的香草，可用于包肉、去腥、腌渍和泡茶；紫苏叶、梗和种子均可入药，有解表散寒、行气和胃之效。紫红品种叶色艳丽，也可作观赏植物种植。","habitat":"东亚的田边、路旁与山坡，喜温暖、阳光充足","distribution":"原产东亚，中国各地栽培或野生，日本、朝鲜半岛也有分布","conservation":"暂无评估","details":[{"label":"株高","value":"30–100 厘米，茎四棱形"},{"label":"花期","value":"7–9 月，花小，白色或淡紫"},{"label":"果期","value":"9–11 月，小坚果"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的壤土"},{"label":"繁殖","value":"以播种为主，能自播"},{"label":"主要用途","value":"食用香草、叶与种子入药、观叶"}],"facts":["紫苏有绿色和紫红色两类品种，紫红品种叶色艳丽，也可观赏。","它的叶片有独特香气，是中餐、日料和韩餐中常用的香草。","紫苏叶、梗和种子均可入药，有解表散寒之效。","紫苏适应性强，种子落地后常能自播繁衍。"]},"flower-german-chamomile":{"description":"洋甘菊为菊科母菊属一年生草本，株高 20–50 厘米，茎直立，多分枝。叶片二至三回羽状细裂，裂片线形。头状花序单生枝顶，直径 1–2 厘米，舌状花白色、向下反折，中央管状花黄色、隆起呈圆锥状，花期 5–7 月；果实为瘦果。\n\n洋甘菊原产欧洲和西亚，喜凉爽、阳光充足和排水良好的环境，耐寒不耐酷热，常自播繁衍。它的花序含挥发油，主要成分是母菊薁等，香气清甜，是洋甘菊茶和精油的原料，也被广泛用于护肤和芳香疗法；全草可入药，有镇静安神之效。栽培以播种为主，花初开时采收花序，阴干后可泡茶或提取精油。","habitat":"欧洲与西亚的田边、路旁与草地，喜凉爽、阳光充足","distribution":"原产欧洲与西亚，现世界各地栽培或归化，中国各地药草园常见","conservation":"暂无评估","details":[{"label":"株高","value":"20–50 厘米，茎多分枝"},{"label":"花期","value":"5–7 月，花径 1–2 厘米"},{"label":"果期","value":"花后结瘦果"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松、排水良好的壤土"},{"label":"繁殖","value":"以播种为主"},{"label":"主要用途","value":"花茶、提取精油、药用"}],"facts":["洋甘菊的黄色花心隆起呈圆锥状，白色舌状花向下反折。","它的花序含挥发油，是洋甘菊茶和精油的原料。","洋甘菊有镇静安神之效，常用于护肤和芳香疗法。","花初开时采收花序，阴干后可泡茶。"]},"flower-pampas-grass":{"description":"蒲苇为禾本科蒲苇属多年生草本，株高 1.5–3 米，丛生，茎秆粗壮。叶片带状，长 1–2 米，边缘粗糙。圆锥花序大型，长 30–100 厘米，银白色或淡粉色，羽状蓬松，花期 8–10 月；果实为颖果。雌雄异株，雌花序的羽毛状花柱更为明显。\n\n蒲苇原产南美洲的草原，喜阳光充足、温暖和排水良好的环境，耐旱耐盐碱，适应性强，在部分地区逸生后成为入侵植物。它花序蓬松如羽毛，是花境中极具视觉冲击力的大型观赏草，也常用于干花和景观布置；秋季花序成熟后可剪下插瓶或作装饰。栽培以分株繁殖为主，株型高大，需预留足够空间并防止倒伏。","habitat":"南美草原的湿润至半干旱地带，喜光、耐旱、耐盐碱","distribution":"原产南美洲，世界各地栽培，部分温暖地区逸生为入侵植物","conservation":"暂无评估；在部分地区逸生为入侵植物","details":[{"label":"株高","value":"1.5–3 米，丛生"},{"label":"花期","value":"8–10 月，花序长 30–100 厘米"},{"label":"果期","value":"秋季结颖果"},{"label":"光照","value":"极喜光"},{"label":"水分","value":"耐旱，忌积水"},{"label":"土壤","value":"疏松、排水良好的壤土"},{"label":"繁殖","value":"以分株繁殖为主"},{"label":"主要用途","value":"花境、干花、景观布置"}],"facts":["蒲苇的银白色羽状花序十分蓬松，是大型观赏草的代表。","它雌雄异株，雌花序的羽毛状花柱更为明显。","蒲苇原产南美草原，在部分地区逸生后成为入侵植物。","秋季花序成熟后可剪下插瓶或制作干花。"]},"flower-chinese-pennisetum":{"description":"狼尾草为禾本科狼尾草属多年生草本，株高 60–120 厘米，丛生，茎直立。叶片带状，长 30–60 厘米。圆锥花序圆柱形，长 10–25 厘米，刚毛状，形似蓬松的狼尾，初为淡绿色，后转紫褐色或黄褐色，花期 8–10 月；果实为颖果。\n\n狼尾草原产东亚和澳大利亚，中国各地山坡、路旁和荒地常见，喜阳光充足、温暖湿润和排水良好的环境，耐旱耐瘠薄，适应性强。它花序形似狼尾，随风摇曳，是花境中灵动的观赏草，也可作干花和切叶材料；根系发达，可用于水土保持和边坡绿化。栽培以分株和播种为主，管理粗放。","habitat":"东亚与澳大利亚的草地、路旁与山坡，喜光、耐旱、耐瘠薄","distribution":"原产东亚与澳大利亚，中国各地常见，现世界温暖地区栽培","conservation":"暂无评估","details":[{"label":"株高","value":"60–120 厘米，丛生"},{"label":"花期","value":"8–10 月，花序长 10–25 厘米"},{"label":"果期","value":"秋季结颖果"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"耐旱，忌积水"},{"label":"土壤","value":"疏松、排水良好的壤土，耐瘠薄"},{"label":"繁殖","value":"分株、播种"},{"label":"主要用途","value":"花境、干花、水土保持"}],"facts":["狼尾草的花序圆柱形、刚毛蓬松，形似狼尾，因此得名。","花序初为淡绿色，后转紫褐色或黄褐色，秋季随风摇曳。","它的根系发达，可用于水土保持和边坡绿化。","狼尾草耐旱耐瘠薄，管理粗放，是花境的常用观赏草。"]},"flower-muhly-grass":{"description":"粉黛乱子草为禾本科乱子草属多年生草本，株高 60–100 厘米，丛生。叶片细长，绿色，秋季转为古铜色。圆锥花序大型、松散，由无数细小花序组成，呈粉紫色至玫瑰色，远看如云雾，花期 9–11 月；果实为颖果。\n\n粉黛乱子草原产北美洲的草原，喜阳光充足、温暖和排水良好的环境，耐旱耐瘠薄，适应性强。它秋季抽出粉紫色云雾状花序，成片种植时如粉色云海，是近年非常热门的景观草，常用于公园、花海和道路绿化；花序也可剪下作干花。栽培以分株和播种为主，需保证充足光照，否则花序颜色变淡、株型松散。","habitat":"北美草原的开阔地，喜光、耐旱、耐瘠薄","distribution":"原产北美洲，中国各地景观绿化大量引种栽培","conservation":"暂无评估","details":[{"label":"株高","value":"60–100 厘米，丛生"},{"label":"花期","value":"9–11 月，花序粉紫色"},{"label":"果期","value":"秋季结颖果"},{"label":"光照","value":"极喜光"},{"label":"水分","value":"耐旱，忌积水"},{"label":"土壤","value":"疏松、排水良好的壤土，耐瘠薄"},{"label":"繁殖","value":"分株、播种"},{"label":"主要用途","value":"花海景观、干花、道路绿化"}],"facts":["粉黛乱子草的花序由无数细小花朵组成，远看如粉色云雾。","它原产北美草原，成片种植时如粉色云海，是热门景观草。","光照不足时花序颜色变淡、株型松散。","秋季花序剪下后可制作干花，观赏期较长。"]},"flower-chinese-silvergrass":{"description":"芒草为禾本科芒属多年生草本，株高 1–2 米，丛生，茎秆直立。叶片带状，长 50–100 厘米，边缘有细齿。圆锥花序大型，长 20–40 厘米，主轴明显，小穗有芒，初为紫红色，后转银白色，花期 8–10 月；果实为颖果。\n\n芒草原产东亚，中国各地山坡、林缘和湿地常见，喜阳光充足、温暖和湿润的环境，耐寒耐旱，适应性强，常成片生长形成“芒草荡”。它秋季抽出羽状花序，随风摇曳如波浪，是园林中常见的观赏草，可用于花境、水岸和边坡绿化；茎秆可作造纸和编织材料，花序可作干花。栽培以分株繁殖为主。","habitat":"东亚的山坡、林缘与湿地，喜光、耐寒、耐旱","distribution":"原产东亚，中国各地常见，日本、朝鲜半岛也有分布","conservation":"暂无评估","details":[{"label":"株高","value":"1–2 米，丛生"},{"label":"花期","value":"8–10 月，花序长 20–40 厘米"},{"label":"果期","value":"秋季结颖果"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"耐旱也耐湿"},{"label":"土壤","value":"适应性广，多种土壤均可生长"},{"label":"繁殖","value":"以分株繁殖为主"},{"label":"主要用途","value":"观赏草、造纸编织、干花"}],"facts":["芒草秋季抽出羽状花序，初为紫红、后转银白。","它适应性强，常成片生长形成“芒草荡”。","芒草茎秆可作造纸和编织材料，花序可作干花。","芒草与芦苇外形相似，但花序和叶片结构不同。"]},"flower-cutleaf-coneflower":{"description":"金光菊为菊科金光菊属多年生草本，株高 1–2 米，茎直立，多分枝。叶片羽状深裂，裂片有锯齿。头状花序单生或数个聚生，直径 5–10 厘米，舌状花金黄色、向下翻卷，中央管状花黄绿色、隆起，花期 7–9 月；果实为瘦果。\n\n金光菊原产北美洲的湿润草甸和河岸，喜阳光充足、湿润和排水良好的环境，耐寒性较强，适应性强。它株型高大、花金黄明快，是花境中明亮的秋季花卉，适合布置在花境后景和水岸；同属的重瓣品种常被称为“重瓣金光菊”。栽培以分株和播种为主，花后剪去残花可促进二次开花。","habitat":"北美湿润草甸与河岸，喜光、喜湿、耐寒","distribution":"原产北美洲，中国各地庭园引种栽培","conservation":"暂无评估","details":[{"label":"株高","value":"1–2 米，茎直立多分枝"},{"label":"花期","value":"7–9 月"},{"label":"果期","value":"花后结瘦果"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的壤土"},{"label":"繁殖","value":"分株、播种"},{"label":"主要用途","value":"花境后景、水岸布置、切花"}],"facts":["金光菊的舌状花金黄色、向下翻卷，中央管状花黄绿色隆起。","它株型高大，适合布置在花境后景和水岸。","金光菊原产北美湿润草甸，耐寒且适应性强。","花后剪去残花可促进二次开花。"]},"flower-purple-coneflower":{"description":"松果菊为菊科松果菊属多年生草本，株高 60–120 厘米，茎直立，全株被粗毛。叶片卵形至披针形，互生。头状花序单生茎顶，直径 8–12 厘米，舌状花紫红色、向下垂，中央管状花橙褐色、隆起呈松果状，花期 6–9 月；果实为瘦果。\n\n松果菊原产北美洲的草原，喜阳光充足、耐旱耐寒和排水良好的环境，适应性强。它花心隆起如松果，因此得名，紫红色舌状花下垂，是花境中独特的花型，也常作切花。松果菊的根和全草是欧美传统的药用植物，被认为有增强免疫力的作用，相关制品广泛用于保健品；栽培以分株和播种为主，花后剪去残花可延长花期。","habitat":"北美草原的开阔地，喜光、耐旱、耐寒","distribution":"原产北美洲，中国各地庭园与药草园引种栽培","conservation":"暂无评估","details":[{"label":"株高","value":"60–120 厘米，全株被粗毛"},{"label":"花期","value":"6–9 月"},{"label":"果期","value":"花后结瘦果"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"耐旱，忌积水"},{"label":"土壤","value":"疏松、排水良好的壤土"},{"label":"繁殖","value":"分株、播种"},{"label":"主要用途","value":"花境、切花、药用"}],"facts":["松果菊的中央管状花隆起呈松果状，因此得名。","紫红色舌状花向下垂，是花境中独特的花型。","它的根和全草是欧美传统的药用植物，常用于保健品。","松果菊耐旱耐寒，原产北美草原，适应性强。"]},"flower-black-eyed-susan":{"description":"黑心菊为菊科金光菊属一二年生草本，株高 30–90 厘米，茎直立，全株被粗毛。叶片卵形至长椭圆形，互生。头状花序单生或数个聚生，直径 5–10 厘米，舌状花金黄色至橙黄色，中央管状花黑褐色、隆起呈锥状，花期 6–10 月；果实为瘦果。\n\n黑心菊原产北美洲的草原与路旁，喜阳光充足、温暖和排水良好的环境，耐旱耐寒，适应性强。它金黄色舌状花与黑褐色花心形成强烈对比，因此得名，是花坛、花境和路旁绿化的常用花卉，也常作切花。栽培以播种为主，能自播繁衍；花后剪去残花可促进再次开花，是夏秋季节管理粗放的开花植物。","habitat":"北美草原、路旁与开阔地，喜光、耐旱","distribution":"原产北美洲，中国各地花坛引种栽培","conservation":"暂无评估","details":[{"label":"株高","value":"30–90 厘米，全株被粗毛"},{"label":"花期","value":"6–10 月"},{"label":"果期","value":"花后结瘦果"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"耐旱，忌积水"},{"label":"土壤","value":"疏松、排水良好的壤土"},{"label":"繁殖","value":"以播种为主，能自播"},{"label":"主要用途","value":"花坛、花境、切花"}],"facts":["黑心菊金黄色舌状花围绕黑褐色隆起花心，因此得名。","它原产北美草原，耐旱耐寒，适应性强。","黑心菊能自播繁衍，花后剪去残花可促进再次开花。","色彩对比强烈，是花坛和路旁绿化的常用材料。"]},"flower-garden-phlox":{"description":"宿根福禄考为花荵科福禄考属多年生草本，株高 60–120 厘米，茎直立。叶片长椭圆形至披针形，对生。圆锥花序顶生，由多数小花密集组成，花冠高脚碟状，5 裂，有粉、紫、红、白等色，喉部常有深色斑纹，花期 6–9 月；果实为蒴果。\n\n宿根福禄考原产北美洲东部的湿润林地与草甸，喜阳光充足、湿润和排水良好的环境，耐寒性较强。它花序密集、花色柔和、花期长且带香气，是花境和庭院夏秋的经典花卉，也常作切花。栽培以分株和扦插为主，每 2–3 年分株一次可保持长势；夏季需保持土壤湿润，避免干旱导致下部叶片枯黄。","habitat":"北美东部湿润林地与草甸，喜光、喜湿、耐寒","distribution":"原产北美洲东部，中国各地庭园引种栽培","conservation":"暂无评估","details":[{"label":"株高","value":"60–120 厘米，茎直立"},{"label":"花期","value":"6–9 月，花序密集"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜充足阳光，也耐半阴"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的壤土"},{"label":"繁殖","value":"分株、扦插"},{"label":"主要用途","value":"花境、庭院点缀、切花"}],"facts":["宿根福禄考的花冠喉部常有深色斑纹，是识别品种的特征。","它花序密集、花期长，是花境和庭院的经典花卉。","栽培中每 2–3 年分株一次，可保持植株长势。","夏季需保持土壤湿润，干旱时下部叶片容易枯黄。"]},"flower-new-york-aster":{"description":"荷兰菊为菊科紫菀属多年生草本，株高 50–100 厘米，茎直立，多分枝。叶片披针形至线形，互生。头状花序多数，密集成伞房状，直径 2–3 厘米，舌状花蓝紫、粉紫或白色，中央管状花黄色，花期 9–10 月；果实为瘦果。\n\n荷兰菊原产北美洲，喜阳光充足、凉爽和排水良好的环境，耐寒性强，适应性强。它秋季开花、花量大，蓝紫色小花密集成片，是秋季花坛和切花的常见材料，也可用于花境后景和道路绿化。栽培以分株和扦插为主，生长期摘心可促进分枝、增加花量；花后剪除残花，有利于越冬和翌年萌发。","habitat":"北美的湿润草甸与河岸，喜光、耐寒、喜湿润","distribution":"原产北美洲，中国各地庭园引种栽培","conservation":"暂无评估","details":[{"label":"株高","value":"50–100 厘米，茎多分枝"},{"label":"花期","value":"9–10 月，花量大"},{"label":"果期","value":"花后结瘦果"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的壤土"},{"label":"繁殖","value":"分株、扦插"},{"label":"主要用途","value":"秋季花坛、花境、切花"}],"facts":["荷兰菊秋季开花，蓝紫色小花密集成片，花量很大。","它原产北美，耐寒性强，是秋季花坛的常见材料。","生长期摘心可促进分枝、增加花量。","花后剪除残花，有利于植株越冬和翌年萌发。"]},"flower-blanket-flower":{"description":"天人菊为菊科天人菊属一年生草本，株高 20–60 厘米，茎直立或斜生，全株被短毛。叶片长椭圆形至披针形，互生。头状花序单生，直径 4–7 厘米，舌状花基部红褐色、先端金黄色，中央管状花紫红色，花期 6–10 月；果实为瘦果。\n\n天人菊原产北美洲的草原与沙地，喜阳光充足、温暖干燥和排水良好的环境，耐旱耐瘠薄，适应性强。它舌状花基部红褐、先端金黄，色彩热烈如火，是耐旱花坛、岩石园和野花组合的常用花卉；在北美也是常见的路旁野花，能自播繁衍。栽培以播种为主，需保证充足光照，忌积水和阴湿。","habitat":"北美草原与沙地，喜光、耐旱、耐瘠薄","distribution":"原产北美洲，中国各地花坛引种栽培","conservation":"暂无评估","details":[{"label":"株高","value":"20–60 厘米，茎直立或斜生"},{"label":"花期","value":"6–10 月"},{"label":"果期","value":"花后结瘦果"},{"label":"光照","value":"极喜光"},{"label":"水分","value":"耐旱，忌积水"},{"label":"土壤","value":"疏松、排水良好的沙质土"},{"label":"繁殖","value":"以播种为主"},{"label":"主要用途","value":"花坛、岩石园、野花组合"}],"facts":["天人菊舌状花基部红褐、先端金黄，色彩像燃烧的火焰。","它原产北美草原和沙地，耐旱耐瘠薄，适应性强。","天人菊是野花组合和岩石园的常用花卉，能自播繁衍。","栽培需充足光照，积水和阴湿会导致生长不良。"]},"flower-purpletop-vervain":{"description":"柳叶马鞭草为马鞭草科马鞭草属多年生草本，株高 1–1.5 米，茎直立、四棱形，上部多分枝。叶片对生，披针形，边缘有锯齿。聚伞花序组成顶生的伞房状花团，花小，蓝紫色，花期 6–10 月；果实为蒴果。\n\n柳叶马鞭草原产南美洲的草原，喜阳光充足、温暖干燥和排水良好的环境，耐旱耐瘠薄，适应性强，在部分地区逸生后成为入侵植物。它茎秆高挑、花序轻盈，蓝紫色小花团仿佛悬浮在空中，是花境中营造空气感的重要植物，也常作切花。栽培以播种和扦插为主，花后修剪可促进二次开花；因其自播力强，需注意控制蔓延。","habitat":"南美草原，喜光、耐旱、耐瘠薄","distribution":"原产南美洲，世界各地栽培，部分温暖地区逸生为入侵植物","conservation":"暂无评估；在部分地区逸生为入侵植物","details":[{"label":"株高","value":"1–1.5 米，茎四棱形"},{"label":"花期","value":"6–10 月，花序伞房状"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"极喜光"},{"label":"水分","value":"耐旱，忌积水"},{"label":"土壤","value":"疏松、排水良好的壤土"},{"label":"繁殖","value":"播种、扦插"},{"label":"主要用途","value":"花境中景、切花、景观绿化"}],"facts":["柳叶马鞭草茎秆高挑，蓝紫色花团仿佛悬浮在空中。","它原产南美草原，耐旱耐瘠薄，自播力强。","在部分地区逸生后大量繁殖，被视为入侵植物。","花后修剪可促进二次开花，是花境的常用材料。"]},"flower-spiked-speedwell":{"description":"穗花婆婆纳为车前科婆婆纳属多年生草本，株高 30–60 厘米，茎直立，多分枝。叶片披针形至线形，对生，边缘有锯齿。穗状花序顶生，细长，花小，蓝紫色或粉紫色，花期 6–8 月；果实为蒴果。\n\n穗花婆婆纳原产欧洲和亚洲的草原与山地，喜阳光充足、凉爽干燥和排水良好的环境，耐寒耐旱，适应性强。它蓝紫色穗状花序细长挺拔，是花境中经典的竖线条植物，与圆形花头的植物搭配可增加层次，也常作切花。栽培以分株和扦插为主，花后修剪可促进二次开花，生长期保持充足光照有利于花序发育。","habitat":"欧亚草原与山地草甸，喜光、耐寒、耐旱","distribution":"原产欧洲与亚洲，中国北方山地有分布，各地庭园栽培","conservation":"暂无评估","details":[{"label":"株高","value":"30–60 厘米，茎多分枝"},{"label":"花期","value":"6–8 月，穗状花序细长"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"耐旱，忌积水"},{"label":"土壤","value":"疏松、排水良好的壤土"},{"label":"繁殖","value":"分株、扦插"},{"label":"主要用途","value":"花境竖线条、切花"}],"facts":["穗花婆婆纳的穗状花序细长挺拔，是花境的竖线条材料。","它原产欧亚草原，耐寒耐旱，适应性强。","与圆形花头的植物搭配种植，可增加花境层次。","花后修剪可促进二次开花，生长期需充足光照。"]},"flower-penstemon":{"description":"钓钟柳为车前科钓钟柳属多年生草本，株高 40–80 厘米，茎直立，多分枝。叶片披针形，对生，边缘有细齿。圆锥花序顶生，花冠钟形或管状，长 2–3 厘米，紫红、粉、白等色，花期 6–9 月；果实为蒴果。\n\n钓钟柳原产墨西哥的山地，喜阳光充足、凉爽干燥和排水良好的环境，耐寒性一般，怕高温高湿和积水。它钟形花朵成串开放，花色柔和，花期长，是花境中富有野趣的竖线条植物，也常作切花；花后修剪可促进二次开花。栽培以分株、扦插为主，夏季高温时需适当遮阴，避免植株萎蔫。","habitat":"墨西哥山地，喜凉爽、阳光充足、排水良好","distribution":"原产墨西哥，中国各地花境引种栽培","conservation":"暂无评估","details":[{"label":"株高","value":"40–80 厘米，茎多分枝"},{"label":"花期","value":"6–9 月，花冠钟形"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜充足阳光，夏季适当遮阴"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松、排水良好的壤土"},{"label":"繁殖","value":"分株、扦插"},{"label":"主要用途","value":"花境竖线条、切花"}],"facts":["钓钟柳的钟形花朵成串开放，花色从紫红到粉白都有。","它原产墨西哥山地，喜凉爽而怕高温高湿。","花期长，是花境中富有野趣的竖线条植物。","花后修剪可促进二次开花。"]},"flower-prince-feather":{"description":"红蓼为蓼科蓼属一年生草本，株高 1–2 米，茎直立，多分枝，全株被长毛。叶片宽卵形，长 10–20 厘米，边缘全缘。穗状花序顶生或腋生，长 3–8 厘米，花小，粉红色或白色，花期 6–9 月；果实为瘦果。\n\n红蓼原产东亚和澳大利亚，中国各地水边、路旁和荒地常见，喜阳光充足、温暖湿润的环境，适应性强，常成片生长。它植株高大、粉红色穗状花序低垂如红穗，是水边和庭院中富有野趣的花卉，也可作切花和干花；嫩叶可食，果实和全草可入药。栽培以播种为主，需注意控制其自播蔓延。","habitat":"东亚与澳大利亚的水边、路旁与荒地，喜光、喜湿","distribution":"原产东亚与澳大利亚，中国各地水边常见","conservation":"暂无评估","details":[{"label":"株高","value":"1–2 米，茎多分枝"},{"label":"花期","value":"6–9 月，穗状花序长 3–8 厘米"},{"label":"果期","value":"8–10 月，瘦果"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"喜湿润，耐浅水"},{"label":"土壤","value":"疏松肥沃、湿润的壤土"},{"label":"繁殖","value":"以播种为主，能自播"},{"label":"主要用途","value":"水边观赏、切花、全草入药"}],"facts":["红蓼粉红色的穗状花序低垂如红穗，因此得名。","它植株高大，常成片生长在水边和荒地。","红蓼嫩叶可食，果实和全草可入药。","适应性强，种子落地后容易自播蔓延。"]},"flower-josephs-coat":{"description":"雁来红为苋科苋属一年生草本，株高 1–1.5 米，茎直立，少分枝。叶片卵形至披针形，有绿、红、黄等色，秋季顶端叶片转为鲜红或黄红相间，十分醒目。花小，绿色，密集成穗状花序，花期 7–8 月；果实为胞果。\n\n雁来红原产热带亚洲，中国各地栽培或野生，喜阳光充足、温暖和湿润的环境，适应性强。它顶端叶片在秋季转为鲜红或黄红相间，因大雁南来时叶色变红而得名，是观叶与食用兼用的植物：嫩叶可作蔬菜，种子可食，全草可入药。栽培以播种为主，生长期需充足阳光，叶色才会鲜艳；也可用于花境和庭院点缀。","habitat":"热带亚洲的田边、路旁与荒地，喜温暖、阳光充足","distribution":"原产热带亚洲，中国各地栽培或野生","conservation":"暂无评估","details":[{"label":"株高","value":"1–1.5 米，茎直立少分枝"},{"label":"花期","value":"7–8 月，穗状花序绿色"},{"label":"果期","value":"9–10 月，胞果"},{"label":"光照","value":"喜充足阳光"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的壤土"},{"label":"繁殖","value":"以播种为主"},{"label":"主要用途","value":"观叶、嫩叶食用、全草入药"}],"facts":["雁来红顶端叶片在秋季转为鲜红，因大雁南来时叶色变红而得名。","它原产热带亚洲，嫩叶和种子可食，全草可入药。","生长期需充足阳光，叶色才会鲜艳。","雁来红适应性强，在田边和荒地也能生长。"]},"flower-guzmania":{"description":"观赏凤梨为凤梨科果子曼属多年生附生草本，株高 20–40 厘米，叶片带状、革质，莲座状排列，中央形成水槽。花序自叶丛中央抽出，苞片鲜红、橙或黄色，小花黄色或白色，花期可长达数月；果实为浆果。\n\n观赏凤梨原产中南美洲的热带雨林，附生于树干和岩石上，喜温暖、湿润和明亮的散射光，忌强光暴晒和积水。它苞片鲜艳、花期长，是室内盆栽的常见观花观叶植物，叶丛中央的水槽可储存水分；栽培常用树皮、水苔等透气基质，保持叶心有水但避免腐烂。母株开花后基部会萌发侧芽，侧芽长成后可分株繁殖。","habitat":"中南美洲热带雨林的树干与岩石上，喜温暖、湿润、散射光","distribution":"原产中南美洲，现世界各地盆栽，中国各地花市常见","conservation":"暂无评估","details":[{"label":"株高","value":"20–40 厘米，莲座状"},{"label":"花期","value":"花期可长达数月"},{"label":"果期","value":"花后结浆果"},{"label":"光照","value":"喜明亮散射光，忌强光"},{"label":"水分","value":"叶心水槽储水，忌积水腐烂"},{"label":"土壤","value":"以树皮、水苔等附生基质栽培"},{"label":"繁殖","value":"分株繁殖"},{"label":"主要用途","value":"室内盆栽、案头观赏"}],"facts":["观赏凤梨的鲜艳部分多为苞片，真正的花较小。","它叶丛中央形成水槽，可储存水分供植株吸收。","观赏凤梨原产中南美洲雨林，是附生植物。","母株开花后基部会萌发侧芽，可分株繁殖。"]},"flower-air-plant":{"description":"空气凤梨为凤梨科铁兰属多年生附生草本，株高 5–15 厘米，叶片细长、肉质，表面密布银白色鳞片，植株呈莲座状或丛生。花小，管状，紫色或白色，花期不定，多在春夏；苞片在花期变红，十分醒目；果实为蒴果。\n\n空气凤梨原产中南美洲的热带和亚热带地区，附生于树干、岩石甚至电线上，靠叶片表面的银白色鳞片吸收空气中的水分和养分，因此不需要土壤。它形态奇特、管理简单，可直接悬挂、粘贴或摆放在支架上，是近年流行的“空气植物”；养护时需定期喷雾或浸泡补水，并保持良好通风和明亮散射光。","habitat":"中南美洲的树干、岩石上，喜温暖、通风、散射光","distribution":"原产中南美洲，现世界各地盆栽，中国各地花市常见","conservation":"暂无评估","details":[{"label":"株高","value":"5–15 厘米，莲座状或丛生"},{"label":"花期","value":"多在春夏，苞片变红"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜明亮散射光"},{"label":"水分","value":"靠叶面鳞片吸水，需定期喷雾"},{"label":"土壤","value":"不需要土壤，可悬挂栽培"},{"label":"繁殖","value":"侧芽分株"},{"label":"主要用途","value":"悬挂装饰、桌面盆栽"}],"facts":["空气凤梨不需要土壤，靠叶片表面的鳞片吸收空气中的水分和养分。","它可直接悬挂、粘贴或摆放在支架上，是奇特的“空气植物”。","养护时需定期喷雾或浸泡补水，并保持良好通风。","花期苞片变红，小花管状，紫色或白色。"]},"flower-oncidium":{"description":"文心兰为兰科文心兰属多年生附生草本，假鳞茎扁球形，叶片 2–3 枚，带状。花葶自假鳞茎抽出，多分枝，着花数十朵，花小，金黄色或黄褐色，唇瓣宽大、形似裙摆，花期秋冬，单株花期可达一两个月；果实为蒴果。\n\n文心兰原产巴西的热带雨林，附生于树干上，喜温暖、湿润、半阴和通风良好的环境，忌强光暴晒和积水。它花形奇特、花朵轻盈，成串开放如金色蝴蝶飞舞，因此有“跳舞兰”之称，是切花和盆栽的常见兰花；栽培常用树皮、水苔等透气基质，花后剪去花葶、保留叶片养球。","habitat":"巴西热带雨林的树干上，喜温暖、湿润、半阴","distribution":"原产巴西，现世界各地栽培，中国南方大量生产","conservation":"暂无评估；CITES 附录Ⅱ（兰科植物）","details":[{"label":"株高","value":"花葶长 30–60 厘米，着花数十朵"},{"label":"花期","value":"秋冬，单株花期可达一两个月"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜半阴散射光"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"以树皮、水苔等透气基质栽培"},{"label":"繁殖","value":"分株繁殖"},{"label":"主要用途","value":"切花、盆栽观赏"}],"facts":["文心兰花朵轻盈、成串开放，像金色蝴蝶在跳舞，因此称“跳舞兰”。","它原产巴西热带雨林，是附生兰花。","单株花期可达一两个月，是切花和盆栽的常见兰花。","栽培常用树皮、水苔等透气基质，忌积水。"]},"flower-cattleya":{"description":"卡特兰为兰科卡特兰属多年生附生草本，假鳞茎棍棒状，叶片 1–2 枚，革质。花大，直径 10–20 厘米，有紫红、粉、白、黄等色，唇瓣宽大、边缘皱褶，形似裙摆，香气浓郁，花期秋冬；果实为蒴果。\n\n卡特兰原产巴西的热带雨林，附生于树干和岩石上，喜温暖、湿润、半阴和通风良好的环境，忌强光暴晒和积水。它花朵硕大艳丽、唇瓣宽大如裙，香气浓郁，是洋兰中最负盛名的种类之一，也是重要的切花材料；栽培常用树皮、水苔等透气基质，需保持较高空气湿度和明亮散射光。","habitat":"巴西热带雨林的树干与岩石上，喜温暖、湿润、半阴","distribution":"原产巴西，现世界各地广泛栽培，是重要的洋兰切花","conservation":"暂无评估；CITES 附录Ⅱ（兰科植物）","details":[{"label":"株高","value":"花径 10–20 厘米"},{"label":"花期","value":"秋冬，香气浓郁"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜半阴散射光"},{"label":"水分","value":"喜湿润，空气湿度较高"},{"label":"土壤","value":"以树皮、水苔等透气基质栽培"},{"label":"繁殖","value":"分株繁殖"},{"label":"主要用途","value":"切花、盆栽观赏"}],"facts":["卡特兰花朵硕大，唇瓣宽大如裙，是洋兰中最负盛名的种类之一。","它原产巴西热带雨林，是附生兰花。","卡特兰香气浓郁，是重要的切花材料。","栽培需保持较高空气湿度和明亮散射光。"]},"flower-gladiolus":{"description":"唐菖蒲为鸢尾科唐菖蒲属多年生球根草本，株高 0.6–1.5 米，地下具扁球形球茎。叶片剑形，互生，排成两列。花葶直立，穗状花序着花 10–20 朵，自下而上依次开放，花冠漏斗状，有红、黄、粉、白、紫及复色，花期 6–9 月；果实为蒴果。\n\n唐菖蒲原产南非，是多种野生唐菖蒲杂交选育而成的园艺类群，中国各地广泛栽培。它喜阳光充足、凉爽通风的环境，适宜疏松肥沃、排水良好的沙质土壤。花葶挺拔、花色丰富，是世界四大切花之一，也适合布置花境与庭院；栽培以分球繁殖为主，球茎需每年更新。切花采收宜在花序下部 1–2 朵花开放时进行，采后及时插入清水可延长观赏期。","habitat":"阳光充足的庭园与花圃，喜凉爽通风","distribution":"原产南非；中国各地广泛栽培，云南、广东为主要切花产区","conservation":"暂无评估；栽培园艺类群，未见野生居群","details":[{"label":"株高","value":"0.6–1.5 米，花葶直立"},{"label":"花期","value":"6–9 月，穗状花序自下而上开放"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜阳光充足"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的沙质土"},{"label":"主要用途","value":"切花、花境与庭院观赏"}],"facts":["唐菖蒲是世界四大切花之一，与月季、菊花、康乃馨齐名。","它的花序自下而上开放，因此切花观赏期很长。","唐菖蒲并非原产中国，其亲本多来自南非。","球茎需每年更新，退化后开花质量会明显下降。"]},"flower-freesia":{"description":"小苍兰为鸢尾科小苍兰属多年生球根草本，株高 30–60 厘米，地下具圆锥形球茎。叶片线形，基生，排成两列。花葶细长，穗状花序稍弯曲，着花 5–10 朵，花冠漏斗状，有黄、白、粉、紫、红等色，香气清甜，花期 2–5 月；果实为蒴果。\n\n小苍兰原产南非，中国各地温室与庭院栽培，喜凉爽湿润、阳光充足的环境，不耐寒，适宜疏松肥沃、排水良好的沙质土壤。它花色明丽、香气清甜，是重要的切花与盆栽花卉，常用于花束、花篮与室内摆放；栽培以分球繁殖为主，球茎需经过低温处理才能正常开花。切花采收宜在花序下部花朵开放时进行，采后避免与水果同放，以免乙烯加速衰老。","habitat":"凉爽湿润的庭园与温室，喜阳光充足","distribution":"原产南非；中国各地温室与庭院栽培","conservation":"暂无评估；中国未列入国家重点保护野生植物名录","details":[{"label":"株高","value":"30–60 厘米，花葶细长"},{"label":"花期","value":"2–5 月，花漏斗状、香气清甜"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜阳光充足"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的沙质土"},{"label":"主要用途","value":"切花、盆栽与花束"}],"facts":["小苍兰的香气清甜，是香水和芳香产品中常见的香调。","它原产南非，球茎需经过低温处理才能正常开花。","小苍兰的花序向一侧弯曲，花朵排列成整齐的一排。","切花应避免与苹果、香蕉等水果同放，以免乙烯加速凋谢。"]},"flower-saffron-crocus":{"description":"番红花为鸢尾科番红花属多年生球根草本，株高 10–20 厘米，地下具球形球茎。叶片线形，基生，中间具白色纵纹。花 1–3 朵自叶丛抽出，花冠淡紫色，花被片 6 枚，喉部具毛，花柱细长、顶端三裂，深红色，花期 10–11 月；果实为蒴果。\n\n番红花原产地中海沿岸至伊朗一带，中国上海、浙江、江苏等地引种栽培。它喜凉爽湿润、阳光充足的环境，秋季开花，夏季休眠，适宜疏松肥沃、排水良好的沙质土壤。花柱与柱头可制名贵香料藏红花，也可入药，有活血化瘀、凉血解毒之效；因每朵花仅产 3 根花柱，需大量人工采收，价格昂贵。栽培以分球繁殖为主，球茎需在夏季休眠期保持干燥。","habitat":"地中海气候的向阳坡地，喜凉爽湿润","distribution":"原产地中海沿岸至伊朗；中国上海、浙江、江苏等地引种","conservation":"暂无评估；为栽培起源的三倍体，未见野生居群","details":[{"label":"株高","value":"10–20 厘米，球茎球形"},{"label":"花期","value":"10–11 月，花淡紫色"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜阳光充足"},{"label":"水分","value":"喜湿润，夏季休眠期忌水"},{"label":"土壤","value":"疏松肥沃、排水良好的沙质土"},{"label":"主要用途","value":"藏红花香料、药用与观赏"}],"facts":["藏红花是番红花的花柱，每朵花只有 3 根，需人工逐朵采摘。","番红花是秋季开花，与其他春季开花的球根花卉不同。","它原产地中海沿岸，中国上海、浙江等地已有规模化种植。","藏红花既是香料也是药材，用量不宜过大。"]},"flower-grape-hyacinth":{"description":"葡萄风信子为天门冬科蓝壶花属多年生球根草本，株高 15–25 厘米，地下具球形鳞茎。叶片线形，基生，粉绿色。花葶直立，总状花序密集，由数十朵小球状花组成，花冠坛状，蓝紫色至淡蓝色，顶端常闭合，花期 3–5 月；果实为蒴果。\n\n葡萄风信子原产地中海沿岸及小亚细亚一带，中国各地引种栽培，喜凉爽湿润、阳光充足的环境，耐寒性较强，适宜疏松肥沃、排水良好的沙质土壤。它花序密集、形如葡萄串，花色清新，是早春庭院、花坛与盆栽的常见花卉；也可成片种植于草坪边缘与林下。栽培以分球繁殖为主，夏季休眠期需保持干燥，秋季栽种后浇透水即可。","habitat":"地中海沿岸的草坡与林缘，喜凉爽湿润","distribution":"原产地中海沿岸及小亚细亚；中国各地引种栽培","conservation":"暂无评估；中国未列入国家重点保护野生植物名录","details":[{"label":"株高","value":"15–25 厘米，花葶直立"},{"label":"花期","value":"3–5 月，花蓝紫色"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜阳光充足"},{"label":"水分","value":"喜湿润，休眠期保持干燥"},{"label":"土壤","value":"疏松肥沃、排水良好的沙质土"},{"label":"主要用途","value":"早春花坛、草坪边缘与盆栽"}],"facts":["葡萄风信子的花序由数十朵小球状花密集组成，形似一串葡萄。","它虽然叫“风信子”，却属于天门冬科蓝壶花属。","葡萄风信子耐寒性较强，适合在北方露地越冬。","夏季休眠期要保持干燥，否则鳞茎容易腐烂。"]},"flower-snowdrop":{"description":"雪滴花为石蒜科雪滴花属多年生球根草本，株高 10–20 厘米，地下具球形鳞茎。叶片线形，基生，粉绿色。花葶直立，花单生，下垂，花被片 6 枚，白色，外轮 3 枚较长，内轮 3 枚较短、顶端具绿色斑点，花期 2–4 月；果实为蒴果。\n\n雪滴花原产欧洲中部至南部，中国北方园林引种栽培，喜凉爽湿润、半阴的环境，耐寒性极强，常在雪中开花，适宜疏松肥沃、排水良好的土壤。它花形小巧、花色洁白，是欧洲早春的代表花卉，常成片种植于林下、草坪边缘与岩石园；鳞茎含生物碱，有毒，不可食用。栽培以分球繁殖为主，花后需保留叶片养球，夏季休眠期保持干燥。","habitat":"欧洲林下、草甸与岩石坡地，喜凉爽半阴","distribution":"原产欧洲中部至南部；中国北方园林引种栽培","conservation":"暂无评估；部分欧洲国家关注其野生种群","details":[{"label":"株高","value":"10–20 厘米，花葶直立"},{"label":"花期","value":"2–4 月，花白色下垂"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜半阴，也耐林下散射光"},{"label":"水分","value":"喜湿润，休眠期保持干燥"},{"label":"土壤","value":"疏松肥沃、排水良好的土壤"},{"label":"主要用途","value":"早春林下、草坪边缘与岩石园"}],"facts":["雪滴花常在雪中开花，是欧洲最早报春的花卉之一。","它的内轮花瓣顶端有绿色斑点，是辨认的重要特征。","雪滴花虽小，却含有生物碱，全株有毒，不可食用。","英国有专门的雪滴花观赏园，早春吸引大量游客。"]},"flower-lily-of-the-valley":{"description":"铃兰为天门冬科铃兰属多年生草本，株高 15–30 厘米，地下具横走的根状茎。叶片 2 枚，椭圆形至卵状披针形，基生，具长柄，叶脉平行。花葶自叶丛抽出，总状花序偏向一侧，着花 6–10 朵，花冠钟状，白色，下垂，香气清雅，花期 4–5 月；果实为浆果，球形，成熟时红色，果期 8–9 月。\n\n铃兰原产欧洲、亚洲北部及北美，中国东北、华北、西北山地有分布，生于林下阴湿处。它喜凉爽湿润、半阴的环境，耐寒性强，适宜疏松肥沃、排水良好的土壤。花序下垂、香气清雅，是著名的林下观赏植物，也常作切花；全株含铃兰毒苷，有毒，误食可致心律失常，栽培与观赏时应避免儿童与宠物接触。","habitat":"林下阴湿处与溪边，喜凉爽半阴","distribution":"欧洲、亚洲北部及北美；中国东北、华北、西北山地","conservation":"暂无评估；中国未列入国家重点保护野生植物名录","details":[{"label":"株高","value":"15–30 厘米，根状茎横走"},{"label":"花期","value":"4–5 月，花白色钟状"},{"label":"果期","value":"8–9 月，浆果红色"},{"label":"光照","value":"喜半阴，忌强光暴晒"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的土壤"},{"label":"主要用途","value":"林下观赏、切花与地被"}],"facts":["铃兰的花序偏向一侧，花朵像一串白色小铃铛。","它的香气清雅，是香水工业中常用的香调。","铃兰全株有毒，误食可致心律失常，观赏时不要采食。","铃兰是芬兰的国花，也是欧洲婚礼常用的手捧花。"]},"flower-hosta":{"description":"玉簪为天门冬科玉簪属多年生草本，株高 40–80 厘米，地下具粗壮的根状茎。叶片基生，卵形至心形，宽大，表面深绿色、有光泽，具弧形叶脉。花葶自叶丛抽出，高 40–80 厘米，总状花序着花 10–20 朵，花冠漏斗状，白色，香气浓郁，花期 6–8 月；果实为蒴果。\n\n玉簪原产中国长江流域及以南地区，生于林下阴湿处，各地庭院广泛栽培。它喜半阴湿润的环境，忌强光暴晒，耐寒性较强，适宜疏松肥沃、排水良好的土壤。叶片宽大优美、花色洁白、香气浓郁，是林下与庭院常见的耐阴植物，也常作切花；嫩芽可食，根与叶可入药，有清热解毒之效。栽培以分株繁殖为主，夏季需遮阴并保持土壤湿润。","habitat":"林下阴湿处与庭院，喜半阴湿润","distribution":"中国长江流域及以南地区；各地庭院广泛栽培","conservation":"暂无评估；中国未列入国家重点保护野生植物名录","details":[{"label":"株高","value":"40–80 厘米，根状茎粗壮"},{"label":"花期","value":"6–8 月，花白色、香气浓郁"},{"label":"果期","value":"花后结蒴果"},{"label":"光照","value":"喜半阴，忌强光暴晒"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的土壤"},{"label":"主要用途","value":"林下观叶观花，切花与药用"}],"facts":["玉簪的花蕾形似白色玉簪，因此得名。","它叶片宽大、耐阴性强，是林下绿化的常用植物。","玉簪的花在傍晚开放，香气在夜间更浓郁。","嫩芽可食，但根与叶入药需遵医嘱，不可自行采食。"]},"flower-blue-plantain-lily":{"description":"紫萼为天门冬科玉簪属多年生草本，株高 30–60 厘米，地下具粗壮根状茎。叶片基生，卵形至卵圆形，宽大，表面深绿色，基部心形。花葶自叶丛抽出，总状花序着花 10 余朵，花冠漏斗状，淡紫色至紫红色，花期 6–7 月；果实为蒴果，果期 8–9 月。\n\n紫萼原产中国华东、华中至西南地区，生于林下阴湿处，各地庭院栽培。它喜半阴湿润的环境，忌强光暴晒，耐寒性较强，适宜疏松肥沃、排水良好的土壤。叶片宽大、花色淡紫，耐阴湿，是林下与庭院常见的观叶观花植物；与玉簪相比，紫萼花朵呈淡紫色、叶片较窄。栽培以分株繁殖为主，需保持土壤湿润，夏季适当遮阴。","habitat":"林下阴湿处、溪边与庭院，喜半阴湿润","distribution":"中国华东、华中至西南地区；各地庭院栽培","conservation":"暂无评估；中国未列入国家重点保护野生植物名录","details":[{"label":"株高","value":"30–60 厘米，根状茎粗壮"},{"label":"花期","value":"6–7 月，花淡紫色"},{"label":"果期","value":"8–9 月，蒴果"},{"label":"光照","value":"喜半阴，忌强光暴晒"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的土壤"},{"label":"主要用途","value":"林下观叶观花，庭院点缀"}],"facts":["紫萼与玉簪同属，但紫萼的花是淡紫色，玉簪的花是白色。","它的叶片宽大、耐阴湿，适合种在树下和建筑北侧。","紫萼的花葶高出叶丛，开花时花序随风摇曳。","根状茎可入药，但需遵医嘱，不可自行采食。"]},"flower-fragrant-solomons-seal":{"description":"玉竹为天门冬科黄精属多年生草本，株高 30–60 厘米，地下具横走的肉质根状茎。茎直立，叶互生，椭圆形至卵状椭圆形，全缘，表面绿色。花腋生，常 1–3 朵，花冠筒状，白色至淡绿色，下垂，花期 5–6 月；果实为浆果，球形，成熟时蓝黑色，果期 8–9 月。\n\n玉竹原产中国东北、华北、华东至西南各地，生于林下阴湿处，朝鲜半岛、日本也有分布。它喜凉爽湿润、半阴的环境，耐寒性强，适宜疏松肥沃、排水良好的土壤。根茎入药称“玉竹”，有养阴润燥、生津止渴之效，也可煲汤、煮粥；植株姿态优雅，是林下常见的药用与观赏植物。栽培以根茎繁殖为主，需保持土壤湿润并适当遮阴。","habitat":"林下阴湿处、溪边与山坡草丛，喜凉爽半阴","distribution":"中国东北、华北、华东至西南各地；朝鲜半岛、日本","conservation":"暂无评估；中国未列入国家重点保护野生植物名录","details":[{"label":"株高","value":"30–60 厘米，根状茎横走"},{"label":"花期","value":"5–6 月，花白色钟状"},{"label":"果期","value":"8–9 月，浆果蓝黑色"},{"label":"光照","value":"喜半阴，忌强光暴晒"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的土壤"},{"label":"主要用途","value":"根茎入药、煲汤，林下观赏"}],"facts":["玉竹的根茎横走，节间明显，是辨认它的重要特征。","它的花腋生下垂，像一串白色小铃铛。","玉竹根茎可入药，也可用来煲汤、煮粥。","玉竹耐寒喜阴，适合种在林下和建筑北侧。"]},"flower-siberian-solomons-seal":{"description":"黄精为天门冬科黄精属多年生草本，株高 50–100 厘米，地下具肥厚的肉质根状茎，常呈结节状。茎直立，叶轮生，每轮 4–6 枚，线状披针形，先端卷曲。花腋生，伞状花序，花冠筒状，白色至淡黄色，下垂，花期 5–6 月；果实为浆果，球形，成熟时黑色，果期 8–9 月。\n\n黄精原产中国东北、华北、华东至西南各地，生于林下、灌丛与山坡阴湿处。它喜凉爽湿润、半阴的环境，耐寒性强，适宜疏松肥沃、排水良好的土壤。根茎肥厚，可入药，有补气养阴、健脾润肺、益肾之效，也是常见的药食两用植物，可煲汤、泡酒；栽培以根茎繁殖为主，生长周期较长。野生黄精因采挖过度，资源日益减少，应重视人工栽培。","habitat":"林下、灌丛与山坡阴湿处，喜凉爽半阴","distribution":"中国东北、华北、华东至西南各地","conservation":"暂无评估；野生资源因过度采挖而减少","details":[{"label":"株高","value":"50–100 厘米，根状茎结节状"},{"label":"花期","value":"5–6 月，花白色至淡黄色"},{"label":"果期","value":"8–9 月，浆果黑色"},{"label":"光照","value":"喜半阴，忌强光暴晒"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的土壤"},{"label":"主要用途","value":"根茎入药、煲汤泡酒，林下观赏"}],"facts":["黄精的根茎肥厚、呈结节状，是著名的药食两用材料。","它的叶片轮生，先端卷曲，是辨认黄精属植物的重要特征。","黄精生长缓慢，人工栽培需多年才能采收。","野生黄精因采挖过度而减少，应优先选用栽培品。"]},"flower-chinese-astilbe":{"description":"落新妇为虎耳草科落新妇属多年生草本，株高 50–100 厘米，地下具粗壮的根状茎。叶基生，二至三回三出复叶，小叶卵形至披针形，边缘具锯齿。圆锥花序顶生，花序轴被腺毛，花小，粉红色至紫红色，花期 6–8 月；果实为蓇葖果，果期 8–9 月。\n\n落新妇原产中国长江流域及以北各地，生于林下、溪边与山谷阴湿处，朝鲜半岛、俄罗斯也有分布。它喜半阴湿润的环境，耐寒性较强，适宜疏松肥沃、排水良好的土壤。花序蓬松、花色柔和，耐阴湿，是林下与花境常见的观赏植物；根状茎可入药，有清热解毒、散瘀止痛之效。栽培以分株繁殖为主，夏季需遮阴并保持土壤湿润，花后剪去残花可促进二次开花。","habitat":"林下、溪边与山谷阴湿处，喜半阴湿润","distribution":"中国长江流域及以北各地；朝鲜半岛、俄罗斯有分布","conservation":"暂无评估；中国未列入国家重点保护野生植物名录","details":[{"label":"株高","value":"50–100 厘米，根状茎粗壮"},{"label":"花期","value":"6–8 月，粉红色圆锥花序"},{"label":"果期","value":"8–9 月，蓇葖果"},{"label":"光照","value":"喜半阴，忌强光暴晒"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的土壤"},{"label":"主要用途","value":"林下与花境观赏，根状茎入药"}],"facts":["落新妇的花序蓬松如羽毛，是花境中少见的雾状花材。","它耐阴湿，适合种在树下、溪边和建筑北侧。","落新妇的花可作切花，干花也常用于花艺设计。","根状茎入药称“红升麻”，有清热解毒、散瘀止痛之效。"]},"flower-alumroot":{"description":"矾根为虎耳草科矾根属多年生草本，株高 20–50 厘米，地下具短根状茎。叶基生，圆形至心形，边缘具浅裂，叶色有绿、黄、橙、红、紫等，叶脉明显。花葶细长，圆锥花序着生多数小花，花冠钟状，白色至粉色，花期 4–6 月；果实为蒴果。\n\n矾根原产北美西部，中国各地园林引种栽培，喜半阴湿润的环境，耐寒性较强，适宜疏松肥沃、排水良好的土壤。它叶色丰富、四季可赏，是园林中重要的观叶植物，常植于林下、花境与岩石园；与玉簪、落新妇等耐阴植物配植效果良好，是花境中的百搭材料。栽培以分株繁殖为主，夏季需遮阴、避免积水，叶色在凉爽季节最为鲜艳。","habitat":"北美西部的林下与岩石坡地，喜半阴湿润","distribution":"原产北美西部；中国各地园林引种栽培","conservation":"暂无评估；中国未列入国家重点保护野生植物名录","details":[{"label":"株高","value":"20–50 厘米，叶基生"},{"label":"叶色","value":"绿、黄、橙、红、紫等"},{"label":"花期","value":"4–6 月，花小、钟状"},{"label":"光照","value":"喜半阴，忌强光暴晒"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的土壤"},{"label":"主要用途","value":"林下观叶、花境与岩石园"}],"facts":["矾根最出名的是叶片色彩，园艺品种多达数百个。","它的花葶细长，小花像一串串小铃铛。","矾根耐寒性较强，在北方可露地越冬。","夏季高温时叶色会变淡，凉爽季节色彩最鲜艳。"]},"flower-purple-bergenia":{"description":"岩白菜为虎耳草科岩白菜属多年生草本，株高 20–40 厘米，地下具粗壮的根状茎。叶基生，倒卵形至圆形，肥厚革质，表面深绿色，冬季常转紫红色，边缘具细锯齿。花葶自叶丛抽出，聚伞花序着花数朵，花冠钟状，粉紫色至紫红色，花期 4–6 月；果实为蒴果。\n\n岩白菜原产中国西南至喜马拉雅地区，生于海拔 2000–4000 米的高山林下与岩石缝隙，耐寒、耐阴。它喜凉爽湿润、半阴的环境，适宜疏松肥沃、排水良好的土壤。叶片肥厚、冬季转红，春季开粉紫色花，是高山与林下常见的观赏植物；根状茎可入药，有清热解毒、止血之效。栽培以分株繁殖为主，夏季需遮阴，避免高温积水。","habitat":"海拔 2000–4000 米的高山林下与岩石缝隙","distribution":"中国西南至喜马拉雅地区，云南、四川、西藏等地","conservation":"暂无评估；中国未列入国家重点保护野生植物名录","details":[{"label":"株高","value":"20–40 厘米，根状茎粗壮"},{"label":"花期","value":"4–6 月，花粉紫色"},{"label":"果期","value":"花后结蒴果"},{"label":"叶色","value":"深绿色，冬季转紫红色"},{"label":"光照","value":"喜半阴，忌强光暴晒"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"主要用途","value":"高山与林下观赏，根状茎入药"}],"facts":["岩白菜的叶片肥厚革质，冬季会变成紫红色。","它原产高山地区，耐寒耐阴，适合岩石园栽培。","岩白菜的根状茎可入药，有清热解毒、止血之效。","夏季高温时需遮阴通风，否则叶片容易腐烂。"]},"flower-lanceleaf-coreopsis":{"description":"大花金鸡菊为菊科金鸡菊属多年生草本，高三十至八十厘米，茎直立，疏生短毛。叶片多基生，披针形至线状披针形，全缘或基部有裂片，茎生叶较小。头状花序单生于细长的花梗上，舌状花八枚、金黄色，先端具齿，管状花黄色，花期五至九月；瘦果扁平，具膜质翅，果期八至十月。\n\n大花金鸡菊原产北美，中国各地引种栽培，在长江流域及以南地区常逸生为野生状态。它喜光、耐旱、耐寒，对土壤要求不严，在贫瘠的砂质土中也能生长，繁殖力强。花金黄醒目、花期长，是花境、道路边坡和野花组合中的常用材料；但种子量大、易自播，在部分地区的自然保护区内被视为入侵性植物，需控制扩散。","habitat":"原产北美草原，栽培于花境、边坡，喜光耐旱","distribution":"原产北美；中国各地引种栽培，长江流域常见逸生","conservation":"暂无评估；部分地区因扩散性强被视为需管控的外来植物","details":[{"label":"株高","value":"30–80 cm，茎直立"},{"label":"花期","value":"5–9 月，舌状花金黄"},{"label":"果期","value":"8–10 月，瘦果具翅"},{"label":"光照","value":"极喜光，光照足花繁"},{"label":"水分","value":"耐旱，忌积水"},{"label":"土壤","value":"疏松砂质土，耐瘠薄"},{"label":"主要用途","value":"花境、边坡绿化与野花组合"}],"facts":["大花金鸡菊的舌状花先端有齿裂，像被剪刀剪过一样。","它自播能力极强，一次种植后常年年在原地萌发成片。","在部分自然保护区，大花金鸡菊因挤占本土植物空间而被列入管控名单。"]},"flower-grand-coreopsis":{"description":"金鸡菊为菊科金鸡菊属多年生草本，高四十至九十厘米，茎直立，分枝较多。叶片对生，羽状分裂，裂片披针形，基生叶较大。头状花序单生或数个聚生，舌状花八枚、金黄色，基部常带橙红色晕，管状花黄色，花期五至八月；瘦果扁平，具翅，果期八月至十月。\n\n金鸡菊原产美国南部，中国各地引种栽培。它喜光、耐旱、耐寒，对土壤要求不严，在疏松排水良好的砂质土中生长最佳，忌水涝。花大色艳、花期集中，是花境、道路绿化和庭院布置的常用材料；也可作切花。栽培中花后及时修剪残花，可促进二次开花并减少自播。与同属的大花金鸡菊相比，本种舌状花基部常带橙红色晕，花形更大。","habitat":"原产北美草原，栽培于花境与路旁，喜光耐旱","distribution":"原产美国南部；中国各地引种栽培","conservation":"暂无评估；栽培观赏植物，不涉及保护等级","details":[{"label":"株高","value":"40–90 cm，分枝较多"},{"label":"花期","value":"5–8 月，舌状花金黄"},{"label":"果期","value":"8–10 月，瘦果具翅"},{"label":"光照","value":"喜光，全日照最佳"},{"label":"水分","value":"耐旱，忌水涝"},{"label":"土壤","value":"疏松排水良好的砂质土"},{"label":"主要用途","value":"花境、道路绿化与切花"}],"facts":["金鸡菊的舌状花基部常有一圈橙红色晕，像金鸡羽毛上的斑纹。","它花后修剪残花可促发新枝，一年开两茬花。","金鸡菊耐旱耐寒，在北方冬季地上部分枯死，翌春仍能萌发。"]},"flower-mealycup-sage":{"description":"蓝花鼠尾草为唇形科鼠尾草属多年生草本，常作一年生或二年生栽培，高三十至八十厘米，茎直立、四棱形。叶片对生，披针形至长椭圆形，边缘有浅锯齿，表面灰绿色、被细绒毛。花组成顶生的穗状花序，花冠蓝紫色至深蓝色，唇形，花萼被白色粉状毛，花期五月至十月；小坚果椭圆形，成熟时褐色，果期秋季。\n\n蓝花鼠尾草原产墨西哥和美国南部，中国各地引种栽培。它喜光、耐旱、耐寒性一般，适宜疏松肥沃、排水良好的土壤，忌高温高湿和积水。花序细长、花色纯正，是花境、花海和道路绿化中不可多得的蓝色花材，常与黄色金鸡菊、红色一串红搭配形成强烈对比；也可作切花和干花。栽培中注意通风，避免根腐。","habitat":"原产墨西哥高原，栽培于花境花海，喜光耐旱","distribution":"原产墨西哥、美国南部；中国各地引种栽培","conservation":"暂无评估；栽培观赏植物，不涉及保护等级","details":[{"label":"株高","value":"30–80 cm，茎四棱"},{"label":"花期","value":"5–10 月，花冠蓝紫色"},{"label":"果期","value":"秋季，小坚果褐色"},{"label":"光照","value":"喜光，全日照花穗更长"},{"label":"水分","value":"耐旱，忌高温高湿"},{"label":"土壤","value":"疏松肥沃、排水良好"},{"label":"主要用途","value":"花境花海、切花与干花"}],"facts":["蓝花鼠尾草的花萼密被白色粉状毛，像撒了一层霜，因此又名粉萼鼠尾草。","它的蓝色花穗在花海中极为抢眼，常被误认为薰衣草。","蓝花鼠尾草单穗花期可达一个多月，是花境中花期最长的材料之一。"]},"flower-four-oclock":{"description":"紫茉莉为紫茉莉科紫茉莉属一年生草本，高五十至一百厘米，茎直立、多分枝，节部膨大。叶片对生，卵形至心脏形，全缘，表面深绿。花单生于叶腋或枝顶，花冠漏斗状，边缘五裂，颜色有紫红、黄、白及复色，花期六月至十月，午后开放、清晨闭合；果实球形，成熟时黑色、表面有皱纹，形似小地雷，果期八月至十一月。\n\n紫茉莉原产热带美洲，中国各地普遍栽培，常逸生于庭院、路旁和村边。它喜温暖湿润和充足阳光，也耐半阴，对土壤要求不严，自播能力强。花在傍晚开放，香气清淡，是夏秋庭院里常见的乡土花卉；种子含淀粉，但不宜食用；根和叶在民间入药，有清热解毒之效。因种子形似地雷，孩子们常称它为地雷花。","habitat":"庭院、路旁与村边，喜温暖湿润、阳光充足","distribution":"原产热带美洲；中国各地普遍栽培并常见逸生","conservation":"暂无评估；栽培与逸生植物，不涉及保护等级","details":[{"label":"株高","value":"50–100 cm，茎多分枝"},{"label":"花期","value":"6–10 月，午后开放"},{"label":"果期","value":"8–11 月，种子黑色似地雷"},{"label":"光照","value":"喜光，也耐半阴"},{"label":"水分","value":"喜湿润，耐短期干旱"},{"label":"土壤","value":"疏松壤土，适应性强"},{"label":"主要用途","value":"庭院观赏，根叶入药"}],"facts":["紫茉莉的花在下午四五点开放、清晨闭合，因此被称为晚饭花。","它的种子黑色、表面有皱纹，形状像一枚微型地雷。","同一株紫茉莉上常能开出不同颜色的花，甚至一朵花上出现复色。"]},"flower-japanese-morning-glory":{"description":"牵牛花为旋花科番薯属一年生缠绕草本，茎细长，左旋缠绕，被短柔毛。叶片互生，心形或三裂，表面被毛。花单生于叶腋，花冠漏斗状，形似喇叭，颜色有蓝、紫、红、白及复色，花期六月至十月，清晨开放、午后闭合凋谢；蒴果球形，成熟时开裂，种子黑色，果期八月至十一月。\n\n牵牛花原产热带美洲，中国各地普遍栽培，常逸生于篱笆、路旁和荒地。它喜光、喜温暖，耐旱、耐瘠薄，对土壤要求不严，自播能力强。花清晨开放、午后凋谢，因此在日本被称为朝颜；花色丰富、攀援性强，是篱笆、棚架和阳台绿化的常用藤本花卉。种子在中药中称牵牛子，有泻下逐水之效，但有毒，需遵医嘱使用。","habitat":"篱笆、路旁与荒地，喜光喜温、耐旱耐瘠薄","distribution":"原产热带美洲；中国各地普遍栽培并常见逸生","conservation":"暂无评估；栽培与逸生植物，不涉及保护等级","details":[{"label":"株高","value":"缠绕藤本，茎长可达 3 m"},{"label":"花期","value":"6–10 月，清晨开放"},{"label":"果期","value":"8–11 月，蒴果球形"},{"label":"光照","value":"喜光，全日照开花多"},{"label":"水分","value":"耐旱，忌积水"},{"label":"土壤","value":"疏松壤土，耐瘠薄"},{"label":"主要用途","value":"篱笆棚架绿化，种子入药"}],"facts":["牵牛花的花冠呈漏斗状，像一支支小喇叭，因此又名喇叭花。","它的花清晨绽放、午后凋谢，日本称之为朝颜，并培育出众多品种。","牵牛花的茎具有左旋缠绕的特性，总是逆时针攀爬支架。"]},"flower-cypress-vine":{"description":"茑萝为旋花科番薯属一年生缠绕草本，茎细长柔弱，光滑无毛。叶片互生，羽状深裂至中脉，裂片线形如丝，翠绿轻盈。花单生于叶腋，花冠高脚碟状，鲜红色，花冠筒细长，先端五裂呈五角星形，花期七月至十月；蒴果卵形，成熟时开裂，种子黑色，果期九月至十一月。\n\n茑萝原产墨西哥、南美洲北部，中国各地普遍栽培。它喜光、喜温暖，耐旱、耐瘠薄，对土壤要求不严，自播能力强。叶片细裂如羽、花形似五角星，攀援在篱笆、窗棂上轻盈秀丽，是夏秋庭院和阳台绿化的常用藤本花卉；也可作地被或盆栽造型。全草在民间入药，有清热解毒之效。茑萝生长迅速，一株可攀满数米长的篱笆。","habitat":"篱笆、窗棂与庭院，喜光喜温、耐旱耐瘠薄","distribution":"原产墨西哥与南美北部；中国各地普遍栽培","conservation":"暂无评估；栽培观赏植物，不涉及保护等级","details":[{"label":"株高","value":"缠绕藤本，茎长 2–4 m"},{"label":"花期","value":"7–10 月，花鲜红色"},{"label":"果期","value":"9–11 月，蒴果卵形"},{"label":"光照","value":"喜光，全日照开花繁"},{"label":"水分","value":"耐旱，忌积水"},{"label":"土壤","value":"疏松壤土，耐瘠薄"},{"label":"主要用途","value":"篱笆窗棂绿化、盆栽造型"}],"facts":["茑萝的花冠五裂，平展后呈标准的五角星形，因此又名五角星花。","它的叶片羽状细裂如丝，远看像一团翠绿的羽毛。","茑萝与牵牛花同属，但叶片细裂、花形星状，风格更为轻盈。"]},"flower-elatior-begonia":{"description":"丽格海棠为秋海棠科秋海棠属多年生草本，由球根海棠与野生秋海棠杂交育成，高二十至四十厘米，茎肉质多汁。叶片互生，心形至卵形，边缘有锯齿，表面深绿有光泽，质地脆嫩。花数朵生于叶腋，花重瓣或半重瓣，形似小玫瑰，颜色有红、粉、橙、黄、白等，花期十二月至翌年五月；蒴果具翅，果期夏季。\n\n丽格海棠是人工杂交类群，中国各地温室和家庭广泛栽培。它喜温暖湿润和明亮散射光，忌强光直射和高温闷热，适宜疏松透气、排水良好的微酸性基质。花重瓣、色彩丰富、花期长，是冬春季节重要的盆栽花卉和年宵花；也可用于花坛和组合盆栽。栽培中需控制浇水，避免叶面积水和根茎腐烂，并保持良好通风。","habitat":"温室与家庭盆栽，喜温暖湿润、明亮散射光","distribution":"园艺杂交类群，中国各地温室与家庭广泛栽培","conservation":"栽培类群，无野生种群；不涉及保护等级","details":[{"label":"株高","value":"20–40 cm，茎肉质"},{"label":"花期","value":"12 月至翌年 5 月"},{"label":"果期","value":"夏季，蒴果具翅"},{"label":"光照","value":"明亮散射光，忌暴晒"},{"label":"水分","value":"喜湿润，忌叶面积水"},{"label":"土壤","value":"疏松透气的微酸性基质"},{"label":"主要用途","value":"盆栽观赏、年宵花与组合盆栽"}],"facts":["丽格海棠由球根海棠与多种野生秋海棠杂交而成，兼具大花与连续开花的特性。","它的重瓣花形似小玫瑰，因此常被称为玫瑰海棠。","丽格海棠的茎叶肉质多汁，浇水过多极易烂根，养护讲究见干见湿。"]},"flower-busy-lizzie":{"description":"非洲凤仙为凤仙花科凤仙花属多年生草本，常作一年生栽培，高二十至六十厘米，茎肉质、多汁，分枝多。叶片互生，卵形至披针形，边缘有锯齿，表面深绿。花单生或数朵生于叶腋，花冠扁平开展，花瓣五枚，后方一片较大并具距，颜色有红、粉、橙、白、紫等，花期五月至十月；蒴果椭圆形，成熟时轻轻一碰即弹裂，种子褐色，果期秋季。\n\n非洲凤仙原产东非坦桑尼亚、莫桑比克一带，中国各地广泛栽培。它喜温暖湿润和半阴环境，忌强光暴晒和高温干旱，适宜疏松肥沃、排水良好的微酸性土壤，不耐寒。花大色艳、花期长，是花坛、花境、窗台和吊篮的常用材料；也可作地被。蒴果成熟后一触即裂，种子被弹射出去，因此英文称其为 Touch-me-not。","habitat":"原产东非林下，栽培喜半阴湿润、忌暴晒","distribution":"原产东非坦桑尼亚、莫桑比克；中国各地广泛栽培","conservation":"暂无评估；栽培观赏植物，不涉及保护等级","details":[{"label":"株高","value":"20–60 cm，茎肉质"},{"label":"花期","value":"5–10 月，花冠平展"},{"label":"果期","value":"秋季，蒴果触之即裂"},{"label":"光照","value":"喜半阴，忌强光暴晒"},{"label":"水分","value":"喜湿润，忌干旱积水"},{"label":"土壤","value":"疏松肥沃的微酸性土"},{"label":"主要用途","value":"花坛、窗台与吊篮盆栽"}],"facts":["非洲凤仙成熟的蒴果一碰就炸开，把种子弹向四周，英文俗称别碰我。","它的茎肉多汁、半透明，因此又有玻璃翠的别称。","非洲凤仙耐半阴，在树荫和北向窗台也能持续开花。"]},"flower-garden-verbena":{"description":"美女樱为马鞭草科马鞭草属多年生草本，常作一年生或二年生栽培，高二十至五十厘米，茎四棱、匍匐或直立，被短毛。叶片对生，长卵形，边缘有粗锯齿，表面粗糙。花组成顶生的伞房花序，花冠先端五裂，颜色有红、粉、紫、白、蓝等，花期五月至十月；小坚果长圆形，成熟时褐色，果期秋季。\n\n美女樱原产南美洲，由多个原种杂交育成，中国各地广泛栽培。它喜光、喜温暖湿润，较耐寒，适宜疏松肥沃、排水良好的土壤，忌积水。花球紧密、色彩鲜艳、花期长，是花坛、花境、道路绿化和吊篮的常用材料，也可作地被；匍匐类型可铺展成花毯。栽培中需及时摘心促分枝，并保持通风以防白粉病。","habitat":"原产南美，栽培于花坛花境，喜光喜湿、较耐寒","distribution":"原产南美洲；中国各地广泛栽培","conservation":"暂无评估；栽培观赏植物，不涉及保护等级","details":[{"label":"株高","value":"20–50 cm，茎四棱"},{"label":"花期","value":"5–10 月，花冠五裂"},{"label":"果期","value":"秋季，小坚果褐色"},{"label":"光照","value":"喜光，全日照花球更密"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好"},{"label":"主要用途","value":"花坛、花境、吊篮与地被"}],"facts":["美女樱的花聚成伞房状花球，远看像一个个彩色的小绣球。","它的茎呈四棱形，匍匐类型可铺满地面，形成彩色花毯。","美女樱品种极多，同一花球上常因花朵开放早晚而呈现深浅不同的颜色。"]},"flower-common-lantana":{"description":"马缨丹为马鞭草科马缨丹属灌木状草本或半灌木，高可达一到两米，茎四棱，被倒钩状皮刺。叶片对生，卵形，边缘有锯齿，表面粗糙、揉碎后有强烈气味。花组成头状花序，花冠管状、先端五裂，初开时黄色或橙色，后渐变为红色或紫红色，同一花序上颜色参差，花期全年；核果球形，成熟时紫黑色，果期秋冬季。\n\n马缨丹原产热带美洲，中国广东、广西、福建、海南、云南、台湾等地常见，常逸生于路旁、荒地和林缘。它喜光、耐旱、耐瘠薄，繁殖力极强，被世界自然保护联盟列为全球百大入侵物种之一。花五色斑斓、花期长，可用于庭院观赏，但全株有毒，果实误食可致中毒；在野外应控制其扩散，避免侵占本土植被。","habitat":"路旁、荒地与林缘，喜光耐旱、繁殖力极强","distribution":"原产热带美洲；中国广东、广西、福建、海南、云南、台湾等地逸生","conservation":"暂无评估；被列为全球百大入侵物种之一，野外需控制扩散","details":[{"label":"株高","value":"1–2 m，茎有倒钩刺"},{"label":"花期","value":"全年，花序颜色渐变"},{"label":"果期","value":"秋冬季，核果紫黑色"},{"label":"光照","value":"极喜光，耐全日照"},{"label":"水分","value":"耐旱，忌积水"},{"label":"土壤","value":"适应性强，耐瘠薄"},{"label":"主要用途","value":"庭院观赏，野外需控制扩散"}],"facts":["马缨丹同一花序上的花由黄变红，因开放先后不同而呈现五色，故称五色梅。","它的茎上长有倒钩状皮刺，野外穿行时容易划伤皮肤。","马缨丹被列为全球百大入侵物种，在热带地区常排挤本土植物。"]},"flower-cape-leadwort":{"description":"蓝雪花为白花丹科白花丹属常绿半灌木，高可达一到两米，枝条披散或攀援，嫩枝绿色。叶片互生，长椭圆形，全缘，表面深绿。花组成顶生的穗状或圆锥花序，花冠天蓝色，花冠筒细长，先端五裂平展，花期六月至九月；蒴果膜质，成熟时开裂，果期秋季。\n\n蓝雪花原产南非，中国南方及长江流域有栽培。它喜光、喜温暖湿润，不耐寒，适宜疏松肥沃、排水良好的微酸性土壤。花色天蓝纯正，在盛夏酷暑中格外清凉，是花境、篱笆和阳台的优良观花植物，也可作小型藤本牵引。花后修剪可促发新枝、延长花期；北方需温室越冬。蓝雪花是白花丹科中少见的真正蓝色花种类。","habitat":"原产南非，栽培于庭院与阳台，喜光喜湿、不耐寒","distribution":"原产南非；中国南方及长江流域栽培","conservation":"暂无评估；栽培观赏植物，不涉及保护等级","details":[{"label":"株高","value":"1–2 m，枝条披散"},{"label":"花期","value":"6–9 月，花冠天蓝色"},{"label":"果期","value":"秋季，蒴果膜质"},{"label":"光照","value":"喜光，全日照开花繁"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃的微酸性土"},{"label":"主要用途","value":"花境、篱笆与阳台观花"}],"facts":["蓝雪花的花冠是纯正的天蓝色，在常见花卉中十分难得。","它的花冠筒细长，五枚花瓣平展，形似小风车。","蓝雪花原产南非，在当地常攀附于岩石和灌木上生长。"]},"flower-chinese-clematis":{"description":"铁线莲为毛茛科铁线莲属藤本，茎细长、坚韧如铁线，长达数米，紫褐色。叶片对生，三出复叶或羽状复叶，小叶卵形，边缘全缘或具齿。花单生于叶腋，花大，花被片六至八枚，白色至乳白色，雄蕊多数、紫褐色，花期五月至六月；瘦果扁平，具宿存羽毛状花柱，果期秋季。\n\n铁线莲分布于中国江苏、浙江、江西、湖北、湖南、广东、广西、云南等地，日本也有，多生于低山丘陵的林缘和灌丛。它喜光也耐半阴，喜凉爽湿润，要求疏松肥沃、排水良好的碱性至中性土壤，忌积水。花大而雅、攀援性强，是篱笆、棚架和墙面的优良藤本花卉，园艺品种极多，被誉为藤本皇后。根和全草在民间入药，有祛风通络之效。","habitat":"低山丘陵林缘与灌丛，喜凉爽湿润、排水良好","distribution":"中国江苏、浙江、江西、湖北、湖南、广东、广西、云南等地；日本","conservation":"暂无评估；野生种群受采挖影响，部分产区加以保护","details":[{"label":"株高","value":"藤本，茎长可达 3 m"},{"label":"花期","value":"5–6 月，花白色至乳白"},{"label":"果期","value":"秋季，瘦果具羽状花柱"},{"label":"光照","value":"喜光，也耐半阴"},{"label":"水分","value":"喜湿润，忌积水烂根"},{"label":"土壤","value":"疏松肥沃、偏碱性壤土"},{"label":"主要用途","value":"篱笆棚架绿化，根入药"}],"facts":["铁线莲的茎细而韧，颜色紫黑如铁线，因此得名。","它的瘦果带有羽毛状的长花柱，成熟时像一团团银丝。","铁线莲园艺品种超过三千个，是世界上栽培最广泛的藤本花卉之一。"]},"flower-wax-plant":{"description":"球兰为夹竹桃科球兰属肉质藤本，茎肉质、攀援或下垂，节上生气生根。叶片对生，肉质，卵形至椭圆形，表面深绿有光泽，有时带白色斑纹。花组成腋生的伞形花序，呈球形，花冠蜡质，白色至淡粉色，花心紫红色，花期四月至六月，夜间散发甜香；蓇葖果细长，成熟时开裂，种子具毛，果期秋季。\n\n球兰原产中国华南、台湾以及东南亚、澳大利亚等地，常附生于树上或岩石上。它喜温暖湿润和半阴环境，忌强光直射，适宜疏松透气、排水良好的基质，不耐寒。花如蜡质小球、香气清甜，是室内垂吊和阳台绿化的优良植物；花序凋谢后不要剪去花梗，翌年可在同一花梗上再次开花。栽培中需控制浇水，避免烂根。","habitat":"热带亚热带林下附生，喜温暖湿润半阴","distribution":"中国华南、台湾；东南亚、澳大利亚等地","conservation":"暂无评估；未被列入国家重点保护野生植物名录","details":[{"label":"株高","value":"肉质藤本，茎长可达 2 m"},{"label":"花期","value":"4–6 月，花序球形"},{"label":"果期","value":"秋季，蓇葖果细长"},{"label":"光照","value":"喜半阴，忌强光直射"},{"label":"水分","value":"喜湿润，忌积水烂根"},{"label":"土壤","value":"疏松透气的附生基质"},{"label":"主要用途","value":"室内垂吊、阳台攀援观赏"}],"facts":["球兰的花冠蜡质光亮，像用蜡捏成的小星星，因此又名蜡兰。","它的花序在夜间香气最浓，并会分泌晶莹的花蜜。","球兰的花梗不能剪掉，因为翌年的花芽仍会从同一花梗上长出。"]},"flower-lipstick-plant":{"description":"口红花为苦苣苔科芒毛苣苔属附生藤本，茎肉质、攀援或下垂，长可达一米。叶片对生，肉质，椭圆形至披针形，表面深绿有光泽。花数朵簇生于枝顶或叶腋，花萼筒状、黑紫色并被绒毛，花冠筒状、鲜红色，先端五裂，从花萼中伸出，形似旋出的口红，花期六月至十月；蒴果细长，成熟时开裂，种子具毛，果期秋冬季。\n\n口红花原产印度尼西亚、马来西亚等东南亚热带地区，常附生于雨林树干和岩石上，中国南方有栽培。它喜温暖湿润和半阴环境，忌强光直射，适宜疏松透气、排水良好的附生基质，不耐寒。花形奇特、色彩鲜艳，是室内垂吊和阳台绿化的优良植物；也可作吊篮栽培。养护中需保持较高空气湿度，避免盆土长期积水。","habitat":"热带雨林树干与岩石附生，喜温暖湿润半阴","distribution":"原产印度尼西亚、马来西亚等地；中国南方栽培","conservation":"暂无评估；栽培观赏植物，不涉及保护等级","details":[{"label":"株高","value":"附生藤本，茎长可达 1 m"},{"label":"花期","value":"6–10 月，花冠鲜红"},{"label":"果期","value":"秋冬季，蒴果细长"},{"label":"光照","value":"喜半阴散射光"},{"label":"水分","value":"喜高湿，忌积水"},{"label":"土壤","value":"疏松透气的附生基质"},{"label":"主要用途","value":"室内垂吊、吊篮观赏"}],"facts":["口红花的黑色花萼像口红管，鲜红花冠从萼中伸出，形似旋出的口红。","它属于苦苣苔科，这一科植物多以附生和耐阴著称。","口红花在空气湿度高的环境下叶片油亮，干燥时叶缘易焦枯。"]},"flower-kanran-cymbidium":{"description":"寒兰为兰科兰属地生草本，假鳞茎狭卵形，叶四至六枚，狭带形，长三十至七十厘米，薄革质，先端渐尖，叶姿挺拔。花葶从假鳞茎基部抽出，直立，高三十至六十厘米，着花五至十二朵，花被片狭长，颜色有黄绿、紫红、白等，唇瓣具紫红色斑纹，花期十月至翌年一月，香气清冽持久；蒴果长圆形，果期翌年春季。\n\n寒兰分布于中国浙江、福建、江西、湖南、广东、广西、云南、贵州、台湾等地，日本也有，多生于海拔八百至两千米的山地林下和溪谷旁。它喜凉爽湿润和半阴环境，要求疏松透气、排水良好的腐殖质土壤，忌高温闷热和积水。花姿清雅、香气幽远，是中国传统兰花的重要种类，常作盆栽观赏；野生资源因过度采挖而减少，需加强保护。","habitat":"海拔 800–2000 米的山地林下与溪谷旁，喜凉爽湿润半阴","distribution":"中国浙江、福建、江西、湖南、广东、广西、云南、贵州、台湾；日本","conservation":"暂无 IUCN 评估；野生资源因采挖减少，多地加强保护","details":[{"label":"株高","value":"叶长 30–70 cm，花葶高挑"},{"label":"花期","value":"10 月至翌年 1 月，香气清冽"},{"label":"果期","value":"翌年春季，蒴果长圆形"},{"label":"光照","value":"喜半阴散射光，忌暴晒"},{"label":"水分","value":"喜湿润，忌积水烂根"},{"label":"土壤","value":"疏松透气的腐殖土"},{"label":"主要用途","value":"传统兰花盆栽观赏"}],"facts":["寒兰在深秋至冬季开花，是国兰中花期较晚的种类，故名寒兰。","它的花被片狭长，盛开时如展开的细带，香气清冽而不浓烈。","寒兰对栽培环境要求较高，是国兰中较难养好的种类之一。"]},"flower-lipped-cymbidium":{"description":"莲瓣兰为兰科兰属地生草本，假鳞茎卵球形，叶五至七枚，狭带形，长三十至六十厘米，边缘具细齿。花葶直立，高二十至四十厘米，着花二至五朵，花被片狭长、略扭转，形似莲花花瓣，颜色有白、粉、红、绿及复色，唇瓣宽阔并具紫红色斑块，花期一至三月，香气幽雅；蒴果长圆形，果期翌年秋季。\n\n莲瓣兰主要分布于中国云南西北部、四川西南部和贵州西部，多生于海拔一千五百至两千五百米的山地林下和溪谷旁。它喜凉爽湿润和半阴环境，要求疏松透气、富含腐殖质的土壤，忌高温和积水。花形似莲、花色丰富，是云南的传统名兰，栽培历史悠久，名品众多；野生资源因过度采挖而日渐稀少，被列入国家重点保护野生植物名录。","habitat":"海拔 1500–2500 米的山地林下与溪谷，喜凉爽湿润半阴","distribution":"中国云南西北部、四川西南部、贵州西部，以云南为主要分布中心","conservation":"列入国家重点保护野生植物名录（兰属）；野生资源因采挖减少","details":[{"label":"株高","value":"叶长 30–60 cm，花葶直立"},{"label":"花期","value":"1–3 月，花被片似莲瓣"},{"label":"果期","value":"翌年秋季，蒴果长圆形"},{"label":"光照","value":"喜半阴散射光"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"富含腐殖质的疏松土"},{"label":"主要用途","value":"传统名兰盆栽与观赏"}],"facts":["莲瓣兰的花瓣狭长微扭，形似莲花花瓣，因此得名。","云南是莲瓣兰的分布中心和栽培中心，名品如大雪素、小雪素久负盛名。","莲瓣兰在冬春之际开花，花期恰逢春节，是云南年宵花市的重要角色。"]},"flower-powder-puff":{"description":"朱缨花为豆科朱缨花属常绿灌木，高可达两至三米，树皮灰褐色，分枝开展。二回羽状复叶，小叶卵状披针形，表面深绿。花组成头状花序，花丝鲜红色、细长而密集，聚成绒球状，形似红缨，花期八月至翌年一月；荚果扁平、线形，成熟时褐色开裂，果期秋冬季。\n\n朱缨花原产玻利维亚、巴西等南美洲国家，中国广东、广西、福建、海南、云南、台湾等地有栽培。它喜高温湿润和充足阳光，不耐寒，适宜疏松肥沃、排水良好的酸性土壤。花丝鲜红、形似绒球，盛开时满树红球，是南方庭园和道路绿化的优良观花灌木；也可盆栽观赏。花后修剪可促进分枝和下次开花。","habitat":"热带亚热带庭院与绿地，喜高温湿润、阳光充足","distribution":"原产玻利维亚、巴西；中国广东、广西、福建、海南、云南、台湾栽培","conservation":"暂无评估；中国未列入国家重点保护野生植物名录","details":[{"label":"株高","value":"2–3 m，分枝开展"},{"label":"花期","value":"8 月至翌年 1 月，花丝鲜红"},{"label":"果期","value":"秋冬季，荚果扁平"},{"label":"光照","value":"喜光，全日照开花多"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃的酸性土"},{"label":"主要用途","value":"庭园观花灌木、盆栽"}],"facts":["朱缨花那团鲜红的绒球其实是由无数细长的雄蕊组成的，并非花瓣。","它的花丝基部白色、上部鲜红，远看像一个个红色绒球挂在枝头。","朱缨花原产南美，因花形喜庆，在华南常被用作节庆摆花。"]},"flower-coral-vine":{"description":"珊瑚藤为蓼科珊瑚藤属多年生藤本，茎细长、具卷须，攀援可达数米，块根纺锤形。叶片互生，心形至卵状三角形，边缘波状，表面深绿。花组成顶生或腋生的圆锥花序，花被片五枚，粉红色至玫红色，形似珊瑚，花期五月至十一月；瘦果圆锥形，成熟时褐色，果期秋冬季。\n\n珊瑚藤原产墨西哥、中美洲，中国广东、广西、福建、海南、云南、台湾等地有栽培，常逸生于路旁和灌丛。它喜高温湿润和充足阳光，不耐寒，适宜疏松肥沃、排水良好的土壤，生长迅速。花粉色、花期长，攀援在篱笆、棚架上如粉色花瀑，是热带和亚热带地区常见的观赏藤本；块根可食，但口感不佳。因繁殖力强，在部分地区被视为入侵植物。","habitat":"热带亚热带篱架与路旁，喜高温湿润、阳光充足","distribution":"原产墨西哥与中美洲；中国广东、广西、福建、海南、云南、台湾栽培并逸生","conservation":"暂无评估；在部分地区因繁殖力强被视为入侵植物","details":[{"label":"株高","value":"藤本，茎长可达 5 m"},{"label":"花期","value":"5–11 月，花被片粉红色"},{"label":"果期","value":"秋冬季，瘦果圆锥形"},{"label":"光照","value":"极喜光，全日照花更繁"},{"label":"水分","value":"喜湿润，耐短期干旱"},{"label":"土壤","value":"疏松肥沃的壤土"},{"label":"主要用途","value":"篱架棚架绿化、花瀑景观"}],"facts":["珊瑚藤的粉色花被片质地似珊瑚，成串开放时像一挂粉色珊瑚串。","它靠卷须攀援，生长迅速，一季可爬满整面篱笆。","珊瑚藤的块根富含淀粉，原产地居民曾在饥荒时煮食。"]},"flower-rangoon-creeper":{"description":"使君子为使君子科使君子属攀援灌木，茎长达数米，幼枝被短柔毛。叶片对生或近对生，椭圆形至卵形，全缘，表面深绿。花组成顶生的穗状花序，花冠管细长，花瓣五枚，初开时白色，后渐变为粉红、深红，同一花序上呈现三色，花期五月至九月，夜间香气浓郁；果实橄榄形，成熟时黑褐色，具五棱，果期秋冬季。\n\n使君子分布于中国广东、广西、福建、海南、云南、贵州、四川、台湾等地，印度、缅甸、菲律宾也有，多生于溪边、林缘和灌丛。它喜温暖湿润和充足阳光，适宜疏松肥沃、排水良好的土壤。花穗三色渐变、夜间芳香，是优良的棚架观赏植物；干燥成熟的种子为使君子，是传统中药，有杀虫消积之效，但过量服用可致呃逆。","habitat":"溪边、林缘与灌丛，喜温暖湿润、阳光充足","distribution":"中国广东、广西、福建、海南、云南、贵州、四川、台湾；印度、缅甸、菲律宾","conservation":"暂无评估；未被列入国家重点保护野生植物名录","details":[{"label":"株高","value":"攀援灌木，茎长可达 5 m"},{"label":"花期","value":"5–9 月，花色由白转红"},{"label":"果期","value":"秋冬季，果实具五棱"},{"label":"光照","value":"喜光，全日照开花繁"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃的壤土"},{"label":"主要用途","value":"棚架观赏，种子入药驱虫"}],"facts":["使君子的花初开洁白，次日转粉，再变为深红，一穗上三色并存。","它的种子是传统驱虫药，因相传由郭使君发现而得名使君子。","使君子夜间香气浓郁，常吸引夜行性蛾类前来传粉。"]},"flower-white-dipladenia":{"description":"飘香藤为夹竹桃科飘香藤属常绿藤本，茎细长、缠绕或攀援，长达数米，含白色乳汁。叶片对生，革质，椭圆形，表面深绿有光泽。花数朵组成顶生的总状花序，花冠漏斗状，粉红色至玫红色，花心颜色较深，花期五月至十月；蓇葖果细长，成熟时开裂，种子具毛，果期秋冬季。\n\n飘香藤是园艺杂交种，由原产南美的双腺藤属种类杂交育成，中国南方及长江流域有栽培。它喜高温湿润和充足阳光，不耐寒，适宜疏松肥沃、排水良好的土壤。花大色艳、开花繁密、花期长，是阳台、篱笆和棚架的优良藤本花卉，也可作盆栽造型；全株含乳汁，修剪时需避免汁液接触皮肤和眼睛。","habitat":"园艺栽培于阳台与篱架，喜高温湿润、阳光充足","distribution":"园艺杂交种，中国南方及长江流域栽培","conservation":"栽培类群，无野生种群；不涉及保护等级","details":[{"label":"株高","value":"藤本，茎长可达 3 m"},{"label":"花期","value":"5–10 月，花冠粉红色"},{"label":"果期","value":"秋冬季，蓇葖果细长"},{"label":"光照","value":"极喜光，光照足花更繁"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好"},{"label":"主要用途","value":"阳台篱架、盆栽攀援观赏"}],"facts":["飘香藤的花冠呈漏斗状，花心颜色更深，像一枚枚小喇叭。","它由双腺藤属的多个原种杂交而成，兼具大花与长花期的优点。","飘香藤全株含白色乳汁，修剪后流出的汁液对皮肤有刺激性。"]},"flower-cigar-flower":{"description":"鸟蕉为蝎尾蕉科蝎尾蕉属多年生草本，高可达一到两米，具地下根茎，丛生。叶片互生，长椭圆形至披针形，形似芭蕉叶，表面深绿有光泽。花序由数枚舟形苞片组成，苞片橙红色、先端带黄绿色，排列成蝎尾状，形似鹦鹉的喙，花期全年，以夏秋最盛；果实为浆果，成熟时蓝黑色，果期秋冬季。\n\n鸟蕉原产南美洲北部和加勒比海地区，中国广东、广西、福建、海南、云南、台湾等地有栽培。它喜高温高湿和半阴环境，忌强光暴晒和干旱，适宜疏松肥沃、排水良好的土壤，不耐寒。苞片色彩鲜艳、瓶插寿命长，是热带风格花艺中重要的切花材料；丛植于庭院水边也极具观赏性。鸟蕉的花序中含有大量花蜜，常吸引蜂鸟和太阳鸟。","habitat":"热带雨林林缘与水边，喜高温高湿、半阴","distribution":"原产南美北部与加勒比海地区；中国广东、广西、福建、海南、云南、台湾栽培","conservation":"暂无评估；栽培观赏植物，不涉及保护等级","details":[{"label":"株高","value":"1–2 m，丛生草本"},{"label":"花期","value":"全年，夏秋最盛"},{"label":"果期","value":"秋冬季，浆果蓝黑色"},{"label":"光照","value":"喜半阴，忌强光暴晒"},{"label":"水分","value":"喜高湿，忌干旱"},{"label":"土壤","value":"疏松肥沃、排水良好"},{"label":"主要用途","value":"热带切花、庭院丛植"}],"facts":["鸟蕉的橙红色苞片形似鹦鹉的喙，因此英文名意为鹦鹉之花。","我们欣赏的鲜艳部分其实是苞片，真正的花藏在苞片之间。","鸟蕉的苞片富含花蜜，在原产地常由蜂鸟和太阳鸟传粉。"]},"flower-yellow-canna":{"description":"黄花美人蕉为美人蕉科美人蕉属多年生草本，高可达一到一点五米，具粗壮根茎。叶片互生，大型，长椭圆形至披针形，形似芭蕉叶，表面绿色。花序为总状花序，花淡黄色，花瓣质薄柔软，退化雄蕊瓣化，花期六月至十月；蒴果球形，成熟时褐色开裂，种子黑色，果期秋冬季。\n\n黄花美人蕉原产美国东南部湿地，中国各地有栽培。它喜光、喜温暖湿润，耐水湿，可浅水种植，适宜肥沃的壤土或淤泥，不耐寒。花淡黄清雅、叶形优美，是水景园、湿地和庭园水边的优良观花植物；也可作花境背景材料。根茎可入药，有清热利湿之效。黄花美人蕉在南方可全年生长，北方冬季地上部分枯死，根茎需保护越冬。","habitat":"原产北美东南部湿地，栽培于水边，喜光喜湿、耐水湿","distribution":"原产美国东南部；中国各地栽培","conservation":"暂无评估；栽培观赏植物，不涉及保护等级","details":[{"label":"株高","value":"1–1.5 m，具根茎"},{"label":"花期","value":"6–10 月，花淡黄色"},{"label":"果期","value":"秋冬季，蒴果球形"},{"label":"光照","value":"喜光，全日照开花好"},{"label":"水分","value":"耐水湿，可浅水种植"},{"label":"土壤","value":"肥沃壤土或淤泥"},{"label":"主要用途","value":"水景园、湿地与花境绿化"}],"facts":["黄花美人蕉耐水湿，可以直接种在浅水中，是少见的水生观花植物。","我们看到的“花瓣”其实是瓣化的雄蕊，真正的花瓣很窄小。","它的根茎在民间入药，有清热利湿、凉血止血之效。"]},"flower-gaillardia":{"description":"宿根天人菊为菊科天人菊属多年生草本，高三十至六十厘米，茎直立，被粗毛。叶片互生，披针形至倒卵形，全缘或具浅裂，表面粗糙。头状花序单生，舌状花橙黄色、基部带紫红色，管状花紫红色，花期六月至九月；瘦果具冠毛，成熟时褐色，果期八月至十月。\n\n宿根天人菊原产北美大草原，中国北方和西北地区有引种栽培。它极喜光、耐旱、耐寒，适宜疏松排水良好的砂质土壤，忌水涝和湿热。花色彩浓烈、花期长，是花境、岩石园和道路绿化的优良宿根花卉，成片种植如彩色地毯；也可作切花。栽培中需注意排水，花后修剪可促进二次开花。与一年生天人菊相比，本种为宿根，耐寒性更强。","habitat":"原产北美草原，栽培于花境，极喜光、耐旱耐寒","distribution":"原产北美大草原；中国北方与西北地区引种栽培","conservation":"暂无评估；栽培观赏植物，不涉及保护等级","details":[{"label":"株高","value":"30–60 cm，茎被粗毛"},{"label":"花期","value":"6–9 月，舌状花橙黄"},{"label":"果期","value":"8–10 月，瘦果具冠毛"},{"label":"光照","value":"极喜光，全日照最佳"},{"label":"水分","value":"耐旱，忌水涝"},{"label":"土壤","value":"疏松砂质土，耐瘠薄"},{"label":"主要用途","value":"花境、岩石园与道路绿化"}],"facts":["宿根天人菊的舌状花基部紫红、先端金黄，像一圈燃烧的火焰。","它耐旱耐寒，在北方冬季可露地越冬，翌春重新萌发。","天人菊属的英文名意为毯花，因成片开放时像铺开的彩色毯子。"]},"flower-shasta-daisy":{"description":"大滨菊为菊科滨菊属多年生草本，高四十至九十厘米，茎直立，不分枝或稀分枝。叶片互生，披针形至倒卵形，边缘具粗齿，基生叶较大。头状花序单生，直径可达十厘米，舌状花白色、多枚，管状花金黄色，花期五月至七月；瘦果具冠毛，成熟时褐色，果期七月至九月。\n\n大滨菊原产法国比利牛斯山和西班牙北部，中国各地引种栽培。它喜光、耐寒，喜凉爽湿润，适宜疏松肥沃、排水良好的土壤，忌高温高湿和积水。花大洁白、花心金黄，清新素雅，是花境、庭院和切花的常用材料，成片种植如白色花海；也可作背景花材。花后修剪残花可延长观赏期，每两三年分株一次可保持长势。","habitat":"原产欧洲山地草甸，栽培于花境，喜凉爽、耐寒","distribution":"原产法国比利牛斯山与西班牙北部；中国各地引种栽培","conservation":"暂无评估；栽培观赏植物，不涉及保护等级","details":[{"label":"株高","value":"40–90 cm，茎直立"},{"label":"花期","value":"5–7 月，舌状花白色"},{"label":"果期","value":"7–9 月，瘦果具冠毛"},{"label":"光照","value":"喜光，全日照开花好"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好"},{"label":"主要用途","value":"花境、庭院与切花"}],"facts":["大滨菊的花序直径可达十厘米，是滨菊属中花最大的种类之一。","它的白色舌状花在清晨初开时略带粉色，午后转为纯白。","大滨菊耐寒，在北方可露地越冬，是夏季花境中的清爽白花。"]},"flower-yarrow":{"description":"蓍草为菊科蓍属多年生草本，高三十至八十厘米，茎直立，被白色柔毛。叶片互生，披针形，二至三回羽状细裂，形似千叶，表面被毛。头状花序小，密集排列成伞房状，舌状花白色、粉红或淡黄，管状花淡黄色，花期六月至九月；瘦果扁平，无冠毛，果期八月至十月。\n\n蓍草广布于北半球温带，中国东北、华北、西北及西南高山地区有分布，欧洲、北美也有，多生于草甸、路边和林缘。它喜光、耐旱、耐寒，对土壤要求不严，在贫瘠地也能生长。花小而密、花期长，是花境和野花组合的常用材料；全草含挥发油，欧洲传统医学用它止血消炎，嫩叶可作香草。蓍草在欧洲民间被视为具有保护力量的植物。","habitat":"草甸、路边与林缘，喜光耐旱、耐寒耐瘠薄","distribution":"北半球温带广布；中国东北、华北、西北及西南高山地区","conservation":"暂无评估；未被列入国家重点保护野生植物名录","details":[{"label":"株高","value":"30–80 cm，茎被柔毛"},{"label":"花期","value":"6–9 月，伞房状花序"},{"label":"果期","value":"8–10 月，瘦果扁平"},{"label":"光照","value":"喜光，全日照最佳"},{"label":"水分","value":"耐旱，忌积水"},{"label":"土壤","value":"疏松壤土，耐瘠薄"},{"label":"主要用途","value":"花境、野花组合，全草药用"}],"facts":["蓍草的叶片二至三回羽状细裂，像千片小叶，因此又名千叶蓍。","欧洲传统医学用蓍草止血消炎，古希腊士兵曾用它处理伤口。","蓍草的花序由许多小头状花聚成伞房状，盛开时像一个个小花盘。"]},"flower-lavender-cotton":{"description":"薰衣草棉为菊科绵杉菊属常绿半灌木，高三十至六十厘米，分枝密集，全株被灰白色绒毛。叶片互生，羽状细裂，裂片细小密集，呈银灰绿色，揉碎后有浓郁的樟脑样香气。头状花序球形，黄色，形似小纽扣，单生于细长花梗顶端，花期六月至八月；瘦果细小，果期秋季。\n\n薰衣草棉原产地中海沿岸的干燥山坡，中国北方和长江流域有引种栽培。它极喜光、耐旱、耐寒，适宜疏松排水良好的石灰质土壤，忌高温高湿和积水。叶色银灰、株型圆整，是地中海风格花境和岩石园的优良材料；枝叶可提取香精，也可作干花和驱虫香包。园艺中常修剪成球形，冬季保持常绿。","habitat":"原产地中海干燥山坡，栽培喜光耐旱、耐寒","distribution":"原产地中海沿岸；中国北方与长江流域引种栽培","conservation":"暂无评估；栽培观赏植物，不涉及保护等级","details":[{"label":"株高","value":"30–60 cm，分枝密集"},{"label":"花期","value":"6–8 月，头状花序黄色"},{"label":"果期","value":"秋季，瘦果细小"},{"label":"光照","value":"极喜光，全日照株型紧凑"},{"label":"水分","value":"耐旱，忌高温高湿"},{"label":"土壤","value":"疏松排水良好的石灰质土"},{"label":"主要用途","value":"花境、岩石园，枝叶提取香精"}],"facts":["薰衣草棉的叶片银灰细裂，远看像一丛柔软的灰绿色羽毛。","它的枝叶揉碎后有樟脑般的气味，地中海居民常用来驱虫。","薰衣草棉耐旱怕涝，夏季高温多雨时容易烂根，需注意排水。"]},"flower-birdwood-mucuna":{"description":"禾雀花为木质藤本，蔓长可达 10 米以上，茎粗壮、老茎常扭曲。叶为三出复叶，小叶卵形至椭圆形，长 6–12 厘米。总状花序自老茎或叶腋下垂，长 20–40 厘米，花朵白色至淡黄色，长约 4–5 厘米，花萼褐色，花瓣形态酷似收翅的小麻雀，成串悬挂；荚果长条形，长 30–50 厘米，密被褐色毛，种子扁圆。\n\n本种分布于广东、广西、江西、福建、香港等地，生于海拔 500–1000 米的山地常绿阔叶林中，喜温暖湿润、半阴的环境。它先花后叶，花期 3–4 月，盛开时成串白花如万雀栖枝，广州、江门等地每年都举办禾雀花观赏活动。禾雀花的老茎生花现象十分典型，花朵直接开在粗壮的藤茎上。其种子含左旋多巴等成分，不可食用。","habitat":"海拔 500–1000 米的山地常绿阔叶林，喜温暖湿润、半阴环境","distribution":"中国广东、广西、江西、福建、香港等地","conservation":"IUCN 暂无评估；野生种群因天然林减少而下降，各地已加强保护","details":[{"label":"蔓长","value":"可达 10 米以上，老茎粗壮扭曲"},{"label":"花期","value":"3–4 月，先花后叶，花白色"},{"label":"果期","value":"8–10 月，荚果长 30–50 厘米"},{"label":"光照","value":"喜半阴，忌强光暴晒"},{"label":"水分","value":"喜湿润，适宜年降水量 1500 mm 以上"},{"label":"土壤","value":"深厚肥沃的酸性红壤"},{"label":"主要用途","value":"棚架观赏、林下垂直绿化"}],"facts":["禾雀花的花瓣形态酷似收翅的小麻雀，成串下垂时像万鸟栖枝。","它属于“老茎生花”植物，花朵直接开在粗壮的老藤上，而不是新枝顶端。","禾雀花的花期只有两三周，华南各地常举办赏花节吸引游客。","它的种子含左旋多巴等成分，不可食用，误食可能引起不适。"]},"flower-evergreen-mucuna":{"description":"常春油麻藤为常绿木质藤本，蔓长可达 15 米，茎粗壮，老茎常扭转成绳索状。叶为三出复叶，小叶革质，卵状椭圆形，长 7–15 厘米。总状花序下垂，花冠深紫色至紫黑色，长 5–6 厘米，形似雀鸟，花萼密被毛，气味特殊；荚果长条形，长 30–60 厘米，密被锈色毛，种子扁圆。\n\n本种分布于中国南方及日本，生于山地林缘与沟谷，喜温暖湿润、半阴的环境，四季常青，是南方棚架、护坡与林下绿化的优良藤本。它花形奇特、花色深沉，花期 4–5 月，常与禾雀花搭配种植。常春油麻藤生长迅速、覆盖力强，可用于裸露坡面的生态修复；其种子含左旋多巴等有毒成分，不可食用。栽培时需设坚固棚架，并控制其攀援范围。","habitat":"山地林缘、沟谷与溪边，喜温暖湿润、半阴环境","distribution":"中国南方及日本；华南、西南各地常见栽培","conservation":"IUCN 暂无评估；分布较广，野生种群稳定","details":[{"label":"蔓长","value":"可达 15 米，老茎扭转呈绳索状"},{"label":"花期","value":"4–5 月，花深紫至紫黑色"},{"label":"果期","value":"9–11 月，荚果长 30–60 厘米"},{"label":"光照","value":"喜半阴，也耐一定直射光"},{"label":"水分","value":"喜湿润，耐短期水湿"},{"label":"土壤","value":"深厚肥沃的酸性壤土"},{"label":"主要用途","value":"棚架遮阴、护坡绿化与生态修复"}],"facts":["常春油麻藤四季常青，是少数能在南方露地越冬的木质藤本之一。","它的花深紫近黑，形似雀鸟，开花时成串下垂，颇具神秘感。","常春油麻藤的茎可长到碗口粗，攀援时能把整个棚架完全覆盖。","它的种子含左旋多巴类物质，不可食用，只能用于药用提取。"]},"flower-pellucid-grape":{"description":"锦屏藤为常绿藤本，蔓长可达 5–10 米，茎绿色或带红色，节间较长。叶片心形至卵形，长 6–12 厘米，边缘具锯齿，卷须与叶对生。茎节上能长出大量细长的气生根，初为红色，后转淡黄或灰白，长可达 1–3 米，成排下垂如珠帘；花小、淡绿色，聚伞花序，果实为浆果。\n\n本种原产热带美洲，喜高温高湿、阳光充足的环境，在中国华南常作廊架、墙垣与庭院垂吊植物。它最引人注目的是从茎节垂下的红色气生根，微风吹拂时如红色珠帘轻摇，因此有“一帘幽梦”的雅称。锦屏藤不耐寒，北方需温室栽培；气生根在干燥环境中会变短，需保持较高空气湿度。其生长迅速，需定期修剪过密枝条。","habitat":"热带美洲的雨林边缘，喜高温高湿、阳光充足","distribution":"原产热带美洲；中国华南、云南南部及世界热带地区栽培","conservation":"IUCN 暂无评估；栽培广泛，野生种群未受明显威胁","details":[{"label":"蔓长","value":"5–10 米，茎节可生红色气生根"},{"label":"气生根","value":"长 1–3 米，成排下垂如珠帘"},{"label":"花期","value":"夏季，花小、淡绿色"},{"label":"光照","value":"喜光，也耐半阴"},{"label":"水分","value":"喜高湿，气生根需经常喷雾"},{"label":"土壤","value":"疏松肥沃、排水良好的壤土"},{"label":"主要用途","value":"廊架垂吊、墙垣绿化与庭院造景"}],"facts":["锦屏藤垂下的“珠帘”其实是茎节上长出的气生根，不是花也不是果。","气生根初生时呈鲜红色，随后逐渐变为淡黄或灰白色。","它原产热带美洲，因造型奇特被称为“一帘幽梦”，在华南庭园中很受欢迎。","锦屏藤的气生根能吸收空气中的水分，但主要功能仍是攀附与辅助呼吸。"]},"flower-blue-passionflower":{"description":"西番莲为常绿草质藤本，蔓长 5–10 米，茎细长，具卷须。叶片掌状 5 深裂，长 6–12 厘米，裂片披针形，边缘全缘。花单生叶腋，直径 8–10 厘米，花被片白色，副花冠由蓝紫色与白色丝状体组成，呈放射状排列，中央为雌雄蕊柱，整体形似钟表盘面；果实卵球形，成熟时橙黄色，果肉可食。\n\n本种原产巴西、阿根廷等南美地区，喜温暖、阳光充足的环境，在中国华南、西南常作篱垣与棚架植物。它的花结构奇特，副花冠如时针刻度，因此英文称“钟表花”（clock flower）；花靠大型蜂类传粉。西番莲的果实橙黄、汁多微酸，可鲜食或制果汁；全草在民间入药，有安神之效。它不耐寒，北方需盆栽，冬季移入室内。","habitat":"南美亚热带林缘，喜温暖、阳光充足，不耐寒","distribution":"原产巴西、阿根廷；中国华南、西南及世界温暖地区栽培","conservation":"IUCN 暂无评估；栽培广泛，部分地区归化","details":[{"label":"蔓长","value":"5–10 米，具卷须攀援"},{"label":"花期","value":"5–9 月，花蓝白相间"},{"label":"果期","value":"8–11 月，果实橙黄色"},{"label":"光照","value":"喜光，每天需充足直射光"},{"label":"水分","value":"喜湿润，生长期需充足浇水"},{"label":"土壤","value":"疏松肥沃、排水良好的壤土"},{"label":"主要用途","value":"棚架观赏、篱垣绿化与果用"}],"facts":["西番莲的花副花冠呈放射状蓝白条纹，整体像一块钟表盘，因此被称为“时计草”。","它的花需要大型蜂类从特定角度进入才能完成传粉，结构十分精巧。","西番莲的果实橙黄、多汁，是百香果的近亲，可直接食用或制汁。","它原产南美，17 世纪传入欧洲后成为温室中的奇花。"]},"flower-garlic-vine":{"description":"蒜香藤为常绿藤本，蔓长 3–5 米，茎细长，具卷须。叶对生，为二出复叶，顶生一枚卷须，小叶椭圆形，长 5–10 厘米，揉碎后有明显的蒜香味。聚伞花序腋生或顶生，花冠漏斗状，紫红色至淡紫色，长 5–6 厘米，花冠檐部 5 裂，花初开时色深，后渐淡；蒴果长条形，成熟时开裂，种子具翅。\n\n本种原产南美北部与亚马孙地区，喜温暖湿润、阳光充足的环境，在中国华南常作篱垣、棚架与坡面绿化。它的叶片与花都有蒜味，当地民间有用其叶调味或驱虫的习俗；花期长、花量大，盛开时如紫色瀑布。蒜香藤不耐寒，北方需盆栽温室越冬；生长迅速，需定期修剪与施肥。其花蜜丰富，能吸引蜂类与蝴蝶。","habitat":"南美北部热带林缘，喜温暖湿润、阳光充足","distribution":"原产南美北部与亚马孙地区；中国华南及世界热带地区栽培","conservation":"IUCN 暂无评估；栽培广泛，野生种群未受明显威胁","details":[{"label":"蔓长","value":"3–5 米，具卷须攀援"},{"label":"花期","value":"5–10 月，花紫红至淡紫色"},{"label":"叶","value":"二出复叶，揉碎有明显蒜味"},{"label":"光照","value":"喜光，每天需充足直射光"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"肥沃、排水良好的壤土"},{"label":"主要用途","value":"篱垣、棚架与坡面绿化"}],"facts":["蒜香藤的叶片揉碎后有浓烈蒜味，因此得名，但其花并没有蒜味。","它的花初开深紫，随后逐渐变淡，整株花期可长达半年。","蒜香藤原产南美，当地民间用其叶作为香料与驱虫材料。","它的卷须能牢牢缠住支架，是南方篱垣绿化的优良材料。"]},"flower-dwarf-allamanda":{"description":"黄蝉为常绿灌木，高 1–2 米，茎直立、多分枝，含白色乳汁。叶片轮生或对生，椭圆形至倒卵形，长 6–12 厘米，上面深绿色有光泽。花单生或数朵聚生叶腋，花冠漏斗状，金黄色，长 5–7 厘米，花冠檐部 5 裂，喉部有橙红色条纹；蒴果球形，表面具刺，成熟时开裂。\n\n本种原产巴西，喜温暖湿润、阳光充足的环境，在中国华南常作庭园、花境与绿篱植物。它花大色艳、花期长，是热带城市中最常见的黄花灌木之一。黄蝉属于夹竹桃科，全株含黄色夹竹桃苷等强心苷类毒素，乳汁接触皮肤可致红肿，误食可引起呕吐、心律失常甚至死亡，栽培与修剪时需戴手套，并避免儿童与宠物接触。","habitat":"巴西热带林缘，喜温暖湿润、阳光充足","distribution":"原产巴西；中国华南、西南及世界热带地区栽培","conservation":"IUCN 暂无评估；栽培广泛，野生种群未受明显威胁","details":[{"label":"株高","value":"1–2 米，茎直立、含白色乳汁"},{"label":"花期","value":"5–10 月，花金黄色"},{"label":"果期","value":"秋季，蒴果球形具刺"},{"label":"光照","value":"喜光，每天需充足直射光"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"肥沃、排水良好的沙质壤土"},{"label":"毒性","value":"全株含强心苷，误食可致命"}],"facts":["黄蝉的花冠金黄色、喉部带橙红条纹，开放时像一只金色的小喇叭。","它属于夹竹桃科，与夹竹桃一样全株含强心苷，乳汁有毒。","黄蝉的果实表面长满软刺，成熟开裂后散出带翅种子。","修剪黄蝉时流出的白色乳汁会刺激皮肤，最好戴手套操作。"]},"flower-queens-wreath":{"description":"蓝花藤为常绿藤本，蔓长 5–10 米，茎木质化，表面粗糙。叶片对生，椭圆形至倒卵形，长 8–15 厘米，表面粗糙如砂纸，边缘全缘。总状花序腋生或顶生，长可达 30 厘米，花冠蓝紫色，5 裂，花萼亦呈蓝紫色并宿存，花后萼片仍保留观赏价值；果实为核果，包裹在宿存花萼中。\n\n本种原产墨西哥、中美洲至委内瑞拉一带，喜温暖、阳光充足的环境，在中国华南常作棚架、墙垣与拱门绿化。它盛开时满架蓝紫，花萼比花冠更持久，远看像紫色的瀑布，因此英文称“女王的花环”。蓝花藤不耐寒，北方需盆栽温室越冬；生长迅速，需设坚固支架并定期修剪。其花蜜丰富，能吸引蜂类与蝴蝶。","habitat":"中美洲热带林缘，喜温暖、阳光充足","distribution":"原产墨西哥、中美洲至委内瑞拉；中国华南及世界热带地区栽培","conservation":"IUCN 暂无评估；栽培广泛，野生种群未受明显威胁","details":[{"label":"蔓长","value":"5–10 米，茎木质化"},{"label":"花期","value":"4–6 月，花蓝紫色"},{"label":"花萼","value":"蓝紫色、宿存，花后仍可观赏"},{"label":"光照","value":"喜光，每天需充足直射光"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"肥沃、排水良好的壤土"},{"label":"主要用途","value":"棚架、墙垣与拱门绿化"}],"facts":["蓝花藤最醒目的蓝紫色部分其实是宿存的花萼，花冠凋落后萼片仍能保持很久。","它的叶片表面粗糙如砂纸，因此英文名又叫 Sandpaper Vine。","蓝花藤盛开时像紫色的瀑布，被称为“女王的花环”。","它原产中美洲，19 世纪传入欧洲后成为温室中的观赏藤本。"]},"flower-shrimp-plant":{"description":"虾衣花为常绿灌木，高 1–1.5 米，茎细长、多分枝，基部常木质化。叶片卵形至椭圆状卵形，长 4–8 厘米，全缘，对生。穗状花序顶生或腋生，长 10–15 厘米，苞片红褐色、叠瓦状排列，形似虾壳；花冠白色，具红色斑点，二唇形，从苞片中伸出，整串花序微微下弯，酷似一只煮熟的虾。\n\n本种原产墨西哥与危地马拉，喜温暖湿润、阳光充足的环境，在中国华南、西南常作盆栽或庭园花灌木。它的“虾衣”其实是红褐色的苞片，真正的花是白色的二唇形小花，花期可从春末持续到秋季。虾衣花不耐寒，北方需盆栽温室越冬；生长迅速，需定期摘心促分枝。其花形奇特，是科普与摄影爱好者的宠儿。","habitat":"墨西哥、危地马拉的热带灌丛，喜温暖湿润、阳光充足","distribution":"原产墨西哥、危地马拉；中国华南、西南及世界温暖地区栽培","conservation":"IUCN 暂无评估；栽培广泛，野生种群未受明显威胁","details":[{"label":"株高","value":"1–1.5 米，茎细长多分枝"},{"label":"花期","value":"5–10 月，苞片红褐色"},{"label":"花序","value":"长 10–15 厘米，形似下弯的虾"},{"label":"光照","value":"喜光，夏季适当遮阴"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"疏松肥沃的微酸性壤土"},{"label":"主要用途","value":"盆栽、花境与庭园观赏"}],"facts":["虾衣花红褐色的“虾壳”其实是苞片，白色的小花才是真正的花。","它的花序自然下弯，加上层层叠叠的苞片，远看像一只煮熟的虾。","虾衣花原产墨西哥，20 世纪初传入欧洲后成为温室观赏植物。","它属于爵床科，与珊瑚花、金苞花是近亲，花的结构相似。"]},"flower-brazilian-plume":{"description":"珊瑚花为常绿灌木，高 1–2 米，茎粗壮、多分枝。叶片大，卵形至长椭圆形，长 15–30 厘米，上面深绿色，叶脉下陷。穗状花序顶生，长 15–25 厘米，苞片粉红色、层层重叠，花冠紫红色，二唇形，长 4–5 厘米，从苞片中伸出，整串花序像一株粉红色的珊瑚。\n\n本种原产巴西，喜温暖湿润、半阴的环境，在中国华南、西南常作庭园花灌木或盆栽。它花序硕大、色彩浓艳，花期长，是热带花园中常见的背景植物。珊瑚花不耐寒，北方需温室越冬；夏季忌强光暴晒，否则叶片容易灼伤。其花蜜丰富，能吸引蜂类与蝴蝶。珊瑚花与虾衣花同属，但花序更粗大、花色更偏紫红。","habitat":"巴西热带林缘，喜温暖湿润、半阴环境","distribution":"原产巴西；中国华南、西南及世界热带地区栽培","conservation":"IUCN 暂无评估；栽培广泛，野生种群未受明显威胁","details":[{"label":"株高","value":"1–2 米，茎粗壮多分枝"},{"label":"花期","value":"5–10 月，花冠紫红色"},{"label":"花序","value":"长 15–25 厘米，苞片粉红色"},{"label":"光照","value":"喜半阴，忌夏季强光暴晒"},{"label":"水分","value":"喜湿润，需较高空气湿度"},{"label":"土壤","value":"疏松肥沃、排水良好的壤土"},{"label":"主要用途","value":"庭园花境、盆栽与切花"}],"facts":["珊瑚花的花序由粉红色苞片与紫红色花冠组成，远看像一株海底珊瑚。","它原产巴西，是爵床科中花序最大的观赏种类之一。","珊瑚花喜欢半阴环境，夏季强光会把叶片晒出焦边。","它的花期很长，在温暖地区可从春末一直开到秋末。"]},"flower-lollipop-plant":{"description":"金苞花为常绿灌木，高 1–2 米，茎直立、多分枝。叶片卵形至披针形，长 8–15 厘米，对生，上面深绿色。穗状花序顶生，长 10–15 厘米，苞片金黄色、叠瓦状排列，四棱形，像一座金色的塔；花冠白色，二唇形，长 5 厘米，从苞片中伸出，花谢后苞片仍可观赏数周。\n\n本种原产秘鲁，喜温暖湿润、阳光充足的环境，在中国华南、西南常作庭园花灌木与盆栽。它金黄色的苞片层层叠叠，白色花冠从中伸出，形似一根金色的麦穗，花期长、观赏价值高。金苞花不耐寒，北方需温室越冬；生长期需充足光照与水分，否则苞片颜色变淡。其花蜜丰富，能吸引蜂类与蝴蝶。","habitat":"秘鲁热带林缘，喜温暖湿润、阳光充足","distribution":"原产秘鲁；中国华南、西南及世界热带地区栽培","conservation":"IUCN 暂无评估；栽培广泛，野生种群未受明显威胁","details":[{"label":"株高","value":"1–2 米，茎直立多分枝"},{"label":"花期","value":"5–10 月，苞片金黄色"},{"label":"花序","value":"长 10–15 厘米，四棱形金穗"},{"label":"光照","value":"喜光，每天需充足直射光"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"肥沃、排水良好的壤土"},{"label":"主要用途","value":"庭园花境、盆栽与切花"}],"facts":["金苞花金黄色的是苞片，白色二唇形的小花才是真正的花。","它的花序呈四棱形，层层叠叠像一座金色的小塔。","金苞花原产秘鲁，是热带庭园中花期最长的灌木之一。","花谢后金黄色苞片仍能保持数周，因此观赏期比一般花卉长得多。"]},"flower-hanging-heliconia":{"description":"艳红赫蕉为多年生丛生草本，高 2–4 米，具粗壮的根状茎，假茎由叶鞘层层包裹而成。叶片大，长椭圆形至披针形，长 1–2 米，形似芭蕉叶。花序下垂，长 60–100 厘米，苞片鲜红色、先端带黄绿色，二列排列，形似倒挂的鸟喙；真正的花小，黄绿色，藏于苞片内。\n\n本种原产哥斯达黎加至玻利维亚的热带雨林，喜高温高湿、半阴的环境，在中国华南、云南南部常作庭园观花植物。它花序倒垂、红黄相间，是热带雨林中最醒目的植物之一，也是蜂鸟的重要蜜源。艳红赫蕉不耐寒，北方需温室栽培；需充足水分与肥沃土壤，才能抽出大型花序。其花期长，切花插瓶可保持数周。","habitat":"热带雨林林下与溪边，喜高温高湿、半阴环境","distribution":"原产哥斯达黎加至玻利维亚；中国华南、云南南部引种栽培","conservation":"IUCN 暂无评估；野生种群受雨林砍伐影响，栽培较广","details":[{"label":"株高","value":"2–4 米，丛生，假茎粗壮"},{"label":"花期","value":"5–10 月，花序下垂"},{"label":"花序","value":"长 60–100 厘米，苞片鲜红带黄尖"},{"label":"光照","value":"喜半阴，忌强光暴晒"},{"label":"水分","value":"喜高湿，需充足浇水与喷雾"},{"label":"土壤","value":"深厚肥沃、排水良好的壤土"},{"label":"主要用途","value":"庭园观赏、切花与热带景观"}],"facts":["艳红赫蕉的花序倒挂生长，红色苞片像一串倒悬的鸟喙。","它的苞片鲜红、先端带黄绿色，是热带雨林中最醒目的色彩之一。","赫蕉属植物靠蜂鸟传粉，花序结构正好适应蜂鸟的取蜜姿势。","艳红赫蕉的切花插瓶可保持数周，是高档花艺的常用材料。"]},"flower-yellow-heliconia":{"description":"黄鸟蕉为多年生丛生草本，高 2–4 米，具粗壮根状茎，假茎由叶鞘包裹。叶片大，长披针形，长 1–2 米，形似芭蕉叶。花序直立，长 30–60 厘米，苞片橙黄色至金黄色，二列排列，形似鸟喙；真正的花小，黄绿色，藏于苞片内。\n\n本种原产墨西哥至哥伦比亚的中美洲热带地区，喜高温高湿、阳光充足的环境，在中国华南、云南南部常作庭园观花植物。它花序直立、色彩明亮，与倒挂的艳红赫蕉形成鲜明对比，是热带景观中的常见配景植物。黄鸟蕉不耐寒，北方需温室栽培；需充足水分与肥沃土壤。其花蜜丰富，能吸引蜂鸟与大型蜂类。在华南，它常与红色赫蕉搭配，形成强烈的色彩对比。","habitat":"中美洲热带雨林边缘与溪边，喜高温高湿、阳光充足","distribution":"原产墨西哥至哥伦比亚；中国华南、云南南部引种栽培","conservation":"IUCN 暂无评估；野生种群受雨林砍伐影响，栽培较广","details":[{"label":"株高","value":"2–4 米，丛生，假茎粗壮"},{"label":"花期","value":"5–10 月，花序直立"},{"label":"花序","value":"长 30–60 厘米，苞片橙黄色"},{"label":"光照","value":"喜光，也耐半阴"},{"label":"水分","value":"喜高湿，需充足浇水"},{"label":"土壤","value":"深厚肥沃、排水良好的壤土"},{"label":"主要用途","value":"庭园观赏、切花与热带景观"}],"facts":["黄鸟蕉的花序直立向上，与倒挂的艳红赫蕉正好相反。","它的苞片橙黄至金黄，在阳光下像一串发亮的小鸟喙。","黄鸟蕉原产中美洲，是热带雨林中蜂鸟的重要蜜源。","它的叶片宽大似芭蕉，常被误认为芭蕉科植物，其实属于赫蕉科。"]},"flower-siam-tulip":{"description":"姜荷花为多年生草本，高 30–80 厘米，具肉质根状茎。叶片长椭圆形至披针形，长 20–40 厘米，具平行脉，叶面深绿色。穗状花序顶生，长 20–30 厘米，上部苞片粉红色、形似莲花瓣，下部苞片绿色、内含真正的花；花小，紫色，藏于绿色苞片内。\n\n本种原产泰国、老挝、柬埔寨等地，喜温暖湿润、阳光充足的环境，在中国华南、云南南部常作切花与庭园栽培。它因花序形似荷花而得名“姜荷花”，其实与荷花没有亲缘关系，而是姜科植物。姜荷花花期长、瓶插寿命久，是近年来流行的新兴切花；其根状茎可提取芳香油。它不耐寒，北方需盆栽温室越冬，冬季地上部分枯萎后以根茎休眠。","habitat":"东南亚热带季风林缘，喜温暖湿润、阳光充足","distribution":"原产泰国、老挝、柬埔寨；中国华南、云南南部引种栽培","conservation":"IUCN 暂无评估；野生种群受栖息地开垦影响，栽培广泛","details":[{"label":"株高","value":"30–80 厘米，具肉质根状茎"},{"label":"花期","value":"6–10 月，上部苞片粉红色"},{"label":"花序","value":"长 20–30 厘米，形似荷花"},{"label":"光照","value":"喜光，每天需充足直射光"},{"label":"水分","value":"喜湿润，生长期需充足浇水"},{"label":"土壤","value":"疏松肥沃、排水良好的沙质壤土"},{"label":"主要用途","value":"切花、盆栽与庭园观赏"}],"facts":["姜荷花粉红色的“花瓣”其实是苞片，真正的花是藏在绿色苞片里的紫色小花。","它名字里有“荷花”，却与荷花没有亲缘关系，而是姜科植物。","姜荷花原产泰国，是近年来国际切花市场的新兴明星。","它的根状茎可提取芳香油，与姜黄、郁金是近亲。"]},"flower-chinese-dwarf-banana":{"description":"地涌金莲为多年生丛生草本，高 0.6–1.5 米，具粗壮的根状茎，假茎由叶鞘层层包裹。叶片大，长椭圆形，长 0.5–1 米，形似芭蕉叶。花序生于假茎基部、贴近地面，苞片金黄色、层层展开如莲花，长 20–30 厘米，真正的花小、黄绿色，藏于苞片内；果实为浆果。\n\n本种为中国特有种，分布于云南西北部与四川西南部的金沙江、澜沧江流域，生于海拔 1500–2500 米的干热河谷与山坡，喜阳光充足、排水良好的环境。它是云南少数民族传统的“五树六花”之一，傣族佛教寺院常种植，寓意吉祥。地涌金莲花期长达半年，金黄色花序从地面涌出，十分奇特；其假茎与花可入药，有止血之效。野生种群因生境破坏而减少，已受到保护。","habitat":"海拔 1500–2500 米的干热河谷与山坡，喜阳光充足、排水良好","distribution":"中国云南西北部与四川西南部，为中国特有种","conservation":"IUCN 暂无评估；中国特有种，野生种群因生境破坏而减少","details":[{"label":"株高","value":"0.6–1.5 米，假茎粗壮"},{"label":"花期","value":"3–10 月，花序金黄色"},{"label":"花序","value":"贴地而生，长 20–30 厘米，形似莲座"},{"label":"光照","value":"喜光，每天需充足直射光"},{"label":"水分","value":"耐旱，忌积水"},{"label":"土壤","value":"疏松肥沃、排水良好的沙质壤土"},{"label":"主要用途","value":"庭院观赏、佛教供花与药用"}],"facts":["地涌金莲的花序从地面直接涌出，像一朵金色的莲花从地下升起，因此得名。","它是云南傣族佛教“五树六花”之一，常种在寺庙与村寨中。","地涌金莲的花期可长达半年，是花期最长的草本花卉之一。","它的假茎与花在民间入药，有收敛止血的作用。"]},"flower-torch-ginger":{"description":"瓷玫瑰为多年生丛生草本，高 2–4 米，具粗壮根状茎，假茎由叶鞘包裹。叶片大，长披针形，长 1–1.5 米，两面光滑。花序生于根状茎上、贴近地面，头状，直径 15–20 厘米，苞片粉红色至深红色，表面具蜡质光泽，层层叠叠如瓷质玫瑰；真正的花小，黄色，藏于苞片间。\n\n本种原产印度尼西亚、马来西亚等东南亚热带地区，喜高温高湿、半阴的环境，在中国华南、云南南部常作庭园观花与切花栽培。它花序硕大、苞片具蜡质光泽，像一朵用瓷器雕成的玫瑰，因此得名“瓷玫瑰”；又因形似火炬，也称“火炬姜”。瓷玫瑰不耐寒，北方需温室栽培；花期长，切花插瓶可保持两周以上，是高档花艺的常用材料。","habitat":"东南亚热带雨林林下与溪边，喜高温高湿、半阴环境","distribution":"原产印度尼西亚、马来西亚；中国华南、云南南部引种栽培","conservation":"IUCN 暂无评估；野生种群受雨林砍伐影响，栽培较广","details":[{"label":"株高","value":"2–4 米，丛生，假茎粗壮"},{"label":"花期","value":"5–10 月，花序粉红至深红"},{"label":"花序","value":"直径 15–20 厘米，蜡质如瓷"},{"label":"光照","value":"喜半阴，忌强光暴晒"},{"label":"水分","value":"喜高湿，需充足浇水与喷雾"},{"label":"土壤","value":"深厚肥沃、排水良好的壤土"},{"label":"主要用途","value":"高档切花、庭园观赏与热带景观"}],"facts":["瓷玫瑰的苞片表面有蜡质光泽，摸上去像瓷器一样光滑，因此得名。","它原产东南亚，是姜科中花序最华丽的种类之一。","瓷玫瑰的花序贴地而生，从根状茎上直接抽出，而不是长在枝顶。","它的切花插瓶可保持两周以上，是婚礼与高端花艺的常用花材。"]},"flower-bird-of-paradise":{"description":"鹤望兰为多年生丛生草本，高 1–2 米，具粗壮肉质根，无地上假茎。叶片基生，长椭圆状披针形，长 30–50 厘米，具长叶柄，形似芭蕉叶。花生于花茎顶端，总苞片舟形，绿色带紫红，花冠由橙黄色萼片与蓝色花瓣组成，整体形似一只昂首的仙鹤，长 10–15 厘米；蒴果三棱形，种子黑色。\n\n本种原产南非开普地区，喜温暖湿润、阳光充足的环境，在中国华南、西南常作庭园观花与切花栽培。它花形奇特、色彩艳丽，是世界上最著名的切花之一，象征自由、幸福与爱情；因花似天堂鸟，英文称 Bird of Paradise。鹤望兰不耐寒，北方需温室栽培；生长缓慢，需充足光照与排水良好的土壤。其花蜜丰富，在原产地由太阳鸟传粉。","habitat":"南非开普地区灌木丛，喜温暖湿润、阳光充足","distribution":"原产南非；中国华南、西南及世界温暖地区栽培","conservation":"IUCN 暂无评估；栽培广泛，野生种群未受明显威胁","details":[{"label":"株高","value":"1–2 米，丛生，具肉质根"},{"label":"花期","value":"全年，盛花期 5–10 月"},{"label":"花形","value":"橙黄萼片配蓝色花瓣，形似仙鹤"},{"label":"光照","value":"喜光，每天需充足直射光"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"深厚肥沃、排水良好的沙质壤土"},{"label":"主要用途","value":"切花、庭园观赏与热带景观"}],"facts":["鹤望兰的花由橙色萼片与蓝色花瓣组成，整体像一只昂首远望的仙鹤。","它是南非的国花之一，英文名 Bird of Paradise 意为“天堂鸟”。","鹤望兰是世界上最著名的切花之一，瓶插寿命可达两周。","它的花蜜在原产地由太阳鸟传播，花的结构与鸟喙高度契合。"]},"flower-giant-bird-of-paradise":{"description":"大鹤望兰为多年生常绿草本，高 4–8 米，具粗壮根状茎，假茎由叶鞘层层包裹，形似小树。叶片大，长 1–2 米，长椭圆形，近似芭蕉叶，簇生于茎顶。花序从叶腋抽出，总苞片舟形，花冠由白色萼片与蓝色花瓣组成，长 20 厘米，形似巨鹤；蒴果三棱形，种子黑色。\n\n本种原产南非东部沿海，喜温暖湿润、阳光充足的环境，在中国华南常作庭园观花与行道景观。它植株高大、花形雄伟，是鹤望兰属中体型最大的种类，常被误认为香蕉树。大鹤望兰不耐寒，北方需温室栽培；生长迅速，需充足光照与肥沃土壤。其花蜜丰富，在原产地由太阳鸟传粉；叶片可作饲料，也可用于编织。","habitat":"南非东部沿海亚热带林缘，喜温暖湿润、阳光充足","distribution":"原产南非东部；中国华南及世界热带地区栽培","conservation":"IUCN 暂无评估；栽培广泛，野生种群未受明显威胁","details":[{"label":"株高","value":"4–8 米，假茎粗壮似小树"},{"label":"花期","value":"全年，盛花期 5–10 月"},{"label":"花形","value":"白色萼片配蓝色花瓣，形似巨鹤"},{"label":"光照","value":"喜光，每天需充足直射光"},{"label":"水分","value":"喜湿润，忌积水"},{"label":"土壤","value":"深厚肥沃、排水良好的壤土"},{"label":"主要用途","value":"庭园观赏、行道景观与切花"}],"facts":["大鹤望兰能长到 8 米高，远看像一棵小香蕉树，其实它是草本植物。","它的花白色萼片配蓝色花瓣，比鹤望兰更大、更显雄伟。","大鹤望兰原产南非东部沿海，常成片生长在海边的灌丛中。","它的叶片宽大坚韧，当地居民曾用来编织篮子和遮阳。"]},"flower-red-ginger":{"description":"红球姜为多年生草本，高 1–2 米，具肉质根状茎，假茎由叶鞘包裹。叶片披针形，长 20–40 厘米，螺旋状排列。花序自根状茎抽出，呈松果状或圆锥形，长 10–15 厘米，苞片鲜红色、覆瓦状排列，花小、淡黄色，藏于苞片内；花后苞片由红转绿，仍可观赏。\n\n本种原产热带亚洲，分布于中国华南、云南及东南亚、印度等地，生于林下与溪边，喜温暖湿润、半阴的环境。它花序形似松果、苞片鲜红，是热带庭园中独特的观花植物；根状茎芳香，含有姜烯等成分，在民间用于洗发、驱虫与药用，英文称 Shampoo Ginger。红球姜不耐寒，北方需温室栽培；其花后苞片可保持数月，是优良的观花观果材料。","habitat":"热带亚洲的林下与溪边，喜温暖湿润、半阴环境","distribution":"中国华南、云南及东南亚、印度等地","conservation":"IUCN 暂无评估；分布较广，野生种群稳定","details":[{"label":"株高","value":"1–2 米，假茎由叶鞘包裹"},{"label":"花期","value":"7–10 月，苞片鲜红色"},{"label":"花序","value":"松果状，长 10–15 厘米"},{"label":"光照","value":"喜半阴，忌强光暴晒"},{"label":"水分","value":"喜湿润，需充足浇水"},{"label":"土壤","value":"疏松肥沃、排水良好的壤土"},{"label":"主要用途","value":"庭园观赏、根茎药用与洗发"}],"facts":["红球姜的花序像一颗红色的松果，花后苞片由红转绿，还能继续观赏。","它的根状茎富含芳香油，东南亚民间用其汁液洗发，因此英文名 Shampoo Ginger。","红球姜的红色部分同样是苞片，真正的花是藏在里面的淡黄色小花。","它原产热带亚洲，在中国华南的溪边林下常能见到野生植株。"]},"flower-crepe-ginger":{"description":"闭鞘姜为多年生草本，高 1–2 米，具块状根状茎，茎粗壮，叶鞘闭合包裹茎干，这是它得名的原因。叶片螺旋状排列，长椭圆形至披针形，长 15–30 厘米，上面深绿色，下面被短柔毛。穗状花序顶生，呈圆锥状或宝塔状，长 10–20 厘米，苞片红色，花冠白色，唇瓣橙黄色、边缘皱波状，十分醒目。\n\n本种原产热带亚洲，分布于中国华南、云南及东南亚、印度等地，生于林下、溪边与灌丛，喜温暖湿润、半阴的环境。它花序形似宝塔、白花黄唇，是南方庭园与药园常见的植物；根状茎入药，有清热解毒、利水消肿之效。闭鞘姜不耐寒，北方需温室栽培；其茎鞘闭合、叶片螺旋排列，是识别本种的重要特征。","habitat":"热带亚洲的林下、溪边与灌丛，喜温暖湿润、半阴环境","distribution":"中国华南、云南及东南亚、印度等地","conservation":"IUCN 暂无评估；分布较广，野生种群稳定","details":[{"label":"株高","value":"1–2 米，茎粗壮，叶鞘闭合"},{"label":"花期","value":"7–10 月，花冠白色、唇瓣橙黄"},{"label":"花序","value":"顶生，宝塔状，长 10–20 厘米"},{"label":"光照","value":"喜半阴，忌强光暴晒"},{"label":"水分","value":"喜湿润，需充足浇水"},{"label":"土壤","value":"疏松肥沃、排水良好的壤土"},{"label":"主要用途","value":"庭园观赏、药园栽培与根茎入药"}],"facts":["闭鞘姜的叶鞘完全闭合包裹茎干，不像普通姜科植物那样叶鞘开裂。","它的花序层层叠叠像一座小宝塔，白色花冠配橙黄唇瓣非常醒目。","闭鞘姜的根状茎在民间入药，用于清热解毒、利水消肿。","它原产热带亚洲，在中国华南的溪边林下常成片生长。"]},"flower-venus-flytrap":{"description":"捕蝇草是一种小型多年生草本，叶柄扁平呈匙形，顶端特化为两片半圆形的捕虫夹。夹面内侧分布着感受毛，昆虫在短时间内触碰两根感受毛，夹子便会在不到一秒内闭合，边缘的齿状刺互相交错，把猎物困在其中；随后腺体分泌消化液，数天后吸收养分并重新张开。\n\n它只原产于美国北卡罗来纳州和南卡罗来纳州沿海的湿润贫瘠沼泽，那里土壤缺氮，食虫成为补充营养的重要方式。捕蝇草喜充足阳光、酸性泥炭土和湿润环境，冬季需要低温休眠。由于栖息地排水、采集和非法贸易，野生种群受到威胁；人工繁殖个体较为常见，但购买时应选择正规繁殖来源，避免购买野外采挖植株。","habitat":"美国东南部沿海的酸性泥炭沼泽、湿地边缘，喜阳光充足与潮湿","distribution":"原产美国北卡罗来纳州与南卡罗来纳州沿海，世界各地有栽培","conservation":"IUCN 易危（VU）；野生种群受贸易与栖息地丧失威胁","details":[{"label":"捕虫方式","value":"感受毛触发，夹状叶在约 0.1–0.5 秒内闭合"},{"label":"叶片","value":"叶柄扁平，顶端为两片捕虫夹"},{"label":"光照","value":"全日照至半日照，光照不足时夹子颜色变淡"},{"label":"土壤","value":"酸性、贫瘠的泥炭土或水苔"},{"label":"水分","value":"保持湿润，使用低矿物质水"},{"label":"休眠","value":"冬季需低温休眠，减少浇水"}],"facts":["捕蝇草需要连续触碰两根感受毛才闭合，可避免被雨滴等误触发。","每个捕虫夹通常只能开合数次，捕到大型猎物后可能腐烂发黑。","它原产地土壤极度贫瘠，食虫主要是为了补充氮和磷。"]},"flower-tropical-pitcher":{"description":"猪笼草是多年生藤本或半灌木，叶分为叶柄、叶片和卷须三部分，卷须末端膨大形成捕虫笼。笼口有光滑的唇，笼盖内侧和唇部会分泌蜜液，吸引蚂蚁、蝇类等昆虫；猎物停在光滑的唇上容易滑落，落入笼内的消化液中，被酶逐步分解吸收。不同种类的猪笼草捕虫笼形态差异很大，有的可容纳数升液体。\n\n猪笼草属广泛分布于东南亚、澳大利亚北部等热带地区，多生于贫瘠的泥炭沼泽、砂质坡地或云雾林。它们喜高温高湿、明亮散射光，根部需要透气基质。由于雨林开发与过度采集，部分种类濒危；常见种类已有大量人工繁殖。栽培时应避免向笼内投喂过多食物，并保持水质洁净。","habitat":"热带雨林、泥炭沼泽、砂质坡地与云雾林，喜高温高湿和散射光","distribution":"东南亚、澳大利亚北部及周边热带地区，中国华南有分布","conservation":"多数种类未评估；部分猪笼草属物种受保护，禁止野外采挖与贸易","details":[{"label":"捕虫结构","value":"叶片卷须末端形成瓶状捕虫笼"},{"label":"引诱方式","value":"笼唇与笼盖分泌蜜液，颜色和气味吸引昆虫"},{"label":"光照","value":"明亮散射光，避免烈日暴晒"},{"label":"温度","value":"热带种类适温 22–30℃"},{"label":"基质","value":"水苔、树皮、珍珠岩等透气贫瘠基质"},{"label":"水分","value":"保持基质湿润，使用低矿物质水"}],"facts":["猪笼草的捕虫笼由叶片卷须末端发育而来，是变态叶而非花。","笼内液体含有消化酶，也能吸引特定昆虫和微生物形成微型生态。","一些猪笼草与蚂蚁、树蛙形成共生关系，彼此受益。"]}});
